const e=[{id:1,icon:"Snowflake",accent:"#2563eb",title:"السلامة في فصل الشتاء",subtitle:"حماية النفس من البرد ومخاطر الشتاء",summary:"الشتاء فصلٌ جميل، لكنّ له مخاطره أيضًا: البرد والثلج والجليد والانزلاق والغاز السامّ المنبعث من المدافئ. علينا أن نعرف كيف نحمي أنفسنا وعائلاتنا.",blocks:[{heading:"تدفئة المنزل بأمان",body:`استخدم مدافئ الغاز والنفط الأبيض (الكيروسين) والكهرباء استخدامًا صحيحًا ووفق تعليمات الشركة المصنِّعة.
• اترك منفذًا للتهوية مفتوحًا في الغرفة، لأن مدافئ الغاز والنفط الأبيض تُنتج غاز أول أكسيد الكربون (CO) السامّ.
• لا تترك المدفأة مشتعلة أثناء النوم.`},{heading:"الوقاية من البرد",body:"ارتدِ ملابس دافئة على طبقات. غطِّ رأسك ويديك وقدميك جيدًا. وإذا كان الجو شديد البرودة، فلا تبقَ في الخارج مدة طويلة."},{heading:"القيادة الآمنة على الثلج والجليد",body:"قُد سيارتك ببطء على الثلج والجليد. زِد المسافة بين سيارتك والسيارة التي أمامك. استخدم إطارات شتوية أو سلاسل."},{heading:"منع تجمّد الأنابيب",body:"تتجمّد أنابيب المياه في البرد وتنفجر. لُفَّ الأنابيب الخارجية واعزلها. وفي الليالي شديدة البرودة، اترك الماء يجري ببطء وبكمية قليلة."}],tips:["ركّب جهاز إنذار لغاز أول أكسيد الكربون (CO) في المنزل.","أطفئ مدفأة الغاز قبل النوم.","ارتدِ الملابس على طبقات — فهي أفضل من قطعة ملابس واحدة سميكة.","احتفظ بحقيبة إسعافات أولية وبطانية في السيارة.","احرص على أن يكون هاتفك المحمول مشحونًا بالكامل عند خروجك."],warnings:["لا تضع المدفأة بالقرب من الستائر والملابس.","أبعِد الأطفال عن المدفأة.","لا تسمح بتراكم كميات كبيرة من الثلج على سطح المنزل.","لا توصِل عدة مدافئ كهربائية بمقبس كهربائي واحد."],activity:{prompt:"أنت في المنزل ومدفأة الغاز مشتعلة. أحد أفراد العائلة يشكو من صداع ويشعر بالدوار. ماذا ستفعل؟",options:[{text:"أُخرج الجميع فورًا إلى الهواء الطلق (وأطفئ المدفأة في طريقي فقط إذا كان ذلك سريعًا وآمنًا)، وأتصل بالرقم 122 حتى لو بدأوا يشعرون بتحسّن، ولا يعود أحد إلى الداخل حتى تتم تهوية الغرفة وفحص المدفأة",correct:!0,feedback:"قد يكون الصداع والدوار قرب مدفأة الغاز علامةً على التسمّم بغاز CO، لذا يأتي الهواء الطلق والاتصال بالرقم 122 أولًا."},{text:"أعطيه دواءً للصداع وأترك المدفأة مشتعلة",correct:!1,feedback:"لا يفيد قرص الدواء إذا كانت المدفأة تُطلق غاز CO؛ أخرِج الجميع إلى الهواء الطلق واتصل بالرقم 122."},{text:"أطفئ المدفأة فقط ونبقى في الغرفة",correct:!1,feedback:"إطفاء المدفأة وحده لا يكفي: فالغاز السامّ يبقى في الغرفة، لذا يجب أن يخرج الجميع إلى الهواء الطلق."},{text:"لا أفعل شيئًا وأنتظر",correct:!1,feedback:"الانتظار خطير: فالغاز يستمر في التراكم، لذا أخرِج الجميع إلى الهواء الطلق واتصل بالرقم 122."}]},quiz:[{question:"لماذا يجب أن يبقى منفذ للتهوية مفتوحًا في الغرفة عندما تكون مدفأة الغاز مشتعلة؟",options:[{text:"لكي تصبح رائحة الغرفة طيبة",correct:!1},{text:"لمنع تراكم غاز أول أكسيد الكربون (CO) السامّ",correct:!0},{text:"لكي لا تبرد الغرفة",correct:!1},{text:"لكي لا يصدر صوت",correct:!1}],explanation:"تُنتج مدافئ الغاز والنفط الأبيض غاز أول أكسيد الكربون (CO) السامّ، ويمنع منفذ التهوية المفتوح تراكمه في الغرفة."},{question:"أيّ الملابس أفضل للوقاية من البرد؟",options:[{text:"قطعة ملابس واحدة سميكة",correct:!1},{text:"ملابس على طبقات",correct:!0},{text:"ملابس خفيفة",correct:!1},{text:"لا يوجد فرق",correct:!1}],explanation:"الملابس الدافئة على طبقات تحمي أفضل من قطعة واحدة سميكة. وغطِّ رأسك ويديك وقدميك جيدًا أيضًا."},{question:"كيف نمنع تجمّد أنابيب المياه؟",options:[{text:"نلفّ الأنابيب، وفي الليالي شديدة البرودة نترك الماء يجري ببطء وبكمية قليلة",correct:!0},{text:"لا نفعل شيئًا",correct:!1},{text:"نُشعل نارًا تحت الأنابيب",correct:!1},{text:"نكسر الأنابيب",correct:!1}],explanation:"قد تتجمّد أنابيب المياه وتنفجر في البرد. لُفّ الأنابيب الخارجية واعزلها، وفي الليالي شديدة البرودة اترك الماء يجري ببطء وبكمية قليلة."}]},{id:2,icon:"Sun",accent:"#ea580c",title:"السلامة في فصل الصيف",subtitle:"حماية النفس من الحرّ وحرائق الغابات",summary:"الصيف فصلٌ حارّ تكتنفه مخاطر خاصة، مثل ضربة الشمس، واحتراق حقول الحبوب والمحاصيل، وحرائق الغابات، والغرق في المياه، وشحّ المياه. تعالَوا نتعلّم كيف نحمي أنفسنا.",blocks:[{heading:"الوقاية من ضربة الشمس (Heatstroke)",body:"اشرب الماء على مدار اليوم قبل أن تشعر بالعطش. لا تبقَ تحت أشعة الشمس في أشدّ أوقات النهار حرارة. ارتدِ ملابس خفيفة فاتحة اللون، واستخدم قبعة."},{heading:"الإنهاك الحراري أم ضربة الحرّ؟",body:`• الإنهاك الحراري (Heat exhaustion): تعرّق غزير، وجلد بارد شاحب رطب، وضعف، ودوار، وصداع، وغثيان، وعطش. انقل المصاب إلى مكان بارد، وأرخِ ملابسه، وبرّده بالماء، وأعطه رشفات من الماء إذا كان واعيًا تمامًا. اطلب المساعدة الطبية إذا تقيّأ، أو ساءت الأعراض أو استمرّت أكثر من ساعة، أو اضطرب وعيه (فهذه ضربة حرّ).
• ضربة الحرّ أو ضربة الشمس (Heatstroke): جسم شديد الحرارة مع اضطراب الوعي، أو سلوك غريب، أو تثاقل في الكلام، أو نوبة تشنّج، أو انهيار؛ وقد يكون الجلد حارًّا وجافًّا أو لا يزال متعرّقًا. وهذه حالة طارئة: اتصل بالرقم 122، وانقل المصاب إلى مكان بارد، وانزع الملابس الزائدة، وابدأ تبريده فورًا قبل نقله إلى المستشفى. وأفضل طريقة غمر الجسم حتى الرقبة في ماء بارد لمدة 15 دقيقة أو حتى يعود تفكيره واضحًا، أيّهما أسبق؛ وإن تعذّر ذلك فاستخدم دشًّا باردًا، ومناشف أو شراشف مبلّلة بماء بارد، وأكياس ثلج، مع التهوية بالمروحة. ولا تعطِ المصاب المضطرب الوعي شيئًا ليشربه.`},{heading:"الوقاية من حرائق الغابات",body:"لا تُشعل النار في الغابات وبين الأعشاب الجافة. لا ترمِ أعقاب السجائر. لا تترك الزجاجات في العراء، لأنها قد تعمل عمل العدسة فتُركّز أشعة الشمس وتُشعل النار."},{heading:"السلامة في البحيرات والأنهار",body:"لا تذهب للسباحة وحدك. اسبح فقط في الأماكن الآمنة وتحت المراقبة. ارتدِ سترة النجاة (Life jacket). لا تُبعد نظرك عن الأطفال."},{heading:"حفظ الطعام والماء",body:"يفسد الطعام بسرعة في الصيف. احفظ الطعام في الثلاجة. اشرب ماءً نظيفًا. اغسل الفواكه والخضراوات جيدًا."}],tips:["اشرب الماء على مدار اليوم — 2 لتر أو أكثر في أغلب الأحيان.","لا تبقَ تحت أشعة الشمس وقت الظهيرة وبعد الظهر، حين تكون الحرارة في أعلى مستوياتها.","استخدم كريم الوقاية من الشمس (SPF 30+).","تناول الفواكه الغنية بالماء (مثل البطيخ والشمّام).","لا تترك الأطفال والحيوانات وحدهم في سيارة حارّة."],warnings:["ضربة الشمس قد تكون قاتلة — أكثِر من شرب الماء وابقَ في الظل.","تنتشر النار في الغابات بسرعة كبيرة.","الغرق في المياه — لا تترك الأطفال دون مراقبة.","الطعام الفاسد يسبّب التسمّم."],activity:{prompt:"أنت في الخارج وتشعر بالدوار والضعف. أصبح جسمك حارًّا جدًّا. ماذا ستفعل؟",options:[{text:"أنتقل إلى مكان ظليل، وأشرب الماء، وأبرّد جسمي بالماء البارد، وأتصل بالرقم 122",correct:!0,feedback:"الدوار والضعف وارتفاع حرارة الجسم كثيرًا علامات تحذير من خطر الحرارة: انتقل إلى الظل، وبرّد جسمك، واتصل بالرقم 122."},{text:"أواصل عملي",correct:!1,feedback:"مواصلة العمل تزيد حرارة جسمك؛ توقّف، وانتقل إلى مكان بارد، وبرّد جسمك، واتصل بالرقم 122."},{text:"أبقى تحت الشمس وأشرب الماء المثلّج فقط",correct:!1,feedback:"البقاء تحت الشمس يزيد حرارة جسمك؛ انتقل إلى الظل وبرّد جسمك بالماء."},{text:"أستلقي تحت الشمس وأنام",correct:!1,feedback:"الاستلقاء تحت الشمس يرفع حرارة جسمك أكثر؛ انتقل إلى مكان بارد، وبرّد جسمك، واتصل بالرقم 122."}]},quiz:[{question:"لماذا لا ينبغي أن نترك زجاجات الماء في الخارج تحت أشعة الشمس؟",options:[{text:"لأن الماء يسخن",correct:!1},{text:"لأنها قد تُشعل النار كما تفعل العدسة",correct:!0},{text:"لأن الزجاج ينكسر",correct:!1},{text:"لا يوجد فرق",correct:!1}],explanation:"قد تعمل الزجاجة عمل العدسة فتُركّز أشعة الشمس وتُشعل النار. لا تترك الزجاجات في العراء."},{question:"كم ينبغي أن نشرب من الماء في الصيف؟",options:[{text:"نصف لتر يكفي",correct:!1},{text:"1 لتر يكفي",correct:!1},{text:"على مدار اليوم، 2 لتر أو أكثر",correct:!0},{text:"فقط عندما نشعر بالعطش",correct:!1}],explanation:"اشرب الماء على مدار اليوم، عادةً 2 لتر أو أكثر، وقبل أن تشعر بالعطش؛ فهذا يساعد على وقايتك من ضربة الشمس."},{question:"في أيّ وقت من النهار تكون الحرارة والمخاطر أكبر في فصل الصيف؟",options:[{text:"الصباح الباكر",correct:!1},{text:"الظهيرة وما بعد الظهر",correct:!0},{text:"المساء",correct:!1},{text:"الليل",correct:!1}],explanation:"تبلغ الحرارة ذروتها وقت الظهيرة وبعد الظهر، لذا لا تبقَ تحت أشعة الشمس في تلك الساعات."}]},{id:3,icon:"Home",accent:"#059669",title:"السلامة في المنزل",subtitle:"حماية العائلة من المخاطر داخل المنزل",summary:"ينبغي أن يكون المنزل مكانًا آمنًا للعائلة، لكنّ فيه مخاطر كثيرة، مثل الحريق والكهرباء والغاز والسقوط والتسمّم. تعالَوا نتعلّم كيف نجعل منزلنا آمنًا.",blocks:[{heading:"السلامة من الحريق ومطفأة الحريق",body:`ركّب جهاز إنذار الدخان واختبره مرة كل شهر. ضع مطفأة حريق بالقرب من المطبخ. أنواع مطفآت الحريق (حسب فئات NFPA):
• الماء: للخشب والورق والقماش (الفئة A).
• CO₂: للأجهزة الكهربائية (الفئة C).
• مسحوق ABC: للفئات A وB وC، لكن ليس لزيت الطبخ ولا للمعادن.
• الرغوة (Foam): للسوائل القابلة للاشتعال (الفئة B).
• لا تصبّ الماء أبدًا على الزيت المشتعل!

لا تستخدم المطفأة إلا إذا تحقّق كل ما يلي: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب. طريقة PASS: اسحب مسمار الأمان (Pull)، ووجّه فوهة الخرطوم نحو قاعدة النار (Aim)، واضغط على المقبض بقوة (Squeeze)، وحرّك الخرطوم يمينًا ويسارًا (Sweep). حدّد طريق الخروج من المنزل في حالات الطوارئ.`},{heading:"السلامة الكهربائية والمولّدات",body:`حافظ على سلامة المقابس والأسلاك الكهربائية. أصلِح الأسلاك المقطوعة أو التالفة أو استبدلها. لا تلمس الأجهزة الكهربائية بيدين مبتلّتين. لا توصِل أجهزة كثيرة بمقبس متعدد واحد.

المولّدات: شغّل المولّد في الخارج فقط، على بعد 6 أمتار (20 قدمًا) على الأقل من النوافذ والأبواب وفتحات التهوية — ولا تشغّله أبدًا داخل المنزل أو المرآب أو القبو أو المحل أو المخزن، حتى لو كانت الأبواب والنوافذ مفتوحة. ركّب في المنزل جهاز إنذار لأول أكسيد الكربون (CO) يعمل بالبطارية. ولا توصِل المولّد أبدًا بمقبس الجدار أو بأسلاك كهرباء المنزل: فقد يصعق الجيران وعمال الكهرباء. ولا يوصله إلا كهربائي مختص عبر مفتاح تحويل (Transfer Switch).`},{heading:"السلامة من الغاز",body:"افحص أنابيب الغاز وأسطواناته بانتظام. إذا شممت رائحة الغاز: لا تُشغّل أيّ مفتاح كهربائي ولا تُطفئه، ولا تُشعل النار، ولا تستخدم الهاتف داخل المنزل، ولا تشغّل مولّدًا أو سيارة في مكان قريب. افتح النوافذ والأبواب في طريقك إلى الخارج إن استطعت. لا تُغلق صمّام الغاز إلا إذا كان قريبًا ويمكن الوصول إليه بأمان، دون الدخول إلى المكان الذي تجمّع فيه الغاز؛ وإلا فلا تقترب منه. اخرج من المنزل، ونبّه الآخرين، واتصل بالرقم 115 من خارج المنزل."},{heading:"الوقاية من السقوط",body:"ركّب درابزينًا للسلالم. لا تترك الأغراض على الأرض وعلى السلالم. احرص على أن تكون إضاءة السلالم جيدة. نظّف الماء المسكوب على الأرض فورًا."}],tips:["اختبر جهاز إنذار الدخان مرة كل شهر.","لا توصِل أجهزة كثيرة بالمقابس المتعددة.","احفظ الأدوية والمواد الكيميائية في مكان مغلق وبعيد عن متناول الأطفال.","أبقِ طريق الخروج في حالات الطوارئ مفتوحًا دائمًا.","اكتب أرقام الطوارئ (115، 122، 104) في مكان ظاهر."],warnings:["لا تترك الأطفال وحدهم في المطبخ.","ضع الأشياء الزجاجية والحادّة في مكان مرتفع وبعيد عن الأطفال.","اجعل النوافذ والشرفات آمنة للأطفال.","اللعب بالنار والكهرباء قد يكون قاتلًا."],activity:{prompt:"تشمّ رائحة غاز في المطبخ. ماذا ستفعل؟",options:[{text:"أفتح النوافذ في طريقي إلى الخارج، ولا أُغلق صمّام الغاز إلا إذا أمكن الوصول إليه بأمان، وأخرج من المنزل، وأتصل بالرقم 115 من الخارج",correct:!0,feedback:"لا تستخدم أيّ مفتاح أو لهب، وتفتح النوافذ في طريقك، ولا تُغلق الصمّام إلا إذا كان ذلك آمنًا، وتتصل بالرقم 115 من الخارج."},{text:"أُشعل الضوء لأرى مكان تسرّب الغاز",correct:!1,feedback:"إشعال الضوء قد يُشعل الغاز؛ لا تلمس أيّ مفتاح واخرج من المنزل."},{text:"أُشغّل مصباح الهاتف المحمول داخل المنزل",correct:!1,feedback:"استخدام الهاتف داخل المنزل قد يُشعل الغاز؛ اخرج أولًا واتصل بالرقم 115 من الخارج."},{text:"أنتظر حتى تزول رائحة الغاز",correct:!1,feedback:"يستمر الغاز في التراكم بينما تنتظر؛ اخرج، ونبّه الآخرين، واتصل بالرقم 115 من الخارج."}]},quiz:[{question:"كم مرة يجب أن نختبر جهاز إنذار الدخان؟",options:[{text:"مرة كل 5 سنوات",correct:!1},{text:"مرة كل شهر",correct:!0},{text:"أبدًا",correct:!1},{text:"عند الشراء فقط",correct:!1}],explanation:"اختبر جهاز إنذار الدخان كل شهر لتتأكّد من أنه سينبّهك إذا اندلع حريق."},{question:"ماذا نفعل عندما نشمّ رائحة غاز في المنزل؟",options:[{text:"نُشعل الأضواء الكهربائية",correct:!1},{text:"نفتح النوافذ في طريقنا إلى الخارج، ولا نُغلق صمّام الغاز إلا إذا كان الوصول إليه آمنًا، ونخرج",correct:!0},{text:"نُشعل سيجارة",correct:!1},{text:"ننتظر حتى تزول الرائحة",correct:!1}],explanation:"أيّ مفتاح أو لهب قد يُشعل الغاز. افتح النوافذ في طريقك إلى الخارج، ولا تُغلق الصمّام إلا إذا كان قريبًا ويمكن الوصول إليه بأمان، ثم اتصل بالرقم 115 من الخارج."},{question:"لماذا لا يجوز لمس الكهرباء بيدين مبتلّتين؟",options:[{text:"لأن اليدين تتّسخان",correct:!1},{text:"لأن الماء يوصل الكهرباء ويسبّب صعقة كهربائية",correct:!0},{text:"لأن الكهرباء تنقطع",correct:!1},{text:"لا يوجد فرق",correct:!1}],explanation:"الماء يوصل الكهرباء، لذا فإن لمس الأجهزة الكهربائية بيدين مبتلّتين قد يسبّب لك صعقة كهربائية."}]},{id:4,icon:"HeartPulse",accent:"#dc2626",title:"أساسيات الإسعافات الأولية",subtitle:"إجراءات أولية لإنقاذ الحياة حتى وصول سيارة الإسعاف",summary:"يمكن للإسعافات الأولية أن تُنقذ حياة إنسان. إذا أُصيب شخص ما، أو توقّف قلبه، أو عجز عن التنفّس، فبإمكانك مساعدته حتى تصل سيارة الإسعاف. الإجراء الأول: اتصل بالرقم 122.",blocks:[{heading:"الإنعاش القلبي الرئوي (CPR) للبالغين",body:`عندما يتوقّف قلب شخص ما (يفقد الوعي ولا يتنفّس، أو لا يتنفّس بصورة طبيعية):
1. تأكّد من أن المكان آمن لك.
2. هزّ كتفيه واسأله بصوت عالٍ: «هل أنت بخير؟»
3. إذا لم يستجب، فاتصل بالرقم 122 وأرسل شخصًا ليُحضر جهاز إزالة الرجفان الخارجي الآلي (AED).
4. اضغط 30 ضغطة على منتصف الصدر: بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة.
5. إذا كنت مدرّبًا، فأعطِ نفَسَي إنقاذ (أمِل الرأس إلى الخلف، وارفع الذقن، وأغلق الأنف). وإذا لم تكن مدرّبًا أو لم ترغب في إعطاء أنفاس الإنقاذ، فاكتفِ بالضغطات الصدرية (Hands-Only CPR) دون توقّف.
6. كرّر 30:2 (أو الضغطات وحدها) حتى يصل فريق الإسعاف.

• جهاز AED: إذا كان متوفرًا، فشغّله فورًا واتّبع التعليمات الصوتية للجهاز.`},{heading:"النزيف — إيقاف الدم",body:`• الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط عليه بقوة. لا ترفع يدك حتى يتوقّف النزيف.
• إذا تشبّعت قطعة القماش بالدم، فلا تُزِلها؛ بل ضع قطعة أخرى فوقها وواصل الضغط.
• العاصبة (تورنيكيه): في حالة النزيف الشديد جدًّا من الذراع أو الساق، اربطها على بُعد 5-7 سم فوق الجرح (وليس على الركبة أو المرفق) وشدّها حتى يتوقّف النزيف. سجّل وقت وضعها ولا تُرخِها أبدًا.
• إذا كان هناك جسم مغروس في الجرح، فلا تُخرجه! اضغط حوله واتصل بالرقم 122.`},{heading:"الحروق — الإسعافات الأولية",body:`• الحرق البسيط: صُبّ الماء البارد الجاري على الحرق فورًا لمدة 20 دقيقة (لا ثلج ولا ماء شديد البرودة).
• لا تفقأ فقاعات الحرق، ولا تضع عليه الزبدة أو الزيت أو معجون الأسنان.
• بعد التبريد، غطِّ الحرق برفق بقطعة قماش نظيفة أو بغلاف بلاستيكي للطعام.
• الحرق الشديد أو الواسع: اتصل بالرقم 122. إذا كانت الملابس ملتصقة بالجلد، فلا تنزعها. حافظ على دفء جسم المصاب.`},{heading:"الاختناق بجسم غريب (Choking)",body:`العلامات: لا يستطيع الشخص الكلام أو السعال أو التنفّس، ويُمسك حلقه بيديه.
• البالغون والأطفال (من عمر سنة واحدة فما فوق): وجّه 5 ضربات بكعب راحة اليد بين لوحَي كتفيه. ثم 5 ضغطات بطنية (Heimlich): قف خلفه، وضع قبضتك فوق السرّة بقليل وأسفل عظمة القصّ بمسافة كافية، واضغط بسرعة نحو الداخل وإلى الأعلى. كرّر 5+5.
• الرضيع (أقل من سنة واحدة): ضع الرضيع على ساعدك، ووجهه إلى الأسفل ورأسه أخفض من صدره، ووجّه 5 ضربات على ظهره. ثم اقلبه على ظهره واضغط 5 ضغطات على منتصف الصدر بكعب راحة يد واحدة. لا تُجرِ أبدًا ضغطات بطنية للرضّع.
• إذا فقد الوعي، فاتصل بالرقم 122 وابدأ الإنعاش القلبي الرئوي (CPR).`}],tips:["اتصل دائمًا بالرقم 122 أولًا.","استخدم القفّازات إن توفّرت.","احتفظ بحقيبة إسعافات أولية في المنزل وفي السيارة.","التحق بدورة في الإسعافات الأولية.","الوقت مهم — ابدأ المساعدة بسرعة."],warnings:["قبل كل شيء، تحقّق من سلامتك أنت.","إذا سقط شخص من مكان مرتفع، فلا تحرّكه (فقد تكون رقبته أو ظهره مصابًا)، إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR).","لا تضع أيّ شيء في فم الشخص فاقد الوعي.","لا تلمس الجرح بيدين متّسختين."],activity:{prompt:"اختنق شخص في المنزل بجسم ما ولا يستطيع الكلام أو التنفّس. ماذا ستفعل؟",options:[{text:"أوجّه 5 ضربات على ظهره، ثم 5 ضغطات بطنية (Heimlich)، وأكرّر ذلك",correct:!0,feedback:"مَن لا يستطيع الكلام أو التنفّس مختنق اختناقًا تامًّا؛ و5 ضربات على الظهر ثم 5 ضغطات بطنية، مع التكرار، قد تُخرج الجسم العالق."},{text:"أعطيه ماءً ليشربه",correct:!1,feedback:"شرب الماء ليس علاجًا للاختناق: وجّه 5 ضربات على الظهر، ثم 5 ضغطات بطنية، وكرّر ذلك."},{text:"أُدخل أصابعي عميقًا في فمه",correct:!1,feedback:"ليس هذا ما يعلّمه الدرس: وجّه 5 ضربات على الظهر، ثم 5 ضغطات بطنية، وكرّر ذلك."},{text:"أنتظر حتى يتحسّن",correct:!1,feedback:"مَن لا يستطيع التنفّس لا يحتمل الانتظار: ابدأ فورًا بضربات الظهر والضغطات البطنية."}]},quiz:[{question:"في الإنعاش القلبي الرئوي (CPR) للبالغين، ما نسبة الضغطات إلى الأنفاس؟",options:[{text:"10 ضغطات ونفَس واحد",correct:!1},{text:"30 ضغطة ونفَسان",correct:!0},{text:"15 ضغطة ونفَسان",correct:!1},{text:"50 ضغطة و5 أنفاس",correct:!1}],explanation:"الإنعاش القلبي الرئوي (CPR) للبالغين 30 ضغطة صدرية ثم نفَسان إذا كنت مدرّبًا. وإن لم تكن مدرّبًا، فاكتفِ بالضغطات (Hands-Only CPR) دون توقّف."},{question:"ماذا نفعل في حالة الحرق البسيط؟",options:[{text:"نضع عليه الثلج",correct:!1},{text:"نضع عليه الزبدة",correct:!1},{text:"ماء بارد جارٍ لمدة 20 دقيقة",correct:!0},{text:"نضع عليه النفط الأبيض",correct:!1}],explanation:"برّد الحرق البسيط بالماء البارد الجاري لمدة 20 دقيقة، ولا تضع عليه الثلج أو الزبدة أو الزيت أو أيّ مادة أخرى."},{question:"ما رقم الإسعاف؟",options:[{text:"115",correct:!1},{text:"122",correct:!0},{text:"104",correct:!1},{text:"911",correct:!1}],explanation:"في إقليم كوردستان، 122 هو رقم الإسعاف، و115 للدفاع المدني، و104 للشرطة."}]},{id:5,icon:"Backpack",accent:"#9333ea",title:"حقيبة الطوارئ",subtitle:"تجهيز حقيبة لحالات الطوارئ",summary:"حقيبة الطوارئ هي الحقيبة التي تحتوي على الأشياء الضرورية في حالات الطوارئ، مثل الزلزال أو الفيضان أو أيّ حادث آخر. ينبغي أن يكون لدى كل منزل حقيبة كهذه.",blocks:[{heading:"الماء والطعام",body:`• الماء: نحو 4 لترات لكل شخص يوميًّا، لمدة 3 أيام على الأقل (للشرب والنظافة).
• أطعمة معلّبة أو جافة لا تحتاج إلى طهي.
• البسكويت والتمر والحلويات.`},{heading:"المستلزمات الطبية",body:"ضمادات، وشاش نظيف للجروح، وشريط لاصق طبي، وقفّازات، ومقصّ، وملقط، والأدوية الخاصة بأفراد العائلة (إن وُجدت)."},{heading:"مستلزمات مهمة",body:"مصباح يدوي وبطاريات، وراديو صغير، وشاحن متنقّل (Power bank) لشحن الهاتف المحمول، وملابس إضافية، وبطانية، وصفّارة لطلب المساعدة."},{heading:"الوثائق والنقود",body:"نسخ من بطاقة الهوية وجواز السفر، وبعض النقود، وقائمة بالأرقام المهمة، ومفاتيح احتياطية."}],tips:["اختر حقيبة خفيفة يسهل حملها.","افحص محتويات الحقيبة مرة كل 6 أشهر، واستبدل ما انتهت صلاحيته من الماء والطعام.","ضع الحقيبة في مكان قريب من الباب يسهل الوصول إليه.","ضع فيها أشياء خاصة بكل فرد من أفراد العائلة (الأطفال، كبار السنّ، المرضى).","لا تنسَ الحيوانات الأليفة أيضًا."],warnings:["تأكّد من أن الماء والطعام يكفيان جميع أفراد العائلة.","لا تنسَ أدويتك.","ضع فيها هاتفًا محمولًا وشاحنًا.","النقود مهمة، لأن البطاقات المصرفية قد لا تعمل."],activity:{prompt:"بعد وقوع زلزال، يجب عليكم إخلاء المنزل بسرعة. حقيبة الطوارئ جاهزة في المنزل. ماذا ستفعل؟",options:[{text:"آخذ الحقيبة وأتوجّه إلى نقطة التجمع",correct:!0,feedback:"أخذ الحقيبة الجاهزة إلى نقطة التجمع يوفّر لك الماء والطعام والأدوية دون إضاعة الوقت."},{text:"أبحث لبعض الوقت لأجمع أشياء أخرى",correct:!1,feedback:"البحث عن أشياء أخرى يُضيّع الوقت في منزل قد يكون متضرّرًا؛ خذ الحقيبة الجاهزة واخرج."},{text:"أترك الحقيبة وأهرب فقط",correct:!1,feedback:"ترك الحقيبة يعني خسارة الماء والطعام والأدوية التي جهّزتها؛ فالحقيبة جاهزة، فخذها معك."},{text:"أبقى في المنزل وأنتظر",correct:!1,feedback:"يجب الإخلاء: البقاء في منزل قد يكون متضرّرًا أمر خطير، لذا خذ الحقيبة وتوجّه إلى نقطة التجمع."}]},quiz:[{question:"كم ينبغي أن يكون في حقيبة الطوارئ من الماء لكل شخص؟",options:[{text:"1 لتر يكفي",correct:!1},{text:"نحو 4 لترات يوميًّا، لمدة 3 أيام على الأقل",correct:!0},{text:"نصف لتر",correct:!1},{text:"لا يوجد فرق",correct:!1}],explanation:"جهّز نحو 4 لترات من الماء لكل شخص يوميًّا، لمدة 3 أيام على الأقل، للشرب والنظافة."},{question:"كم مرة ينبغي أن نفحص محتويات الحقيبة؟",options:[{text:"مرة كل 10 سنوات",correct:!1},{text:"مرة كل 6 أشهر",correct:!0},{text:"عند الشراء فقط",correct:!1},{text:"لا تحتاج إلى فحص أبدًا",correct:!1}],explanation:"افحص الحقيبة مرة كل 6 أشهر، واستبدل ما انتهت صلاحيته من الماء والطعام."},{question:"أيّ هذه الأشياء غير ضروري في حقيبة الطوارئ؟",options:[{text:"الماء",correct:!1},{text:"المصباح اليدوي",correct:!1},{text:"التلفاز",correct:!0},{text:"الأدوية",correct:!1}],explanation:"التلفاز غير ضروري؛ فالحقيبة تضمّ ما تحتاجه في الطوارئ: الماء والطعام والأدوية والمصباح اليدوي وراديو صغير."}]},{id:6,icon:"PhoneCall",accent:"#16a34a",title:"أرقام الطوارئ",subtitle:"معرفة الأرقام وكيفية الاتصال",summary:"معرفة أرقام الطوارئ قد تُنقذ الأرواح. ينبغي لكل شخص أن يحفظ هذه الأرقام عن ظهر قلب، وأن يعرف متى وكيف يتصل.",blocks:[{heading:"الأرقام الرئيسية في إقليم كوردستان",body:`• 115: الدفاع المدني (الحريق، الإنقاذ، انهيار المباني، الفيضانات، تسرّب الغاز والمواد الخطرة).
• 122: الإسعاف (الحالات الطبية الطارئة).
• 104: الشرطة.`},{heading:"كيفية الاتصال",body:"حافظ على هدوئك وتحدّث بوضوح. اذكر المكان الدقيق أولًا: الحيّ، والشارع، ومَعلمًا قريبًا، والطابق. ثم اذكر ما حدث، وعدد المصابين أو المحاصَرين، وأيّ خطر (انتشار النار، الغاز، الكهرباء، المواد الكيميائية). اذكر اسمك ورقم هاتفك. أجب عن الأسئلة، واتّبع تعليماتهم، ولا تُنهِ المكالمة حتى يطلبوا منك ذلك."},{heading:"متى نتصل بأيّ رقم",body:`• الحريق، أو الدخان، أو الانفجار، أو الانهيار، أو الفيضان، أو وجود شخص محاصَر: 115.
• الإصابات، أو المرض الشديد، أو وجود شخص فاقد الوعي: 122.
• السرقة، والتهديد، والحوادث الأمنية: 104.
• إذا اجتمع حريق أو حادث مع وجود مصابين: 115 و122.`},{heading:"العنوان الصحيح",body:"اذكر اسم الحيّ والشارع، والمعالم الواضحة القريبة (مسجد، مدرسة، متجر)، ورقم المنزل ولونه."}],tips:["احفظ الأرقام في هاتفك المحمول.","ضع قائمة بالأرقام في مكان ظاهر في المنزل.","علّم الأطفال هذه الأرقام.","علّم الأطفال عنوان المنزل.","احفظ عنوان منزلك بدقة."],warnings:["لا تُجرِ أبدًا مكالمات كاذبة أو على سبيل المزاح — فهي تؤخّر وصول المساعدة إلى من يحتاجون إليها.","لا تُشغل خط الطوارئ دون سبب — فحياة الآخرين في خطر.","حافظ على هدوئك وتحدّث بوضوح.","العنوان الصحيح مهم جدًّا."],activity:{prompt:"رأيت سيارة تصدم شخصًا في الشارع فأُصيب. ماذا ستفعل؟",options:[{text:"أتصل بالرقم 122، وأذكر العنوان، وأُبلغ عن حالة المصاب",correct:!0,feedback:"يحتاج المصاب إلى الإسعاف: والاتصال بالرقم 122 مع ذكر العنوان الدقيق وحالة المصاب يوصل المساعدة بسرعة."},{text:"أمضي في طريقي",correct:!1,feedback:"المضيّ في طريقك يترك المصاب بلا مساعدة؛ اتصل بالرقم 122 واذكر العنوان الدقيق."},{text:"أصوّر مقاطع فيديو",correct:!1,feedback:"التصوير لا يساعد المصاب ولا يحترمه؛ اتصل أولًا بالرقم 122 واذكر العنوان الدقيق."},{text:"أكتفي بالمشاهدة",correct:!1,feedback:"الاكتفاء بالمشاهدة لا يساعد ويُضيّع الوقت؛ اتصل فورًا بالرقم 122 واذكر العنوان الدقيق."}]},quiz:[{question:"ما رقم الدفاع المدني (الحريق والإنقاذ)؟",options:[{text:"122",correct:!1},{text:"104",correct:!1},{text:"115",correct:!0},{text:"911",correct:!1}],explanation:"115 هو رقم الدفاع المدني: الحريق والإنقاذ وانهيار المباني والفيضانات وتسرّب الغاز والمواد الخطرة. أما 122 فللإسعاف، و104 للشرطة."},{question:"عند الاتصال، ما المعلومات التي يجب أن تقدّمها؟",options:[{text:"اسمك فقط",correct:!1},{text:"المكان الدقيق أولًا، ثم ما حدث، وعدد المصابين أو المحاصَرين، وأيّ خطر، واسمك ورقم هاتفك",correct:!0},{text:"العنوان فقط",correct:!1},{text:"لا حاجة إلى أيّ معلومات",correct:!1}],explanation:"اذكر المكان الدقيق أولًا ليصل إليك المسعفون، ثم ما حدث، وعدد المصابين أو المحاصَرين، وأيّ خطر، واسمك ورقم هاتفك."},{question:"ما رقم الإسعاف؟",options:[{text:"115",correct:!1},{text:"122",correct:!0},{text:"104",correct:!1},{text:"100",correct:!1}],explanation:"122 هو رقم الإسعاف للإصابات والأمراض الخطيرة وفاقدي الوعي، و115 للدفاع المدني، و104 للشرطة."}]},{id:7,icon:"FireExtinguisher",accent:"#dc2626",title:"مطفأة الحريق — تدريب شامل",subtitle:"التعرّف على أنواع مطفآت الحريق وفئات الحريق وطريقة PASS",summary:"مطفأة الحريق (Fire Extinguisher) أداة أساسية لإخماد الحرائق الصغيرة في بدايتها. ينبغي لكل شخص بالغ في المنزل ومكان العمل أن يعرف كيف يستخدمها بسرعة وبطريقة صحيحة، لأن مطفآت الحريق اليدوية لا تعمل إلا بضع ثوانٍ. إذا كبرت النار، فاترك المطفأة، واخرج، واتصل بالرقم 115.",blocks:[{heading:"فئات الحريق (حسب NFPA)",body:`• الفئة A: المواد الصلبة العادية (الخشب، الورق، القماش).
• الفئة B: السوائل والغازات القابلة للاشتعال (البنزين، النفط الأبيض، الغاز). الماء يؤدي إلى انتشار السائل المشتعل.
• الفئة C: الأجهزة الكهربائية الموصولة بالتيار. لا تستخدم الماء أو الرغوة.
• الفئة D: المعادن القابلة للاشتعال (مثل المغنيسيوم). الماء يسبّب تفاعلًا عنيفًا وانفجارًا.
• الفئة K: زيوت الطبخ ودهونه. الماء ينثر الزيت الساخن فتنتشر نار كبيرة.`},{heading:"أنواع مطفآت الحريق",body:`الفئات مكتوبة بأحرف NFPA:
• الماء: للفئة A فقط.
• CO₂: للفئة B وللأجهزة الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). مداها قصير، ولا تصلح لحرائق الخشب والورق العميقة. أمسك المقبض فقط ولا تلمس فوهة الخرطوم — فهي تبرد كثيرًا وتحرق الجلد. وفي الغرفة الصغيرة اخرج بعد الاستخدام وهوِّ المكان، لأن CO₂ يطرد الأكسجين.
• مسحوق ABC: للفئات A وB وC. ليس للفئة D ولا للفئة K.
• الرغوة: للفئتين A وB. لا تستخدمها للأجهزة الكهربائية.
• العامل النظيف (Clean Agent): للأجهزة الحسّاسة مثل الحواسيب؛ وتختلف فئاته حسب الطراز، فاقرأ الملصق.
• المادة الكيميائية الرطبة (Wet Chemical): لزيت الطبخ (الفئة K).
• الفئة D: فقط مطفأة أو مادة يذكر ملصقها المعدن المشتعل.`},{heading:"طريقة PASS",body:`قبل استخدام المطفأة (يجب أن تكون كل الإجابات «نعم»):
• الحريق صغير وفي بدايته، مثل حريق في سلة مهملات أو مقلاة.
• المطفأة مناسبة لهذا النوع من الحريق.
• طريق الخروج خلفك، والنار ليست بينك وبين المخرج.
• تمّ إطلاق الإنذار: نُبِّه الآخرون واتُّصل بالرقم 115.
• أنت مدرَّب على استخدام المطفأة.
• لا يوجد دخان أو حرارة يمنعان خروجك.
• إذا لم تنطفئ النار فورًا، فتوقّف واخرج وأغلق الباب خلفك.

1. P = Pull (اسحب): اسحب مسمار الأمان.
2. A = Aim (وجِّه): وجِّه فوهة الخرطوم نحو قاعدة النار، لا نحو أعلاها.
3. S = Squeeze (اضغط): اضغط على مقبض المطفأة بقوة.
4. S = Sweep (حرِّك): حرِّك الخرطوم يمينًا ويسارًا حتى تنطفئ النار.

PASS هي الطريقة العامة لمعظم المطافئ اليدوية. أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعامل النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة.`},{heading:"فحص مطفأة الحريق",body:`الفحص البصري مرة كل شهر، يجريه الشخص المسؤول:
• أن تكون المطفأة في مكانها، ظاهرة وسهلة الوصول.
• أن يكون مسمار الأمان وختمه في مكانهما.
• أن يكون الملصق مقروءًا ومتّجهًا إلى الخارج.
• ألّا يكون الخرطوم مكسورًا أو مثقوبًا، وأن تكون الفوهة غير مسدودة.
• ألّا يكون جسم المطفأة صدئًا أو متضررًا أو يسرّب.
• إذا كان فيها مؤشر ضغط، أن يكون المؤشر في المنطقة الخضراء. مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة.

خدمة يجريها فنّي مؤهَّل:
• الفحص والصيانة (Maintenance): مرة كل سنة.
• إعادة التعبئة (Recharge): بعد أي استخدام، ولو كان قصيرًا.
• صيانة السنوات الست: تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار ضغط كل 12 سنة، ويُفحص داخلها كل 6 سنوات.
• اختبار ضغط جسم المطفأة (Hydrostatic test): كل 5 سنوات لمطافئ الماء والرغوة (AFFF) وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ؛ وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم.

موعد الاختبار ليس موعدًا للاستبدال. تُسحب المطفأة من الخدمة إذا فشلت في الفحص أو الاختبار، أو تضرّرت، أو صارت قديمة الطراز، أو استدعتها الشركة المصنّعة، أو لم يعد ملصقها مقروءًا، أو كانت من النوع غير القابل لإعادة التعبئة وتجاوزت مدة الخدمة المكتوبة على ملصقها. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك.`},{heading:"مخاطر خاصة في المنزل والمجتمع",body:`• المطبخ: زيت الطبخ من الفئة K — استخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical) أو غطاءً كبيرًا.
• الكهرباء: المقابس والأسلاك — الفئة C.
• موقد الغاز والأسطوانة: الغاز — الفئة B؛ والأولوية لإيقاف الغاز: يُغلق شخصٌ مؤهَّل صمّامَ الغاز فقط إذا كان الوصول إليه آمنًا. لا تُطفئ لهب الغاز إذا لم يمكن إيقاف الغاز بأمان: أخرِج الجميع واتصل بالرقم 115.
• البنزين والنفط الأبيض (الكيروسين): خزّنهما بعيدًا عن المنزل في مكان جيد التهوية.
• مطفأة ABC مناسبة لمعظم حرائق المنزل، لكنها ليست لزيت الطبخ (K) ولا للمعادن (D).`},{heading:"ألوان مطفآت الحريق (BS EN 3 وBS 7863)",body:`اللون ليس فئة الحريق. وفقًا للمعيار الأوروبي BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة:
• الكريمي = الرغوة.
• الأزرق = المسحوق الجاف.
• الأسود = CO₂.
• الأصفر = المادة الكيميائية الرطبة (Wet Chemical).
• الماء بلا شريط.

وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا.`},{heading:"الفئة F (زيت الطبخ) — هي نفسها الفئة K",body:`تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. لذا فالفئة F (EN 2) والفئة K (NFPA) فئة واحدة: حرائق زيوت الطبخ ودهونه.
• الزيت شديد السخونة قد يشتعل من تلقاء نفسه.
• مطفأة المادة الكيميائية الرطبة (Wet Chemical) هي المناسبة: فهي تُكوّن طبقة شبيهة بالصابون على سطح الزيت تعزل الأكسجين وتُبرّد الزيت.
• تحتاج المطاعم والمطابخ الكبيرة إلى مطفآت حريق من الفئة F/K.`}],tips:["يجب أن تتوفّر في كل منزل مطفأة ABC واحدة على الأقل.","ضع المطفأة بالقرب من باب المطبخ، لا داخل المطبخ بجوار الموقد.","درّب جميع أفراد العائلة البالغين على استخدام المطفأة.","افحص المطفأة مرة كل شهر؛ وإذا كان فيها مؤشر ضغط، فيجب أن يكون في المنطقة الخضراء (مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة).","لا تسحب مسمار الأمان إلا عند الحاجة.","ابدأ من المسافة المحددة على ملصق المطفأة أو في تعليمات الشركة المصنّعة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار.","اجعل ظهرك نحو باب الخروج — لكي يبقى طريق الهروب مفتوحًا دائمًا.","سلّم المطفأة مرة كل سنة إلى شخص مختصّ لإجراء الصيانة (Service).","لا تعمل مطفأة الحريق اليدوية إلا بضع ثوانٍ — كن مستعدًّا قبل أن تبدأ."],warnings:["لا تصبّ الماء أبدًا على الزيت المشتعل — ستنتشر نار كبيرة بسرعة!","لا تستخدم الماء أبدًا على الأجهزة الكهربائية — خطر الصعق الكهربائي!","لا تستخدم المطفأة إذا كانت النار أكبر من سلة مهملات، أو كانت تنتشر، أو كان الدخان يزداد: اخرج واتصل بالرقم 115!","وجِّه فوهة الخرطوم دائمًا نحو قاعدة النار — لا نحو أعلاها!","مطفأة CO₂: لا تلمس فوهة الخرطوم! فهي تبرد إلى نحو 78 درجة تحت الصفر وتحرق الجلد.","مسحوق ABC في غرفة مغلقة يحجب الرؤية ويُصعّب التنفّس — اخرج بعد استخدامه وافتح الأبواب والنوافذ."],activity:{prompt:"في مطبخ المنزل، اشتعلت النار في الزيت داخل المقلاة على الموقد! ماذا ستفعل؟",options:[{text:"أصبّ عليها الماء",correct:!1,feedback:"يتحوّل الماء إلى بخار في الزيت الساخن فينشر الزيت المشتعل في نار كبيرة؛ لا تصبّ الماء عليه أبدًا."},{text:"إذا كان ذلك آمنًا، أُطفئ الموقد وأضع عليها غطاءً كبيرًا لقطع الأكسجين، أو أستخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical)",correct:!0,feedback:"إطفاء الموقد وتغطية المقلاة يقطعان الأكسجين، ومطفأة المادة الكيميائية الرطبة مصمَّمة لزيت الطبخ."},{text:"أحمل المقلاة وأُخرجها إلى الخارج",correct:!1,feedback:"لا تحمل المقلاة المشتعلة؛ أطفئ الموقد إن كان ذلك آمنًا وضع عليها غطاءً كبيرًا."},{text:"أضربها بقطعة ملابس لتنطفئ",correct:!1,feedback:"ليس هذا ما يعلّمه الدرس: غطِّ المقلاة بغطاء كبير أو استخدم مطفأة المادة الكيميائية الرطبة."}]},quiz:[{question:"بأحرف NFPA، لأيّ فئات الحريق تصلح مطفأة CO₂؟",options:[{text:"A وD",correct:!1},{text:"B وC",correct:!0},{text:"A وK",correct:!1},{text:"D وK",correct:!1}],explanation:"بأحرف NFPA، تصلح مطفأة CO₂ للفئة B (السوائل القابلة للاشتعال) والفئة C (الأجهزة الكهربائية الموصولة بالتيار)، ولا تصلح لحرائق الخشب والورق العميقة ولا للمعادن (D) ولا لزيت الطبخ (K)."},{question:"في طريقة PASS، إلى أين يجب توجيه فوهة الخرطوم؟",options:[{text:"أعلى النار",correct:!1},{text:"قاعدة النار",correct:!0},{text:"حول النار",correct:!1},{text:"سقف الغرفة",correct:!1}],explanation:"في طريقة PASS، وجِّه الفوهة نحو قاعدة النار لا نحو أعلى اللهب، وحرّكها يمينًا ويسارًا حتى تنطفئ النار."},{question:"لماذا لا يُصبّ الماء على حريق الزيت (الفئة K)؟",options:[{text:"لأنه لا تأثير له",correct:!1},{text:"لأن الماء يتحوّل بسرعة إلى بخار فينثر الزيت الساخن وتنتشر نار كبيرة",correct:!0},{text:"لأن الزيت يمتصّ الماء",correct:!1},{text:"لأن الماء نفسه يحترق",correct:!1}],explanation:"يتحوّل الماء فورًا إلى بخار داخل الزيت الساخن فينثر الزيت المشتعل وتنتشر نار كبيرة. استخدم بدلًا منه غطاءً كبيرًا أو مطفأة المادة الكيميائية الرطبة."},{question:"أيّ مطفأة تناسب معظم حرائق المنزل (الفئات A وB وC)؟",options:[{text:"مطفأة الماء",correct:!1},{text:"مطفأة CO₂",correct:!1},{text:"مطفأة مسحوق ABC",correct:!0},{text:"مطفأة الرغوة",correct:!1}],explanation:"يغطّي مسحوق ABC الفئات A وB وC، لذا يناسب معظم حرائق المنزل، لكنه لا يصلح لزيت الطبخ (K) ولا للمعادن (D)."},{question:"وفق ترميز الألوان البريطاني (BS EN 3 مع BS 7863)، ما لون الشريط على مطفأة المادة الكيميائية الرطبة (Wet Chemical) الخاصة بزيت الطبخ؟",options:[{text:"أحمر",correct:!1},{text:"أسود",correct:!1},{text:"أصفر",correct:!0},{text:"أزرق",correct:!1}],explanation:"في الترميز البريطاني يدلّ الشريط الأصفر على المادة الكيميائية الرطبة. واللون ليس فئة الحريق أبدًا، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق دائمًا."},{question:"وفقًا لـ NFPA 10، كم مرة يجب أن يُجري شخص مختصّ الصيانة (Maintenance) لمطفأة الحريق؟",options:[{text:"كل أسبوع",correct:!1},{text:"مرة كل سنة، مع فحص بصري كل شهر",correct:!0},{text:"مرة كل 20 سنة",correct:!1},{text:"لا تحتاج إلى فحص",correct:!1}],explanation:"يُجري الشخص المسؤول فحصًا بصريًّا كل شهر، ويُجري فنّي مؤهَّل الفحص والصيانة مرة كل سنة، ويعيد تعبئة المطفأة بعد أيّ استخدام."}]},{id:8,icon:"Heart",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"تدريب شامل على الإسعافات الأولية وإنعاش القلب",summary:"الإسعافات الأولية (First Aid) هي المساعدة المبدئية التي تُقدَّم للشخص المصاب أو المريض قبل وصول الفريق الطبي. ينبغي لكل فرد في المجتمع أن يعرف كيف يُجري الإنعاش القلبي الرئوي (CPR)، ويوقف النزيف، ويحمي المصاب حتى تصل سيارة الإسعاف. هذا الدرس قد يحمي حياتك وحياة عائلتك.",blocks:[{heading:"الإنعاش القلبي الرئوي (CPR)",body:`1. تحقّق من سلامة المكان.
2. هزّ كتفي المصاب واسأله: «هل أنت بخير؟»
3. إذا لم يستجب ولم يكن يتنفّس بصورة طبيعية، فاتصل بالرقم 122 واطلب جهاز إزالة الرجفان الخارجي الآلي (AED).
4. اضغط 30 ضغطة على منتصف الصدر: بمعدل 100-120 ضغطة في الدقيقة، وبعمق 5-6 سم لجميع البالغين.
5. إذا كنت مدرّبًا ومستعدًّا، فأعطِ نفَسين، مدة كل منهما ثانية واحدة. وإذا لم تكن مدرّبًا أو لم ترغب في إعطاء أنفاس الإنقاذ، فاكتفِ بالضغطات الصدرية (Hands-Only CPR) دون توقّف.
6. واصل 30:2 (أو الضغطات وحدها) حتى يصل فريق الإسعاف.
7. إذا توفّر جهاز AED، فاستخدمه فورًا.`},{heading:"إيقاف النزيف",body:`• الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط عليه بقوة.
• إذا تشبّعت قطعة القماش بالدم، فلا تُزِلها؛ بل ضع قطعة أخرى فوقها وواصل الضغط.
• العاصبة (تورنيكيه): في حالة النزيف الشديد جدًّا من الذراع أو الساق، اربطها على بُعد 5-7 سم فوق الجرح، وسجّل وقت وضعها، ولا تُرخِها أبدًا.
• لا تُخرج الجسم المغروس في الجرح!`},{heading:"علاج الحروق",body:`• الحروق الحرارية: ماء بارد جارٍ لمدة 20 دقيقة.
• الحروق الكيميائية: اغسلها بكمية كبيرة من الماء، لمدة 20 دقيقة على الأقل.
• الحروق الكهربائية: الإجراء الأول هو قطع التيار الكهربائي! ثم اتصل بالرقم 122.
• لا تفقأ فقاعات الحرق، ولا تستخدم الزبدة أو الزيت أو معجون الأسنان.`},{heading:"الكسور والسقوط",body:`• لا تحرّك الطرف المصاب — ثبّته بعصا أو لوح خشبي (جبيرة - Splint).
• لا تحرّك الشخص الذي سقط من مكان مرتفع: فقد تكون رقبته أو ظهره مصابًا. أبقِه ثابتًا واتصل بالرقم 122. لا تحرّكه إلا إذا كان المكان خطرًا (حريق، أو حركة مرور، أو انهيار، أو غاز، أو ارتفاع المياه)، مع إبقاء الرأس والرقبة والظهر على خط واحد. وإذا احتاج إلى الإنعاش القلبي الرئوي (CPR)، فمدّده على ظهره على سطح صلب. ولا تضعه على جنبه في وضعية الإفاقة.
• لُفَّ الثلج بقطعة قماش وضعه على التورّم.`},{heading:"الصعقة الكهربائية",body:`• اقطع التيار الكهربائي فورًا! لا تلمس المصاب قبل قطع التيار.
• إذا لم تستطع قطع التيار (في كهرباء المنازل فقط)، فأبعِد السلك عن المصاب بعصا خشبية جافة.
• اتصل بالرقم 122؛ إذ يجب أن يخضع كل من تعرّض لصعقة كهربائية لفحص طبي.`},{heading:"الاختناق بجسم غريب — مناورة هايمليك (Heimlich)",body:`إذا كان الشخص لا يستطيع الكلام أو السعال أو التنفّس، ويُمسك حلقه بيديه، فهو مختنق بجسم غريب.
• وجّه 5 ضربات بكعب راحة اليد بين لوحَي كتفيه.
• 5 ضغطات بطنية (Heimlich): قف خلفه، وضع قبضتك فوق السرّة بقليل وأسفل عظمة القصّ بمسافة كافية، وأمسكها باليد الأخرى، واضغط بسرعة نحو الداخل وإلى الأعلى.
• واصل 5+5 حتى يخرج الجسم أو يفقد الشخص وعيه؛ فإذا فقد وعيه، فاتصل بالرقم 122 وابدأ الإنعاش القلبي الرئوي (CPR).
• الرضيع (أقل من سنة واحدة): 5 ضربات على الظهر (ورأسه أخفض من صدره) و5 ضغطات على الصدر. لا تُجرِ أبدًا ضغطات بطنية للرضّع.`},{heading:"وضعية الإفاقة (Recovery Position)",body:`إذا كان الشخص فاقدًا للوعي لكنه يتنفّس بصورة طبيعية، ولم يُشتبه في إصابة رقبته أو ظهره، فضعه في وضعية الإفاقة:
1. ضع ذراعه القريبة منك بزاوية قائمة باتجاه الرأس.
2. ضع ذراعه البعيدة على صدره، واجعل ظهر يده تحت خدّه.
3. ارفع ركبة ساقه البعيدة.
4. أمسك الركبة والكتف، واقلبه نحوك على جانبه.
5. أمِل رأسه قليلًا إلى الخلف ليبقى مجرى الهواء مفتوحًا.

• اتصل بالرقم 122 وراقب تنفّسه حتى تصل سيارة الإسعاف.`}],tips:["يجب أن تتوفّر في كل منزل حقيبة إسعافات أولية.","ضع قائمة أرقام الطوارئ في مكان ظاهر.","علّم جميع أفراد العائلة الإنعاش القلبي الرئوي (CPR) ومناورة هايمليك (Heimlich).","احرص على وجود قماش نظيف وعاصبة (تورنيكيه) ومقصّ في الحقيبة.","الرقم 122 متاح دائمًا — لا تخف واتصل.","الدماغ يتضرّر سريعًا دون أكسجين — ابدأ الإنعاش القلبي الرئوي (CPR) بسرعة.","لجميع البالغين، بمن فيهم كبار السنّ، عمق الضغط 5-6 سنتيمترات — لا تُقلّله.","للمرأة الحامل أو الشخص شديد البدانة، عند الاختناق بجسم غريب، اضغط على منتصف الصدر لا على البطن."],warnings:["لا تلمس المصاب إذا لم يُقطع التيار الكهربائي!","لا تُخرج الجسم المغروس في الجرح!","لا تفقأ فقاعات الحرق!","لا تحرّك الشخص الذي سقط من مكان مرتفع، إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR)!","لا تستخدم الضغطات البطنية (Heimlich) للرضّع الذين تقلّ أعمارهم عن سنة واحدة!","واصل الإنعاش القلبي الرئوي (CPR) حتى يصل فريق الإسعاف — لا تتوقّف."],activity:{prompt:"اشتعلت النار في يد أحد أصدقائك وأُصيب بحرق كبير. ماذا ستفعل؟",options:[{text:"أضع على الحرق الزبدة أو الزيت",correct:!1,feedback:"لا تضع الزبدة أو الزيت على الحرق أبدًا؛ برّده بالماء البارد الجاري لمدة 20 دقيقة واتصل بالرقم 122."},{text:"أصبّ الماء البارد الجاري على الحرق لمدة 20 دقيقة وأتصل بالرقم 122",correct:!0,feedback:"الماء البارد الجاري لمدة 20 دقيقة يبرّد الحرق، والحرق الكبير يحتاج إلى الإسعاف (122)."},{text:"أفقأ فقاعات الحرق",correct:!1,feedback:"لا تفقأ فقاعات الحرق أبدًا؛ برّد الحرق بالماء البارد الجاري لمدة 20 دقيقة واتصل بالرقم 122."},{text:"لا أفعل شيئًا",correct:!1,feedback:"الحرق الكبير يحتاج إلى مساعدة فورية: برّده بالماء البارد الجاري لمدة 20 دقيقة واتصل بالرقم 122."}]},quiz:[{question:"في الإنعاش القلبي الرئوي (CPR)، كم ضغطة يجب أن تُعطى على الصدر في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"150 فأكثر",correct:!1}],explanation:"اضغط بقوة وبسرعة على منتصف الصدر: 100-120 ضغطة في الدقيقة، وبعمق 5-6 سم لجميع البالغين."},{question:"إذا كان هناك جسم حادّ مغروس في الجرح، فماذا ستفعل؟",options:[{text:"أُخرجه",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"أتركه وأمضي في طريقي",correct:!1},{text:"أغسله بالماء وأُخرجه",correct:!1}],explanation:"لا تُخرج الجسم المغروس في الجرح: اتركه في مكانه، واضغط حوله، واتصل بالرقم 122."},{question:"إذا تعرّض شخص لصعقة كهربائية، فما الإجراء الأول؟",options:[{text:"أُمسك بيده",correct:!1},{text:"أبدأ الإنعاش القلبي الرئوي (CPR) فورًا",correct:!1},{text:"أقطع التيار الكهربائي",correct:!0},{text:"أصبّ عليه الماء",correct:!1}],explanation:"اقطع التيار الكهربائي أولًا: فلمس المصاب قبل قطع التيار قد يصعقك أنت أيضًا. ثم اتصل بالرقم 122."},{question:"ما العلامة الرئيسية للاختناق التامّ بجسم غريب؟",options:[{text:"صوت عالٍ يصدر من الحلق",correct:!1},{text:"العجز عن الكلام والسعال والتنفّس، مع وضع اليدين على الحلق",correct:!0},{text:"سعال خفيف",correct:!1},{text:"صداع",correct:!1}],explanation:"في الاختناق التامّ لا يستطيع الشخص الكلام أو السعال أو التنفّس، ويُمسك حلقه بيديه. وجّه 5 ضربات على الظهر، ثم 5 ضغطات بطنية."},{question:"لمن تُستخدم وضعية الإفاقة (Recovery Position)؟",options:[{text:"الشخص فاقد الوعي الذي لا يزال يتنفّس بصورة طبيعية",correct:!0},{text:"الشخص فاقد الوعي الذي لا يتنفّس",correct:!1},{text:"الشخص الواعي المصاب بجرح بسيط",correct:!1},{text:"شخص سليم لا يعاني من أيّ مشكلة",correct:!1}],explanation:"وضعية الإفاقة للشخص فاقد الوعي الذي يتنفّس بصورة طبيعية ولا يُشتبه في إصابة رقبته أو ظهره. أما مَن لا يتنفّس فيحتاج إلى الإنعاش القلبي الرئوي (CPR)."}]},{id:9,icon:"CarFront",accent:"#2563eb",title:"السلامة المرورية",subtitle:"حماية النفس والعائلة على الطرق",summary:"تُعدّ الحوادث المرورية من أكبر أسباب الوفاة والإصابة. إن تعلّم قوانين المرور والالتزام بها قد يحمي حياتك. يتناول هذا الدرس سلامة المشاة والسائقين والأطفال.",blocks:[{heading:"سلامة المشاة",body:"امشِ دائمًا على الرصيف. قبل عبور الشارع، انظر إلى الاتجاهين واعبر من ممرّ المشاة. لا تنظر إلى هاتفك المحمول أثناء العبور. في الليل، ارتدِ ملابس فاتحة اللون أو ملابس عليها علامات عاكسة للضوء (Reflective)."},{heading:"سلامة القيادة",body:"اربط حزام الأمان دائمًا. لا تستخدم الهاتف المحمول أثناء القيادة. التزم بسرعة مناسبة ووفق القانون. استخدم في الشتاء إطارات مناسبة."},{heading:"الأطفال في السيارة",body:"أجلِس الأطفال دائمًا على مقعد الأطفال الخاص (Car seat) المناسب لأعمارهم وأوزانهم. يجلس الأطفال بعمر 12 سنة فما دون في المقاعد الخلفية. لا تترك الأطفال وحدهم في السيارة أبدًا."},{heading:"الدراجات النارية والهوائية",body:"ارتدِ خوذة الحماية (Helmet) دائمًا. في الليل، لا بدّ من الأضواء والعلامات العاكسة للضوء. ارتدِ قفّازات وأحذية مناسبة."}],tips:["اربط حزام الأمان دائمًا.","لا تستخدم الهاتف المحمول أثناء القيادة.","يجلس الأطفال في المقاعد الخلفية.","خوذة الحماية للدراجات النارية والهوائية."],warnings:["الهاتف المحمول + القيادة = خطر الموت.","السرعة + الثلج أو الجليد = حادث."],activity:{prompt:"أنت تقود السيارة ويرنّ هاتفك المحمول. وصلتك رسالة مهمة. ماذا ستفعل؟",options:[{text:"أواصل القيادة وأقرأ الرسالة",correct:!1,feedback:"الهاتف مع القيادة يعني خطر الموت؛ توقّف أولًا في مكان آمن ثم اقرأ الرسالة."},{text:"أتوقّف في مكان آمن على جانب الطريق ثم أردّ",correct:!0,feedback:"التوقّف أولًا في مكان آمن يتيح لك الردّ دون تعريض أحد على الطريق للخطر."},{text:"أستخدم الهاتف بيد واحدة",correct:!1,feedback:"استخدام الهاتف بيد واحدة يظلّ استخدامًا له أثناء القيادة؛ توقّف أولًا في مكان آمن."},{text:"أكتب الردّ بسرعة أثناء القيادة",correct:!1,feedback:"الكتابة أثناء القيادة من أخطر الأفعال؛ توقّف في مكان آمن ثم ردّ."}]},quiz:[{question:"الأطفال بعمر كم سنة فما دون يجب أن يجلسوا في المقاعد الخلفية للسيارة؟",options:[{text:"12 سنة",correct:!0},{text:"6 سنوات",correct:!1},{text:"18 سنة",correct:!1},{text:"لا يوجد فرق",correct:!1}],explanation:"يجب أن يجلس الأطفال بعمر 12 سنة فما دون في المقاعد الخلفية، في مقعد أطفال يناسب عمرهم ووزنهم."},{question:"أيّ هذه الأفعال يُعدّ من أخطر الأفعال أثناء القيادة؟",options:[{text:"استخدام الهاتف المحمول",correct:!0},{text:"ربط حزام الأمان",correct:!1},{text:"القيادة بالسرعة القانونية",correct:!1},{text:"التوقّف عند إشارة المرور الحمراء",correct:!1}],explanation:"لا تستخدم الهاتف أثناء القيادة: فالهاتف مع القيادة يعني خطر الموت. أما حزام الأمان والسرعة القانونية فيساعدان على حمايتك."},{question:"هل يجوز ترك الأطفال وحدهم في سيارةٍ متوقفة؟",options:[{text:"لا، ولا حتى لوقتٍ قصير",correct:!0},{text:"نعم، إذا كانت النوافذ مفتوحة قليلًا",correct:!1},{text:"نعم، لبضع دقائق",correct:!1},{text:"نعم، إذا كانت السيارة متوقفة في الظل",correct:!1}],explanation:"لا تترك الأطفال وحدهم في السيارة أبدًا، ولا حتى لوقتٍ قصير. وأجلِسهم دائمًا على مقعد الأطفال المناسب لأعمارهم وأوزانهم."}]},{id:10,icon:"LifeBuoy",accent:"#0891b2",title:"السلامة المائية والوقاية من الغرق",subtitle:"حماية النفس والأطفال بالقرب من المياه",summary:"وفقًا لمنظمة الصحة العالمية (WHO)، يُعدّ الغرق في المياه أحد الأسباب الرئيسية لوفاة الأطفال والشباب في العالم. وفي إقليم كوردستان، تكون البحيرات والسدود والأنهار خطيرة جدًّا في الصيف. إن تعلّم السلامة المائية ضروري لجميع العائلات.",blocks:[{heading:"الأطفال والماء",body:"لا تترك الأطفال وحدهم بالقرب من الماء أبدًا — فالطفل الصغير قد يغرق في كمية قليلة جدًّا من الماء (بضعة سنتيمترات، كما في دلو أو طست). وبالقرب من الأحواض والمياه، أبقِ عينيك عليهم دائمًا."},{heading:"السباحة بأمان",body:"اسبح فقط في الأماكن الرسمية وتحت المراقبة. ليكن معك شخص آخر دائمًا. اعرف عمق الماء قبل النزول إليه. ارتدِ سترة النجاة (Life jacket) في البحيرات والأنهار."},{heading:"الإنقاذ",body:`إذا كان شخص ما يغرق في الماء:
1. لا تنزل إلى الماء بنفسك!
2. مُدَّ إليه شيئًا أو ارمِه له (حبل، عصا، طوق نجاة).
3. اتصل بالرقمين 115 و122.
4. بعد إخراجه من الماء، افحص تنفّسه. إذا لم يكن يتنفّس بصورة طبيعية وكنت مدرّبًا، فابدأ الإنعاش القلبي الرئوي (CPR) مع أنفاس الإنقاذ: ففي الغرق يتوقّف التنفّس أولًا، ولذلك فأنفاس الإنقاذ هي الأهم. وإذا لم تكن مدرّبًا أو لم تستطع إعطاء أنفاس الإنقاذ، فاكتفِ بالضغطات الصدرية حتى وصول المساعدة.
5. كل من أُخرج من الماء يجب أن يفحصه طبيب، حتى لو بدا بخير، لأن مشكلات الرئة شائعة بعد ذلك.`}],tips:["لا تترك الأطفال وحدهم بالقرب من الماء.","ارتدِ سترة النجاة (Life jacket) في البحيرات والأنهار.","لا تنزل إلى الماء لإنقاذ أحد — ارمِ له شيئًا.","تعلّم الإنعاش القلبي الرئوي (CPR)."],warnings:["بضعة سنتيمترات من الماء تكفي لإغراق طفل صغير.","قد تكون مياه الأنهار والسدود في الإقليم شديدة التيار وباردة جدًّا، حتى لو بدت هادئة من السطح."],activity:{prompt:"أنت وعائلتك بالقرب من بحيرة. يريد طفلك الصغير أن ينزل إلى الماء. ماذا ستفعل؟",options:[{text:"أتركه يذهب — هذا أمر عادي",correct:!1,feedback:"قد يغرق الطفل الصغير حتى في الماء الضحل جدًّا؛ لا تتركه أبدًا ينزل إلى الماء وحده."},{text:"أُلبسه سترة النجاة، وأرافقه، وأراقبه عن قرب",correct:!0,feedback:"سترة النجاة ووجود شخص بالغ قريب يراقب طوال الوقت يجعلان الطفل الصغير أكثر أمانًا قرب الماء."},{text:"أطلب منه البقاء على الشاطئ وأبتعد عنه",correct:!1,feedback:"لا تترك الأطفال وحدهم قرب الماء أبدًا، ولو على الشاطئ؛ ابقَ قريبًا منهم وعيناك عليهم."},{text:"أراقبه من بعيد",correct:!1,feedback:"المراقبة من بعيد لا تكفي: قرب الماء ابقَ قريبًا من الطفل وعيناك عليه دائمًا."}]},quiz:[{question:"إذا كان شخص ما يغرق في الماء، فما الإجراء الأول؟",options:[{text:"أنزل إلى الماء لأنقذه",correct:!1},{text:"أرمي له شيئًا (حبلًا أو عصا) وأتصل بالرقمين 115 و122",correct:!0},{text:"أكتفي بالصراخ",correct:!1},{text:"لا أفعل شيئًا",correct:!1}],explanation:"لا تنزل إلى الماء بنفسك. مُدَّ إليه شيئًا أو ارمِه له، مثل حبل أو عصا أو طوق نجاة، واتصل بالرقمين 115 و122."},{question:"ما كمية الماء التي تكفي لإغراق طفلٍ صغير؟",options:[{text:"بضعة سنتيمترات، كما في دلو",correct:!0},{text:"فقط ماءٌ أعمق من طول الطفل",correct:!1},{text:"فقط البحيرات والسدود العميقة",correct:!1},{text:"ماءٌ يصل إلى خصر الطفل على الأقل",correct:!1}],explanation:"بضعة سنتيمترات من الماء تكفي لإغراق طفلٍ صغير، كما في دلو أو طست. لا تترك الأطفال وحدهم بالقرب من الماء أبدًا."},{question:"شخصٌ أُخرج من الماء ولا يتنفّس بصورة طبيعية، وأنت مدرَّب على الإنعاش القلبي الرئوي (CPR). ماذا تفعل؟",options:[{text:"أبدأ الإنعاش القلبي الرئوي مع أنفاس الإنقاذ",correct:!0},{text:"أكتفي بالضغطات الصدرية",correct:!1},{text:"أنتظر حتى يبدأ بالتنفّس وحده",correct:!1},{text:"أقلبه ليخرج الماء من فمه",correct:!1}],explanation:"إذا لم يكن يتنفّس بصورة طبيعية وكنت مدرّبًا، فابدأ الإنعاش القلبي الرئوي مع أنفاس الإنقاذ: ففي الغرق يتوقّف التنفّس أولًا، ولذلك فأنفاس الإنقاذ هي الأهم. وإذا لم تكن مدرّبًا أو لم تستطع إعطاء أنفاس الإنقاذ، فاكتفِ بالضغطات الصدرية حتى وصول المساعدة."}]},{id:11,icon:"Activity",accent:"#d97706",title:"الزلزال في المنزل والمجتمع",subtitle:"الاستعداد والاستجابة",summary:"يأتي الزلزال دون إنذار. إن استعداد العائلات ومعرفتها بالإجراء الصحيح أثناء الزلزال يحميان الأرواح. ومنطقتنا ليست بمنأى عن خطر الزلازل، ولذلك يجب أن تكون جميع العائلات مستعدّة.",blocks:[{heading:"أثناء الزلزال",body:`1. انخفض، واحتمِ، وتمسّك (Drop, Cover, Hold On): ادخل تحت طاولة متينة وأمسك بقائمتها.
2. ابتعد عن النوافذ والزجاج والأشياء الثقيلة.
3. لا تركض إلى الخارج، ولا تقف تحت إطار الباب، ولا تستخدم المصعد.
4. إذا كنت في الخارج: ابتعد عن المباني والأشجار وأسلاك الكهرباء.`},{heading:"حقيبة الطوارئ",body:"ينبغي لكل عائلة أن تجهّز حقيبة طوارئ: ماء (نحو 4 لترات لكل شخص يوميًّا، لمدة 3 أيام على الأقل)، وطعام لا يفسد، وأدوية، وراديو يعمل بالبطاريات، ومصباح يدوي، وبطانية، ووثائق مهمة."},{heading:"بعد الزلزال",body:"إذا شممت رائحة الغاز أو سمعت صوت تسرّبه: لا تلمس أيّ مفتاح ولا تُشعل نارًا، وافتح النوافذ في طريقك إلى الخارج، ولا تُغلق صمّام الغاز إلا إذا كان قريبًا ويمكن الوصول إليه دون الدخول إلى المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة، ثم اخرج واتصل بالرقم 115 من الخارج. لا تدخل المباني المتضرّرة. توقّع حدوث الهزّات الارتدادية (Aftershock). إذا بقي أشخاص تحت الأنقاض أو كان هناك مصابون، فاتصل بالرقمين 115 و122."}],tips:["انخفض، واحتمِ، وتمسّك.","أبقِ حقيبة الطوارئ جاهزة دائمًا.","لا تقطع الغاز إلا إذا شممت رائحته أو سمعت صوت تسرّبه، وأمكن الوصول إلى الصمّام دون الدخول إلى مكان الغاز ودون إحداث أي شرارة.","لا تبقَ في المباني المتضرّرة."],warnings:["لا تركض أثناء الهزّة!","لا تدخل المباني المتضرّرة!"],activity:{prompt:"يضرب زلزال قوي. أنت في المنزل والأطفال خائفون. ماذا ستفعل؟",options:[{text:"ندخل مع الأطفال تحت طاولة متينة، ونغطّي رؤوسنا، ونمسك بقائمة الطاولة",correct:!0,feedback:"الانخفاض والاحتماء والتمسّك تحت طاولة متينة يحميك أنت والأطفال من الأشياء المتساقطة حتى تتوقّف الهزّة."},{text:"نركض إلى الخارج",correct:!1,feedback:"لا تركض أثناء الهزّة؛ انخفض واحتمِ وتمسّك تحت طاولة متينة."},{text:"نقف بجانب النافذة",correct:!1,feedback:"قد تتحطّم النوافذ والزجاج أثناء الهزّة؛ ابتعد عنها واحتمِ تحت طاولة متينة."},{text:"ننزل بالمصعد",correct:!1,feedback:"لا تستخدم المصعد أبدًا أثناء الزلزال؛ انخفض واحتمِ وتمسّك تحت طاولة متينة."}]},quiz:[{question:"ما الإجراء الأول أثناء الزلزال في المنزل؟",options:[{text:"ادخل تحت طاولة متينة وغطِّ رأسك",correct:!0},{text:"اركض إلى الخارج",correct:!1},{text:"قف بجانب النافذة",correct:!1},{text:"استخدم المصعد",correct:!1}],explanation:"أثناء الهزّة: انخفض، واحتمِ، وتمسّك تحت طاولة متينة. لا تركض إلى الخارج، ولا تقف بجانب النوافذ، ولا تستخدم المصعد."},{question:"أنت في الخارج عندما يبدأ الزلزال. ماذا تفعل؟",options:[{text:"أبتعد عن المباني والأشجار وأسلاك الكهرباء",correct:!0},{text:"أركض إلى أقرب مبنى وأدخل تحت طاولة",correct:!1},{text:"أقف بجانب جدارٍ عالٍ لأحتمي به",correct:!1},{text:"أبقى تحت شجرةٍ كبيرة حتى تتوقف الهزّة",correct:!1}],explanation:"إذا كنت في الخارج أثناء الزلزال، فابتعد عن المباني والأشجار وأسلاك الكهرباء. ولا تركض أثناء الهزّة."},{question:"بعد الزلزال، هل يجوز أن تدخل المباني المتضرّرة؟",options:[{text:"لا، لا تدخل المباني المتضرّرة",correct:!0},{text:"نعم، لإحضار الوثائق والأدوية المهمة",correct:!1},{text:"نعم، فور انتهاء الاهتزاز",correct:!1},{text:"نعم، إذا كان المبنى منزلك",correct:!1}],explanation:"لا تدخل المباني المتضرّرة، وتوقّع حدوث الهزّات الارتدادية (Aftershock). وإذا بقي أشخاص تحت الأنقاض أو كان هناك مصابون، فاتصل بالرقمين 115 و122."}]},{id:12,icon:"Siren",accent:"#dc2626",title:"عمل الدفاع المدني",subtitle:"مهامّ فرق 115 وكيف يمكنك مساعدتها",summary:"الدفاع المدني جهاز حكومي مهم يحمي أرواح المواطنين والممتلكات الخاصة والعامة. في إقليم كوردستان، الرقم 115 هو رقم الدفاع المدني للحرائق والإنقاذ والكوارث، وفرقه جاهزة ليلًا ونهارًا. ينبغي أن يعرف المواطنون كيف يتصلون بالرقم 115 وكيف يساعدون الفرق، لا أن يعرقلوا عملها.",blocks:[{heading:"المهامّ الرئيسية للدفاع المدني",body:`• إطفاء الحرائق: في المنازل والدوائر الحكومية والمصانع والحقول والغابات.
• الإنقاذ: من السيارات في الحوادث، ومن تحت الأنقاض، ومن المياه.
• الفيضانات والكوارث: نقل السكان، وسحب المياه، ومساعدة المتضرّرين.
• المواد الخطرة (HazMat): تسرّب الغاز والمواد الكيميائية.
• التدريب والتوعية: دروس في المدارس والدوائر الحكومية.
• التفتيش على السلامة: في الأسواق والمطاعم والقاعات والمباني العالية.`},{heading:"الهيكل الرسمي",body:`• في إقليم كوردستان، يتبع الدفاع المدني وزارة الداخلية.
• في كل محافظة مديرية للدفاع المدني، مثل مديرية الدفاع المدني في دهوك، ولها مراكز في المدن والأقضية.
• الأقسام العاملة: إطفاء الحرائق، والإنقاذ، والإسعافات الأولية، والتدريب، والأقسام الفنية.
• في الكوارث الكبرى، يعمل الدفاع المدني جنبًا إلى جنب مع الإسعاف (122) والشرطة (104) والجهات الأخرى.`},{heading:"معدّاتهم ومركباتهم",body:`• سيارات الإطفاء: تحمل الماء والخراطيم والمضخّات.
• سيارات السلالم: تصل إلى الطوابق العالية.
• معدّات الإنقاذ: أدوات هيدروليكية لقطع حديد السيارات وإخراج الأشخاص المحاصَرين (Jaws of Life).
• جهاز التنفّس (BA — Breathing Apparatus): يزوّد رجل الإطفاء بالهواء النقي وسط الدخان.
• ملابس خاصة للحماية من الحرارة.
• أجهزة راديو للاتصال بين الفرق.`},{heading:"كيف تتصل بالرقم 115",body:`1. اطلب الرقم 115.
2. حافظ على هدوئك وتحدّث بوضوح.
3. اذكر: العنوان الصحيح (الحيّ، والشارع، ومَعلمًا واضحًا قريبًا)، وما الذي حدث (حريق؟ حادث؟ شخص محاصَر؟)، وعدد المصابين أو المحاصَرين، وأيّ خطر خاص (غاز، مواد كيميائية، كهرباء)، واسمك ورقم هاتفك ليتمكّنوا من معاودة الاتصال بك.
4. لا تُنهِ المكالمة حتى يطلبوا منك ذلك.
5. إذا كان ذلك آمنًا، فأبقِ الطريق مفتوحًا أمام سيارات الإطفاء.
6. أرسل شخصًا إلى الشارع ليُرشد الفريق إلى المكان.`},{heading:"كيف يساعد المجتمع فرق 115",body:`• على الطريق: عندما تسمع صوت صفّارة الإنذار، انتقل بهدوء إلى الجانب الأيمن وتوقّف ليبقى الطريق مفتوحًا.
• لا تُجرِ مكالمات كاذبة: كل مكالمة كاذبة تُبعد فريقًا عن حالة طوارئ حقيقية.
• أبقِ طرق الوصول مفتوحة: لا توقف السيارات أمام الأبواب وفي الأزقّة الضيقة.
• الشهادة: إذا رأيت الحادث، فابقَ في المكان وقدّم معلوماتك للفريق.
• لا تتجمهر بالقرب من الفريق ولا تلتقط الصور، حتى لا تعرقل طريقهم.
• إذا طلب الفريق المساعدة، فساعِده.
• إذا رأيت أن هناك حاجة إلى 115، فلا تتأخّر — اتصل.
• حافظ على هدوئك ولا تنشر الخوف والفوضى.`},{heading:"العمل والتطوّع في الدفاع المدني",body:`• يُقدَّم طلب التعيين عبر الإعلانات الرسمية للدفاع المدني.
• تحدّد المديرية شروط العمر والتحصيل الدراسي واللياقة البدنية والاختبارات — وللاطّلاع على أحدث المعلومات، اتصل بمديرية الدفاع المدني في دهوك.
• يتلقّى الموظفون الجدد تدريبًا أساسيًّا في مجالات إطفاء الحرائق والإنقاذ والإسعافات الأولية.
• يمكن للمواطنين المشاركة في دروس التوعية والتدريبات، وأن يكونوا عونًا في أحيائهم في أوقات الطوارئ.`}],tips:["احفظ الرقم 115 — وليحفظه جميع أفراد العائلة أيضًا.","اعرف عنوان منزلك بدقة (الحيّ، الشارع، رقم المنزل).","عندما تسمع صوت صفّارة الإنذار، انتقل إلى الجانب الأيمن وتوقّف، لا في منتصف الطريق.","استخدم الرقم 115 لحالات الطوارئ فقط، ليبقى خطّه مفتوحًا لمن يحتاجون إليه.","إذا اشتبهت في وجود حريق أو خطر، فاتصل — فمن الأفضل أن يأتي الفريق ولا تكون هناك مشكلة.","اجعل رقم المنزل واسم الحيّ ظاهرين على الباب ليصل الفريق إليك بسهولة.","اكتب خطة الإخلاء من المنزل وجرّبها مع عائلتك."],warnings:["لا تُجرِ مكالمات كاذبة إلى الرقم 115 — فهي تُضيّع وقت الفرق وتعرّض الأرواح للخطر.","لا تتجمهر بالقرب من مركبات 115 ولا تلتقط الصور — فهذا يعرقل عملهم.","لا تصوّر مقاطع فيديو للضحايا ولا تنشرها — احترم كرامتهم.","عندما تسمع صفّارة الإنذار، لا تقُد سيارتك خلف مركبات الطوارئ، وأبقِ الطريق مفتوحًا أمامها."],activity:{prompt:"وقع حادث سيارة أمام منزلك. هناك شخصان محاصَران داخل السيارة ولا يوجد أحد غيرك في المكان. ماذا ستفعل؟",options:[{text:"أتصل فورًا بالرقمين 115 و122 وأذكر العنوان الصحيح. إذا لم يكن هناك حريق، فلا أُخرج المصابين المحاصَرين حتى لا تتضرّر رقابهم وظهورهم. أبقى في مكان آمن وأتّبع تعليمات 115.",correct:!0,feedback:"الاتصال بالرقمين 115 و122 يجلب الإنقاذ والمساعدة الطبية، وعدم تحريك المصابين المحاصَرين يحمي رقابهم وظهورهم."},{text:"أحاول بسرعة إخراج المصابين المحاصَرين",correct:!1,feedback:"إخراج المصابين المحاصَرين قد يؤذي رقابهم وظهورهم؛ ما لم يكن هناك حريق، اتصل بالرقمين 115 و122 واتّبع تعليماتهم."},{text:"أصوّر مقطع فيديو وأنشره على مواقع التواصل الاجتماعي",correct:!1,feedback:"تصوير الضحايا ونشر المقاطع لا يساعد ولا يحترمهم؛ اتصل أولًا بالرقمين 115 و122."},{text:"أذهب لأبحث عن شخص آخر يساعد ولا أتصل",correct:!1,feedback:"لا تتأخّر: أنت الوحيد في المكان، فاتصل بنفسك فورًا بالرقمين 115 و122."}]},quiz:[{question:"ما رقم الطوارئ الخاص بالدفاع المدني في إقليم كوردستان؟",options:[{text:"991",correct:!1},{text:"107",correct:!1},{text:"115",correct:!0},{text:"122",correct:!1}],explanation:"في إقليم كوردستان، 115 هو رقم الدفاع المدني للحرائق والإنقاذ والكوارث، أما 122 فللإسعاف."},{question:"ماذا تفعل عندما ترى سيارة إطفاء تُطلق صفّارة الإنذار؟",options:[{text:"أنتقل بهدوء إلى الجانب الأيمن وأتوقّف ليبقى الطريق مفتوحًا",correct:!0},{text:"أقود خلفها بسرعة",correct:!1},{text:"أسدّ الطريق أمامها",correct:!1},{text:"أصوّر مقاطع فيديو",correct:!1}],explanation:"الانتقال بهدوء إلى اليمين والتوقّف يُبقيان الطريق مفتوحًا لسيارة الإطفاء. لا تقُد خلفها أبدًا، ولا تسدّ طريقها، ولا تتوقّف للتصوير."},{question:"عند الاتصال بالرقم 115، ما أهمّ شيء يجب أن تذكره أولًا؟",options:[{text:"اسمك فقط",correct:!1},{text:"العنوان وما الذي حدث",correct:!0},{text:"أقول «تعالوا بسرعة» وأُنهي المكالمة",correct:!1},{text:"أسأل متى سيصلون",correct:!1}],explanation:"يجب أن يعرف الفريق إلى أين يتّجه وما الذي حدث. ثم اذكر عدد المصابين وأيّ خطر واسمك ورقمك، ولا تُنهِ المكالمة حتى يُطلب منك ذلك."},{question:"ما وظيفة جهاز BA (Breathing Apparatus)؟",options:[{text:"هو مطفأة حريق",correct:!1},{text:"هو جهاز تنفّس يزوّد رجل الإطفاء بالهواء النقي وسط الدخان",correct:!0},{text:"هو جهاز راديو",correct:!1},{text:"هو صفّارة إنذار",correct:!1}],explanation:"يزوّد جهاز التنفّس (BA) رجل الإطفاء بالهواء النقي ليتنفّس وسط الدخان."},{question:"إذا اجتمع حريق ومصابون، فبأيّ رقم تتصل؟",options:[{text:"104 فقط",correct:!1},{text:"122 فقط",correct:!1},{text:"115 و122",correct:!0},{text:"لا أتصل وأنتظر",correct:!1}],explanation:"الحريق يحتاج إلى الدفاع المدني (115)، والمصابون يحتاجون إلى الإسعاف (122)، لذا اتصل بالرقمين كليهما."}]},{id:13,icon:"FlameKindling",accent:"#ea580c",title:"أنواع الحرائق",subtitle:"ليست كل الحرائق متشابهة — فكل نوع يتطلّب إجراءً خاصًّا",summary:"وفقًا للنظام الأمريكي (NFPA 10)، هناك خمس فئات للحريق: A وB وC وD وK. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. في كل فئة تحترق مادة مختلفة، ولكل فئة مطفأة حريق مناسبة لها. واختيار المطفأة الخاطئة قد يزيد النار اشتعالًا. سيعلّمك هذا الدرس كيف تتعرّف على نوع الحريق وما الذي تستخدمه.",blocks:[{heading:"الفئة A — المواد الصلبة (الخشب، الورق، القماش)",body:`شائعة جدًّا في المنزل: الورق، والكرتون، والستائر، والقماش، والبلاستيك، والأثاث الخشبي. المطفأة: الماء أو مسحوق ABC. صوّب على قاعدة النار، وابدأ من المسافة المحددة على ملصق المطفأة، وطريق الخروج خلفك.
• إذا اشتعلت النار في ملابسك: توقّف، وانبطح على الأرض، وتدحرج (Stop, Drop, Roll).`},{heading:"الفئة B — السوائل والغازات القابلة للاشتعال (البنزين، النفط الأبيض، الكحول)",body:`تشتعل هذه السوائل بسرعة، ويمكن لأبخرتها أن تشتعل من مسافة بعيدة. لا تستخدم الماء: فالماء ينشر السائل المشتعل ويزيد النار اتساعًا. المطفأة للسوائل: الرغوة (Foam) أو CO₂ أو مسحوق ABC. انشر الرغوة برفق على سطح السائل لتغطّيه.
• الكحول والأسيتون والمذيبات القطبية الأخرى: CO₂ أو مسحوق ABC أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها.
• حريق الغاز (غاز LPG أو الغاز الطبيعي): الأولوية لإيقاف تدفق الغاز. يُغلق شخصٌ مؤهَّل صمّامَ الغاز فقط إذا كان الوصول إليه آمنًا. لا تُطفئ لهب الغاز إذا لم يمكن إيقاف الغاز بأمان، فالغاز غير المحترق يتجمّع وقد ينفجر. وإذا لم يكن ذلك آمنًا، فأخلِ الجميع، وأطلق الإنذار، واتصل بالرقم 115. والرغوة ليست الخيار العام لحرائق الغاز. وفي EN 2 يُعدّ حريق الغاز من الفئة C.
• BLEVE: إذا سخّنت النار أسطوانة غاز أو خزّانًا، فقد ينفجر انفجارًا كبيرًا — ابتعد عنه واتصل بالرقم 115.`},{heading:"الفئة C — الأجهزة الكهربائية (حسب NFPA)",body:`الحواسيب، والتلفزيونات، والثلاجات، والمقابس، والأسلاك الكهربائية.
• لا تستخدم الماء أبدًا! فالصعقة الكهربائية قد تقتل.
• الإجراء الأول: اقطع التيار الكهربائي (انزع القابس أو اقطع الكهرباء الرئيسية للمنزل)، ثم استخدم CO₂ أو العامل النظيف (Clean Agent) أو مسحوق ABC.
• مسحوق ABC يُتلف الأجهزة الإلكترونية؛ وCO₂ أفضل للأجهزة الحسّاسة.
• في النظام الأوروبي (EN 2)، لا يُعدّ حريق الكهرباء فئة مستقلة.`},{heading:"الفئة D — المعادن القابلة للاشتعال (المغنيسيوم، التيتانيوم، الصوديوم، الليثيوم المعدني)",body:`تحترق هذه المعادن بحرارة عالية جدًّا.
• لا تستخدم الماء أو CO₂ على المعادن المشتعلة — فهما يسبّبان تفاعلًا عنيفًا ونارًا أكبر.
• استخدم فقط مطفأة أو مادة يذكر ملصقها هذا المعدن، فالمادة تختلف من معدن لآخر (فالليثيوم مثلًا يحتاج مادة مخصّصة لليثيوم). ولا تستخدم الماء أو المسحوق العادي أو الرغوة أبدًا. ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة SDS للمعدن وكان جافًا تمامًا. واتصل بالرقم 115.
• بطاريات الليثيوم أيون (Li-ion) في الهواتف المحمولة والحواسيب المحمولة والشواحن المتنقّلة والدراجات الكهربائية لا تحتوي على الليثيوم المعدني، وليست من الفئة D: إذا اشتعلت، فبرّدها بكمية كبيرة من الماء واتصل بالرقم 115. الفئة D مخصّصة فقط لبطاريات الليثيوم المعدني (Lithium-metal).`},{heading:"الفئة K (NFPA) / F (EN 2) — زيت الطبخ",body:`حريق الزيت الساخن في المقلاة أو القِدر على الموقد.
• لا تستخدم الماء أبدًا! فالماء يتحوّل بسرعة إلى بخار داخل الزيت الساخن وينثر الزيت المشتعل بشكل انفجاري.
• مسحوق ABC لا يناسب هذه الفئة.
• استخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical)، أو أطفئ الموقد وضع غطاءً كبيرًا أو بطانية الحريق (Fire blanket) لقطع الأكسجين.
• لا تحمل المقلاة ولا تُخرجها إلى الخارج.`},{heading:"مراحل تطوّر الحريق",body:`1. البداية (Incipient): النار صغيرة والدخان قليل. في هذه المرحلة فقط يكون استخدام مطفأة الحريق آمنًا.
2. النموّ (Growth): تزداد الحرارة وتنتشر النار.
3. الحريق الكامل (Fully Developed): الغرفة كلها مشتعلة.
4. الخمود (Decay): تخفّ النار، لكن إذا دخل الهواء إلى الغرفة فجأة، فهناك خطر الارتداد اللهبي (Backdraft).

• الاشتعال الوميضي (Flashover): عندما تصل حرارة طبقة الدخان الساخن تحت السقف إلى نحو 500-600 درجة مئوية، تشتعل جميع محتويات الغرفة في وقت واحد.`}],tips:["قبل الشراء، اقرأ فئات الحريق المكتوبة على ملصق مطفأة الحريق.","احرص على وجود مطفأة ABC واحدة على الأقل في المنزل، ومطفأة المادة الكيميائية الرطبة (Wet Chemical) أو بطانية حريق للمطبخ.","وفقًا لـ NFPA 10، لا تزيد مسافة الوصول إلى مطفأة الفئة A في أماكن العمل على 23 مترًا.","وفقًا لـ NFPA، الطبخ هو السبب الأول لحرائق المنازل — لا تغادر المطبخ أثناء الطهي.","حريق الأجهزة الكهربائية: لا تستخدم الماء أبدًا — الإجراء الأول هو قطع التيار الكهربائي.","بطارية الليثيوم أيون: إذا سخنت أو انتفخت أو خرج منها دخان، فضعها بعيدًا عن المواد القابلة للاشتعال، وابتعد عنها، واتصل بالرقم 115.","زيت الطبخ: أطفئ الموقد وضع غطاءً كبيرًا على الإناء — فهذه هي الطريقة الأولى لإخماد هذا الحريق."],warnings:["الماء على الزيت المشتعل = انفجار بخاري ونار كبيرة.","الماء على الأجهزة الكهربائية = صعقة قاتلة.","مسحوق ABC على الحاسوب = تلف الجهاز.","برّد بطارية الليثيوم أيون المشتعلة بكمية كبيرة من الماء واتصل بالرقم 115 — فقد تشتعل النار من جديد.","حريق أكبر من سلّة المهملات = اخرج فورًا، لا تستخدم المطفأة."],activity:{prompt:"أنت في المطبخ. اشتعلت النار في الزيت داخل المقلاة والموقد لا يزال مشتعلًا. عائلتك في غرفة النوم. ماذا ستفعل؟",options:[{text:"أُطفئ الموقد، وأضع غطاءً كبيرًا على المقلاة، وأُنبّه العائلة، وإذا لم تنطفئ النار نخرج ونتصل بالرقم 115",correct:!0,feedback:"إطفاء الموقد والغطاء يقطعان الحرارة والأكسجين، وتنبيه عائلتك يتيح للجميع الخروج عند الحاجة."},{text:"أصبّ عليها الماء لتبرد",correct:!1,feedback:"الماء على الزيت المشتعل يسبّب انفجارًا بخاريًّا ونارًا كبيرة؛ لا تصبّ الماء عليه أبدًا."},{text:"أحمل المقلاة وأُخرجها إلى الخارج",correct:!1,feedback:"لا تحمل المقلاة ولا تُخرجها؛ أطفئ الموقد وضع عليها غطاءً كبيرًا."},{text:"أهرب وحدي ولا أُنبّه العائلة",correct:!1,feedback:"عائلتك في خطر أيضًا؛ نبّههم، وإذا لم تنطفئ النار فاخرجوا معًا واتصلوا بالرقم 115."}]},quiz:[{question:"اشتعلت النار في حاسوب في غرفتك. ما الإجراء الصحيح؟",options:[{text:"الماء",correct:!1},{text:"أقطع التيار الكهربائي أولًا، ثم أستخدم CO₂ أو العامل النظيف (Clean Agent) أو ABC",correct:!0},{text:"الرغوة (AFFF Foam)",correct:!1},{text:"المادة الكيميائية الرطبة (Wet Chemical)",correct:!1}],explanation:"الحاسوب جهاز كهربائي: اقطع التيار أولًا، ثم استخدم CO₂ أو العامل النظيف (Clean Agent) أو مسحوق ABC. فالماء قد يسبّب صعقة كهربائية قاتلة."},{question:"اشتعلت النار في زيت المقلاة على موقد الغاز. ما الإجراء الأول؟",options:[{text:"أصبّ عليها الماء",correct:!1},{text:"أغلق صمّام الغاز وأضع عليها غطاءً كبيرًا",correct:!0},{text:"أرشّ عليها مسحوق ABC",correct:!1},{text:"أضربها بقطعة قماش",correct:!1}],explanation:"إغلاق الغاز يوقف الحرارة، والغطاء الكبير يقطع الأكسجين. أما الماء فيسبّب انفجارًا بخاريًّا، ومسحوق ABC لا يناسب زيت الطبخ."},{question:"اشتعلت بطارية الليثيوم أيون في هاتف محمول. ماذا ستفعل؟",options:[{text:"أغطّيها ببطانية وأتركها في الغرفة",correct:!1},{text:"أرشّ عليها مسحوق ABC فقط وأذهب",correct:!1},{text:"إذا كان ذلك آمنًا، أُبعدها عن المواد القابلة للاشتعال، وأبرّدها بكمية كبيرة من الماء، وأتصل بالرقم 115",correct:!0},{text:"أرشّ عليها CO₂ فقط وأتركها",correct:!1}],explanation:"إذا كان ذلك آمنًا، فأبعد البطارية عن المواد القابلة للاشتعال، وبرّدها بكمية كبيرة من الماء، واتصل بالرقم 115؛ فمسحوق ABC وCO₂ لا يوقفان هذا الحريق تمامًا."},{question:"يحدث الاشتعال الوميضي (Flashover) عندما تصل حرارة طبقة الدخان الساخن تحت السقف إلى نحو كم درجة؟",options:[{text:"200 درجة مئوية",correct:!1},{text:"300 درجة مئوية",correct:!1},{text:"500-600 درجة مئوية",correct:!0},{text:"1000 درجة مئوية",correct:!1}],explanation:"يحدث الاشتعال الوميضي (Flashover) عندما تصل حرارة طبقة الدخان الساخن تحت السقف إلى نحو 500-600 درجة مئوية، فتشتعل جميع محتويات الغرفة في وقت واحد."},{question:"وفقًا لـ NFPA، ما النشاط الذي يُعدّ السبب الأول لحرائق المنازل؟",options:[{text:"قراءة الكتب",correct:!1},{text:"غسل الملابس يدويًّا",correct:!1},{text:"الطبخ (المطبخ)",correct:!0},{text:"النوم",correct:!1}],explanation:"وفقًا لـ NFPA، الطبخ هو السبب الأول لحرائق المنازل، لذا لا تغادر المطبخ أثناء الطبخ."}]},{id:14,icon:"FireExtinguisher",accent:"#0891b2",title:"كيف تستخدم مطفأة الحريق",subtitle:"أنواع مطفآت الحريق، وطريقة PASS، ومتى يجب أن تترك المطفأة وتخرج",summary:"توجد مطفآت الحريق في المنازل والدوائر الحكومية والأماكن العامة، لكن كثيرًا من الناس لا يعرفون كيف يستخدمونها. فمطفأة الحريق اليدوية لا تعمل إلا بضع ثوانٍ، ولذلك يجب أن تكون مستعدًّا قبل وقوع الحريق. يعلّمك هذا الدرس طريقة PASS، واختيار المطفأة المناسبة، والأهمّ من ذلك كلّه — متى يجب ألّا تستخدم المطفأة وأن تخرج.",blocks:[{heading:"الأنواع الرئيسية لمطافئ الحريق",body:`الفئات بأحرف NFPA:
• الماء: الفئة A فقط.
• الرغوة (Foam): A وB.
• CO₂: الفئة B والأجهزة الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). مداها قصير؛ ولا تصلح لحرائق الخشب والورق العميقة؛ وفي الغرفة الصغيرة اخرج بعد الاستخدام وهوِّ المكان.
• مسحوق ABC: A وB وC — الأكثر انتشارًا؛ ليس للفئة D ولا للفئة K.
• المادة الكيميائية الرطبة (Wet Chemical): K، زيت الطبخ.
• العامل النظيف (Clean Agent): للأجهزة الإلكترونية الحسّاسة؛ وتختلف فئاته حسب الطراز، فاقرأ الملصق.

اللون ليس فئة الحريق. وفق BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة: الكريمي = الرغوة، الأزرق = المسحوق الجاف، الأسود = CO₂، الأصفر = المادة الكيميائية الرطبة، والماء بلا شريط. وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا.

تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.

للمنزل: مطفأة ABC، ومطفأة المادة الكيميائية الرطبة أو بطانية حريق للمطبخ.`},{heading:"PASS — خطوة بخطوة",body:`قبل أن تبدأ، يجب أن تكون كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك.

1. P = Pull (اسحب): اسحب مسمار الأمان.
2. A = Aim (وجِّه): وجِّه فوهة الخرطوم نحو قاعدة النار، لا نحو أعلاها. ابدأ من المسافة المحددة على ملصق المطفأة، ولا تقترب إلا كلما صغرت النار.
3. S = Squeeze (اضغط): اضغط على المقبض بقوة وباستمرار.
4. S = Sweep (حرِّك): حرِّك الخرطوم يمينًا ويسارًا ببطء حتى تنطفئ النار.

• إذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب.
• تفرغ المطافئ الصغيرة بسرعة، غالبًا خلال ثوانٍ قليلة؛ ومدة التفريغ الدقيقة مكتوبة على الملصق.
• PASS هي الطريقة العامة لمعظم المطافئ اليدوية. أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعامل النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة.`},{heading:"مكان الوقوف — السلامة قبل كل شيء",body:`اجعل ظهرك دائمًا نحو الباب (طريق الخروج). ابدأ من المسافة المحددة على ملصق المطفأة أو في تعليمات الشركة المصنّعة، ولا تقترب إلا كلما صغرت النار. إذا اشتدّت الحرارة، فتراجع إلى الخلف. لا تسمح أبدًا بأن تصبح النار بينك وبين الباب.
• الدخان والحرارة قد يقتلان بسرعة — إذا امتلأت الغرفة بالدخان، فاخرج فورًا.`},{heading:"متى لا تستخدم مطفأة الحريق",body:`• النار أكبر من سلّة مهملات أو تنتشر بسرعة.
• الغرفة تمتلئ بالدخان.
• لا تعرف ما المادة التي تحترق.
• طريق الخروج ليس خلفك.
• لم يتصل أحد بالرقم 115 بعد (اتصل أولًا).
• النار تقترب من أسطوانة غاز أو خزّان سوائل.
• انتشرت السوائل القابلة للاشتعال على مساحة واسعة.

في جميع هذه الحالات: اخرج أولًا، ثم اتصل بالرقم 115.`},{heading:"فحص مطفأة الحريق في المنزل",body:`كل شهر (فحص بصري، يجريه الشخص المسؤول):
1. أن تكون المطفأة في مكانها وظاهرة، والطريق إليها مفتوحًا.
2. أن يكون مسمار الأمان وختمه سليمين.
3. أن يكون جسم المطفأة نظيفًا، خاليًا من الصدأ والكسور والتسرّب، وأن يكون الخرطوم والفوهة غير مسدودين.
4. أن يكون ملصق التعليمات سهل القراءة ومتّجهًا إلى الخارج.
5. إذا كان فيها مؤشر ضغط، أن يكون المؤشر في المنطقة الخضراء. مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة.

خدمة يجريها فنّي مؤهَّل:
• الفحص والصيانة (Maintenance): مرة كل سنة، وتسجيلها على بطاقة المطفأة.
• إعادة التعبئة (Recharge): بعد أي استخدام، ولو كان قصيرًا.
• صيانة السنوات الست: تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار ضغط كل 12 سنة، ويُفحص داخلها كل 6 سنوات.
• اختبار ضغط جسم المطفأة (Hydrostatic test): كل 5 سنوات لمطافئ الماء والرغوة (AFFF) وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ؛ وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم.

موعد الاختبار ليس موعدًا للاستبدال. تُسحب المطفأة من الخدمة إذا فشلت في الفحص أو الاختبار، أو تضرّرت، أو صارت قديمة الطراز، أو استدعتها الشركة المصنّعة، أو لم يعد ملصقها مقروءًا، أو كانت من النوع غير القابل لإعادة التعبئة وتجاوزت مدة الخدمة المكتوبة على ملصقها. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك.`},{heading:"أين نضع مطفأة الحريق؟",body:`• في المنزل (واحدة على الأقل): بالقرب من باب المطبخ، وفي كل طابق إن أمكن.
• في أماكن العمل (NFPA 10): لا تزيد مسافة الوصول إلى المطفأة على 23 مترًا للفئة A، و9 أو 15 مترًا للفئة B (حسب حجم المطفأة).
• يجب أن تكون علامة المطفأة (Sign) ظاهرة من بعيد.
• علّق المطفأة على الحائط على ارتفاع يسهل الوصول إليه (لا يزيد ارتفاع أعلاها على نحو 1.5 متر)، لا على الأرض ولا داخل الخزائن المغلقة.`}],tips:["للشراء: مطفأة ABC تستطيع حملها واستخدامها (وزنها مكتوب على الملصق) للمنزل، ومطفأة المادة الكيميائية الرطبة (Wet Chemical) أو بطانية حريق للمطبخ.","قبل الشراء، تحقّق من فئات الحريق وعلامة المعيار (مثل EN 3) على الملصق.","جرّب طريقة PASS في تدريب باستخدام مطفأة تدريبية.","اقرأ على الملصق كم ثانية تعمل مطفأتك — فمعظم المطفآت الصغيرة تفرغ بسرعة.","شارك في تدريبات الدفاع المدني عندما تُقام في حيّك أو مكان عملك.","ابدأ من المسافة المحددة على ملصق المطفأة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار.","اجعل ظهرك دائمًا نحو الباب."],warnings:["لا تعمل المطفأة الصغيرة إلا بضع ثوانٍ — كن مستعدًّا.","فوهة خرطوم مطفأة CO₂ تبرد كثيرًا — لا تلمسها.","مسحوق ABC على الحاسوب قد يُلحق الضرر بالجهاز.","النار أكبر من سلّة مهملات = اخرج، لا تستخدم المطفأة.","بطارية الليثيوم أيون: مسحوق ABC وCO₂ لا يوقفان النار تمامًا — برّدها بكمية كبيرة من الماء واتصل بالرقم 115."],activity:{prompt:"أنت في المنزل. في غرفة النوم، اشتعلت النار في شاحن الهاتف المحمول الموصول بالمقبس الكهربائي. النار صغيرة ولديك مطفأتان في متناول يدك: مطفأة ABC بوزن 2 كغ ومطفأة المادة الكيميائية الرطبة (Wet Chemical). ماذا ستفعل؟",options:[{text:"أقطع التيار الكهربائي أولًا (أنزع القابس إذا كان ذلك آمنًا، أو أقطع الكهرباء الرئيسية). أُنبّه عائلتي وأتصل بالرقم 115. ثم، وظهري نحو الباب، آخذ مطفأة ABC وأستخدم طريقة PASS، بدءًا من المسافة المحددة على ملصقها؛ وإذا لم تنطفئ النار فورًا، أخرج وأغلق الباب.",correct:!0,feedback:"التيار مقطوع، والعائلة منبَّهة، و115 اتُّصل به، والمخرج خلفك، والمطفأة مناسبة: كل الإجابات «نعم» قبل PASS."},{text:"أستخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical)",correct:!1,feedback:"المادة الكيميائية الرطبة مخصّصة لزيت الطبخ (الفئة K)؛ أما هذا الحريق الكهربائي فاقطع عنه التيار ثم استخدم مطفأة ABC."},{text:"أصبّ عليها الماء",correct:!1,feedback:"لا تستخدم الماء أبدًا على الأجهزة الكهربائية: فقد يسبّب صعقة كهربائية قاتلة."},{text:"أهرب ولا أُنبّه أحدًا",correct:!1,feedback:"الخروج دون تنبيه أحد يعرّض عائلتك للخطر؛ نبّههم واتصل بالرقم 115، حتى لو لم تحاول إطفاء النار."}]},quiz:[{question:"في طريقة PASS، إلامَ يرمز الحرف P؟",options:[{text:"Push (ادفع)",correct:!1},{text:"Pull (اسحب مسمار الأمان)",correct:!0},{text:"Point (أشِر)",correct:!1},{text:"Press (اضغط)",correct:!1}],explanation:"الحرف P يعني Pull: اسحب مسمار الأمان. ثم وجِّه الفوهة نحو قاعدة النار (Aim)، واضغط المقبض (Squeeze)، وحرّكها يمينًا ويسارًا (Sweep)."},{question:"كم تعمل تقريبًا مطفأة صغيرة بمسحوق ABC (2 كغ)؟",options:[{text:"3-5 دقائق",correct:!1},{text:"بضع ثوانٍ فقط؛ والمدة الدقيقة مكتوبة على ملصقها",correct:!0},{text:"1 دقيقة",correct:!1},{text:"بلا حدّ",correct:!1}],explanation:"تفرغ المطفأة الصغيرة في بضع ثوانٍ فقط، لذا كن مستعدًّا قبل أن تبدأ. ومدة التفريغ الدقيقة مكتوبة على ملصقها."},{question:"كيف تعرف من أيّ مسافة تبدأ عن النار؟",options:[{text:"ابدأ دائمًا من مسافة نصف متر",correct:!1},{text:"من ملصق المطفأة: ابدأ من المسافة المحددة عليه، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار",correct:!0},{text:"ابدأ دائمًا من مسافة 7-10 أمتار",correct:!1},{text:"لا يوجد فرق",correct:!1}],explanation:"لا توجد مسافة ثابتة: ابدأ من المسافة المحددة على ملصق المطفأة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار."},{question:"متى يجب ألّا تستخدم المطفأة وأن تخرج؟",options:[{text:"أبدًا — استخدمها دائمًا",correct:!1},{text:"عندما تكون النار أكبر من سلّة مهملات أو تمتلئ الغرفة بالدخان",correct:!0},{text:"في المطبخ فقط",correct:!1},{text:"في غرفة النوم فقط",correct:!1}],explanation:"إذا كانت النار أكبر من سلّة مهملات، أو تنتشر، أو كانت الغرفة تمتلئ بالدخان، فلا تستخدم المطفأة: اخرج واتصل بالرقم 115."},{question:"أيّ مطفأة تناسب حريق زيت الطبخ؟",options:[{text:"الماء",correct:!1},{text:"مسحوق ABC",correct:!1},{text:"المادة الكيميائية الرطبة (Wet Chemical) — الفئة K/F",correct:!0},{text:"CO₂",correct:!1}],explanation:"حرائق زيت الطبخ من الفئة K (NFPA) أو F (EN 2). وتُكوّن مطفأة المادة الكيميائية الرطبة طبقةً تقطع الأكسجين وتبرّد الزيت؛ ولا تستخدم الماء أبدًا."}]},{id:15,icon:"HeartHandshake",accent:"#e11d48",title:"الإسعافات الأولية للمواطنين",subtitle:"الفحص الأولي، وCPR، وAED، والنزيف، والحروق، والاختناق",summary:"يمكن أن تُنقَذ حياة إنسان على يد مواطن عادي إذا عرف ما الذي يجب فعله. فبعد توقّف القلب، كل دقيقة تمرّ دون إنعاش قلبي رئوي (CPR) ودون جهاز إزالة الرجفان الخارجي الآلي (AED) تُقلّل فرصة النجاة. ووفقًا لإرشادات AHA 2025، يشرح هذا الدرس الفحص الأولي (DRABC)، والإنعاش القلبي الرئوي (CPR)، وجهاز AED، ومناورة هايمليك (Heimlich)، وإيقاف النزيف، والحروق، وبعض حالات الطوارئ الأخرى. ينبغي لكل مواطن أن يتعلّم هذه المعلومات.",blocks:[{heading:"DRABC — الفحص الأولي",body:`• D = Danger (الخطر): هل هناك خطر؟ كهرباء، أو حريق، أو حركة مرور؟ قبل كل شيء، تأكّد من سلامتك أنت.
• R = Response (الاستجابة): هزّ كتفيه واسأله بصوت عالٍ: «هل أنت بخير؟» إذا لم يستجب، فاتصل بالرقم 122 واطلب جهاز AED.
• A = Airway (مجرى الهواء): أمِل الرأس إلى الخلف وارفع الذقن.
• B = Breathing (التنفّس): في مدة لا تزيد على 10 ثوانٍ، انظر هل يتحرّك الصدر وهل التنفّس طبيعي أم لا.
• C = CPR: إذا لم يكن يتنفّس بصورة طبيعية، فابدأ ضغطات الصدر فورًا. لا يحتاج المواطن إلى فحص النبض (Pulse).`},{heading:"CPR — 30:2 أو باليدين فقط (Hands-Only)",body:`• الموضع: منتصف الصدر، يد فوق الأخرى، وذراعاك مستقيمتان.
• البالغون (بمن فيهم كبار السنّ): العمق 5-6 سم، والمعدل 100-120 ضغطة في الدقيقة.
• 30 ضغطة + نفَسان إذا كنت مدرّبًا؛ وإلا فاكتفِ بالضغطات (Hands-Only). والأطفال والرضّع والغرقى بحاجة خاصة إلى أنفاس الإنقاذ: إذا كنت مدرّبًا وقادرًا، فأجرِ الإنعاش مع أنفاس الإنقاذ؛ وإن لم تستطع، فالضغطات وحدها أفضل من لا شيء.
• لا تتوقّف حتى يصل جهاز AED، أو يتسلّم فريق الإسعاف العمل، أو تعجز عن الاستمرار.
• الطفل (من عمر سنة واحدة حتى سنّ البلوغ): بيد واحدة أو باليدين، والعمق نحو 5 سم (ثلث عمق الصدر).
• الرضيع (أقل من سنة واحدة): بالإبهامين مع إحاطة الصدر باليدين، أو بكعب راحة يد واحدة؛ والعمق نحو 4 سم. لم تعد طريقة الإصبعين تُدرَّس (AHA 2025).
• للأطفال والرضّع، إذا أجرى شخصان الإنعاش القلبي الرئوي (CPR) معًا: 15:2.`},{heading:"AED — جهاز إزالة الرجفان الخارجي الآلي",body:`يتوفّر جهاز AED في الأماكن العامة مثل الدوائر الحكومية والمستشفيات والأسواق الكبيرة. يمكن لأيّ شخص استخدامه، لأن الجهاز يعطي التعليمات صوتيًّا. واستخدامه المبكر يزيد فرصة النجاة كثيرًا.
1. شغّل الجهاز.
2. ضع اللاصقتين على الصدر العاري، كما في الصورة الموجودة على اللاصقتين.
3. استمع إلى تعليمات الجهاز الصوتية.
4. نادِ بصوت عالٍ: «لا يلمسه أحد!»
5. إذا طلب الجهاز ذلك، فاضغط زرّ الصدمة.
6. تابع الإنعاش القلبي الرئوي (CPR) فورًا لمدة دقيقتين واتّبع تعليمات الجهاز.

• أثناء الصدمة، لا يلمس أحدٌ المصاب!`},{heading:"مناورة هايمليك (Heimlich) — الاختناق بجسم غريب",body:`العلامات: لا يستطيع الشخص الكلام أو السعال أو التنفّس، ويُمسك حلقه بيديه.
1. وجّه 5 ضربات بكعب راحة اليد بين لوحَي الكتفين (Back blows).
2. ثم 5 ضغطات بطنية (Heimlich): ضع قبضتك فوق السرّة بقليل وأسفل عظمة القصّ بمسافة كافية، واضغط بسرعة نحو الداخل وإلى الأعلى.
3. كرّر 5+5 حتى يخرج الجسم؛ فإذا فقد الوعي، فاتصل بالرقم 122 وابدأ الإنعاش القلبي الرئوي (CPR).

• الرضيع (أقل من سنة واحدة): 5 ضربات على الظهر (ورأسه أخفض من صدره) + 5 ضغطات على الصدر. لا تُجرِ ضغطات بطنية أبدًا.
• المرأة الحامل أو الشخص شديد البدانة: اضغط على منتصف الصدر، لا على البطن.`},{heading:"النزيف — Stop the Bleed",body:`1. الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة وباستمرار. إذا تشبّعت قطعة القماش بالدم، فلا تُزِلها؛ بل ضع قطعة أخرى فوقها.
2. حشو الجرح (Wound packing): إذا كان الجرح عميقًا، فاحشُ داخله بشاش الجروح النظيف (Gauze) ثم اضغط بقوة.
3. العاصبة (تورنيكيه): في حالة النزيف المهدِّد للحياة من الذراع أو الساق، اربطها على بُعد 5-7 سم فوق الجرح (وليس على الركبة أو المرفق) وشدّها حتى يتوقّف النزيف. سجّل وقت وضعها، ولا تُرخِها ولا تنزعها أبدًا — فالفريق الطبي وحده هو من ينزعها.

• لا تُخرج الجسم الحادّ من الجرح!
• إصابة العين: لا تضغط على العين.
• جرح الرأس: إذا اشتبهت في كسر عظم الجمجمة، فاضغط برفق.
• اتصل بالرقم 122.`},{heading:"الحروق وحالات طوارئ أخرى",body:`• الحروق: 20 دقيقة من الماء البارد الجاري (لا ماء ساخن ولا ثلج).
• الإغماء (Fainting): مدّده على ظهره وارفع ساقيه قليلًا.
• مريض السكّري (Diabetic): إذا كان واعيًا ويستطيع البلع، فأعطه شيئًا حلوًا.
• نوبة الهلع (Panic attack): حافظ على هدوئك وساعده على التنفّس ببطء.
• إصابة الرأس أو الرقبة: لا تحرّكه، وأبقِه ثابتًا، واتصل بالرقم 122. لا تحرّكه إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR)، مع إبقاء الرأس والرقبة والظهر على خط واحد. ولا تضعه على جنبه في وضعية الإفاقة.
• الكسر (Fracture): لا تحرّك الطرف المصاب، وثبّته، وضع ثلجًا ملفوفًا على التورّم.
• الصعقة الكهربائية: الإجراء الأول هو قطع التيار الكهربائي.
• لدغة الأفعى (Snake bite): ابتعد عن الأفعى، وأبقِ المصاب هادئًا وساكنًا. ثبّت الذراع أو الساق الملدوغة بجبيرة ولا تحرّكها، وانزع الخواتم والساعة والملابس الضيقة قبل أن يحدث التورّم. اتصل بالرقم 122 وانقله إلى المستشفى بسرعة. لا تجرح مكان اللدغة ولا تمصّه، ولا تربط رباطًا ضيقًا أو عاصبة (تورنيكيه)، ولا تضع عليه ثلجًا، ولا تستعمل العلاجات الشعبية أو العشبية.
• التسمّم: اتصل بالرقم 122، واحتفظ بعبوة المادة السامة أو ملصقها لتريها للأطباء. لا تحاول إحداث القيء، ولا تعطه حليبًا أو زيتًا أو ماءً مالحًا أو أي علاج منزلي آخر، ولا تعطه شيئًا يأكله أو يشربه إلا إذا طلب الطبيب ذلك. وإذا ابتلع النفط الأبيض (الكيروسين) أو البنزين أو زيت المصابيح، فالقيء خطير جدًا لأن المادة قد تدخل إلى الرئتين. وإذا أصابت المادة السامة الجلد أو العينين، فاغسلها بكمية وافرة من الماء الجاري وانزع الملابس الملوّثة. وإذا كان المصاب نعسانًا أو فاقدًا للوعي لكنه يتنفّس طبيعيًا، فضعه على جنبه.`}],tips:["122 للإسعاف و115 للحريق والإنقاذ — احفظهما.","التحق بدورة في الإنعاش القلبي الرئوي (CPR) والإسعافات الأولية، وجدّدها كل بضع سنوات.","اعرف أماكن أجهزة AED القريبة من منزلك ومكان عملك.","بعد توقّف القلب، كل دقيقة مهمة — ابدأ الإنعاش القلبي الرئوي (CPR) بسرعة.","أغنية «Stayin' Alive» تُذكّرك بإيقاع 100-120 ضغطة في الدقيقة.","احتفظ بحقيبة إسعافات أولية في المنزل وفي السيارة وفي مكان العمل.","في حقيبة الإسعافات الأولية: قماش نظيف، وقفّازات، وعاصبة (تورنيكيه)، ومقصّ، وقائمة بأرقام الطوارئ."],warnings:["لا تلمس أبدًا الشخص المصاب بصعقة كهربائية قبل قطع التيار.","إذا اشتبهت في إصابة الظهر أو الرقبة، فلا تحرّك الشخص الذي سقط، إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR).","العاصبة (تورنيكيه): سجّل وقت وضعها، ولا تُرخِها ولا تنزعها أبدًا.","لا تضع على الحرق ماءً ساخنًا أو ثلجًا أو زبدة أو معجون أسنان.","يجب ألّا تتداخل لاصقتا جهاز AED؛ وللأطفال الأصغر من 8 سنوات، استخدم لاصقات الأطفال إن توفّرت."],activity:{prompt:"في الشارع، رأيت شخصًا عمره 55 عامًا يسقط. لا يستجيب ولا يتنفّس. يوجد جهاز AED عند باب دائرة حكومية قريبة، وهناك شخص آخر في المكان. ماذا ستفعل؟",options:[{text:"أتأكّد من أن المكان آمن وأتحقّق من استجابته. أتصل بالرقم 122 وأرسل الشخص الآخر ليُحضر جهاز AED. أبدأ فورًا الإنعاش القلبي الرئوي (CPR) بنسبة 30:2، وأستخدم جهاز AED عند وصوله.",correct:!0,feedback:"الاتصال بالرقم 122، وإرسال مَن يُحضر جهاز AED، والبدء فورًا بالإنعاش أمور حاسمة، لأن كل دقيقة بلا إنعاش تُقلّل فرصة النجاة."},{text:"أكتفي بإرسال شخص ليُحضر جهاز AED وأنتظر دون إنعاش قلبي رئوي (CPR)",correct:!1,feedback:"الانتظار دون إنعاش يُضيّع دقائق ثمينة؛ ابدأ الضغطات فورًا بينما يُحضر الشخص الآخر جهاز AED."},{text:"أعطيه ماءً",correct:!1,feedback:"لا تضع أيّ شيء في فم فاقد الوعي أبدًا؛ اتصل بالرقم 122 وابدأ الإنعاش القلبي الرئوي (CPR)."},{text:"أصوّر مقطع فيديو من بعيد",correct:!1,feedback:"التصوير لا يساعد؛ هذا الشخص يحتاج الآن إلى الإنعاش وجهاز AED، فاتصل بالرقم 122 وابدأ الضغطات."}]},quiz:[{question:"في الإنعاش القلبي الرئوي (CPR)، ما عمق الضغط للبالغين؟",options:[{text:"2 سم",correct:!1},{text:"5-6 سم",correct:!0},{text:"10 سم",correct:!1},{text:"لا يوجد فرق",correct:!1}],explanation:"لجميع البالغين، بمن فيهم كبار السنّ، اضغط بعمق 5-6 سم وبمعدل 100-120 ضغطة في الدقيقة، ولا تقلّل العمق."},{question:"مَن يستطيع استخدام جهاز AED؟",options:[{text:"الأطباء فقط",correct:!1},{text:"أيّ شخص — فالجهاز يعطي التعليمات صوتيًّا",correct:!0},{text:"رجال الإطفاء فقط",correct:!1},{text:"لا أحد خارج المستشفى",correct:!1}],explanation:"يمكن لأيّ شخص استخدام جهاز AED: فهو يعطي التعليمات صوتيًّا، واستخدامه المبكر يزيد فرصة النجاة كثيرًا."},{question:"كيف يُجرى الإنعاش القلبي الرئوي (CPR) للرضّع (أقل من سنة واحدة)؟",options:[{text:"باليدين، كما للبالغين",correct:!1},{text:"بالإبهامين (مع إحاطة الصدر باليدين) أو بكعب راحة يد واحدة، والعمق نحو 4 سم",correct:!0},{text:"بإصبعين، 2 سم",correct:!1},{text:"لا يُجرى الإنعاش القلبي الرئوي (CPR) للرضّع",correct:!1}],explanation:"للرضّع، استخدم الإبهامين مع إحاطة الصدر باليدين، أو كعب راحة يد واحدة، بعمق نحو 4 سم. ولم تعد طريقة الإصبعين تُدرَّس (AHA 2025)."},{question:"بعد وضع العاصبة (تورنيكيه)، ماذا يجب أن تفعل؟",options:[{text:"أُرخيها بعد 10 دقائق",correct:!1},{text:"أسجّل وقت وضعها ولا أُرخيها أبدًا حتى يصل الفريق الطبي",correct:!0},{text:"أفكّها كل نصف ساعة ثم أربطها من جديد",correct:!1},{text:"أنزعها فورًا عندما يتوقّف النزيف",correct:!1}],explanation:"سجّل وقت وضع العاصبة، ولا تُرخِها ولا تنزعها أبدًا؛ فالفريق الطبي وحده هو من ينزعها."},{question:"رضيع عمره أقل من سنة واحدة اختنق بجسم غريب ولا يزال واعيًا. ماذا تفعل؟",options:[{text:"ضغطات بطنية (Heimlich) فورًا",correct:!1},{text:"5 ضربات على الظهر + 5 ضغطات على الصدر",correct:!0},{text:"إنعاش قلبي رئوي (CPR) فورًا",correct:!1},{text:"أتركه وحده",correct:!1}],explanation:"للرضيع الواعي المختنق: 5 ضربات على الظهر ورأسه أخفض من صدره، ثم 5 ضغطات على الصدر. ولا تُجرِ أبدًا ضغطات بطنية للرضيع."}]},{id:16,icon:"DoorOpen",accent:"#dc2626",title:"النجاة من حريق المنزل",subtitle:"أجهزة إنذار الدخان وخطة إخلاء الأسرة وما تفعله إذا حوصرت",summary:"قد ينتشر حريق المنزل بسرعة كبيرة: فبعد أن يرنّ جهاز إنذار الدخان قد لا يكون أمامك أكثر من دقيقتين للخروج بأمان. وتنقذ الأرواحَ أجهزةُ إنذار دخان تعمل، وخطةُ إخلاء تدرّبت عليها الأسرة كلها، وقواعدُ بسيطة: اخرج، وابقَ في الخارج، وأغلق الأبواب خلفك، واتصل بالرقم 115 من الخارج.",blocks:[{heading:"أجهزة إنذار الدخان: التحذير المبكر",body:`يستطيع جهاز إنذار الدخان أن يوقظك عند وجود دخان، حتى في منتصف الليل.
• ركّب أجهزة إنذار الدخان في كل غرفة نوم، وخارج أماكن النوم، وفي كل طابق من المنزل، على السقف أو في أعلى الجدار، وفق تعليمات الشركة المصنّعة.
• أبعِدها عن موقد الطبخ وعن باب الحمّام، حتى لا يطلقها دخان الطبخ وبخار الماء.
• اختبر كل جهاز مرة في الشهر بزر الاختبار.
• استبدل البطاريات القابلة للاستبدال مرة في السنة على الأقل، وفورًا إذا أخذ الجهاز يصدر صفيرًا قصيرًا متكررًا (علامة ضعف البطارية).
• استبدل الجهاز كله عندما يبلغ عمره 10 سنوات من تاريخ صنعه، أو قبل ذلك إذا نصّت تعليمات الشركة المصنّعة على ذلك.
• لا تنزع البطارية ولا تعطّل الجهاز أبدًا لأن الطبخ يطلقه.`},{heading:"خطة إخلاء الأسرة",body:`ضعوا الخطة معًا وتدرّبوا عليها مع كل من يسكن المنزل.
1. ارسم مخططًا بسيطًا للمنزل يُظهر كل الأبواب والنوافذ.
2. حدّد طريقين للخروج من كل غرفة إن أمكن: الباب وطريقًا ثانيًا، كنافذة تُفتح.
3. أبقِ الممرات والدرج والمخارج خالية. ويجب أن تُفتح الأبواب وقضبان النوافذ الواقعة على طريق الخروج بسرعة من الداخل؛ واحفظ أي مفتاح في مكان ثابت بجانب الباب.
4. اختر نقطة تجمّع في الخارج، أمام المنزل وعلى مسافة آمنة منه، كشجرة أو عمود كهرباء، يُعدّ فيها الجميع.
5. حدّد من سيساعد الأطفال وكبار السن والأشخاص ذوي الإعاقة على الخروج.
6. تدرّبوا على الخطة مرتين في السنة على الأقل، ليلًا ونهارًا.`},{heading:"عندما يرنّ الإنذار: اخرج وابقَ في الخارج",body:`• اصرخ «حريق!» لتنبيه الجميع، واخرج فورًا من أقرب طريق آمن، ولا تتوقف لجمع الأغراض.
• إذا كان هناك دخان فانخفض وتقدّم تحته نحو طريق الخروج: فالهواء الأنظف قريب من الأرض.
• قبل أن تفتح بابًا مغلقًا، تحسّس الباب ومقبضه بظاهر يدك. فإن كان ساخنًا، أو كان الدخان يتسرّب من حوله، فأبقِه مغلقًا واستعمل طريقك الثاني.
• أغلق الأبواب خلفك وأنت تخرج: فالباب المغلق يبطئ انتشار الدخان والحرارة والنار.
• استعمل الدرج، ولا تستعمل المصعد أبدًا.
• اذهب إلى نقطة التجمّع واتصل بالرقم 115 من الخارج، واذكر العنوان وعلامة دالّة قريبة أولًا.
• لا تعد إلى الداخل أبدًا من أجل الأشخاص أو الحيوانات الأليفة أو الأغراض. وإذا فُقد أحد فأخبر رجال الإطفاء فورًا بالمكان الذي قد يكون فيه.`},{heading:"إذا حوصرت: أغلق الباب، وسدّ الفتحات، واتصل، وأشِر",body:`إذا سدّ الدخان أو النار طريقي الخروج كليهما:
1. ابقَ في غرفة فيها نافذة، وأغلق الباب الفاصل بينك وبين النار.
2. ضع مناشف أو بطانيات أو ملابس حول الباب وفوق فتحات التهوية لمنع دخول الدخان.
3. اتصل بالرقم 115 وحدّد مكانك بدقة: العنوان والطابق والغرفة، ولا تُنهِ المكالمة حتى يُطلب منك ذلك.
4. أشِر من النافذة بقطعة قماش فاتحة اللون أو بمصباح يدوي ليراك رجال الإطفاء. وإذا فتحت النافذة لتتنفّس فأغلقها من جديد إذا دخل الدخان.
5. ابقَ منخفضًا وانتظر رجال الإطفاء، ولا تقفز من طابق علوي.`},{heading:"اشتعال الملابس والحروق",body:`• إذا اشتعلت ملابسك: توقّف، وانبطح على الأرض، وغطِّ وجهك بيديك، وتدحرج مرارًا حتى ينطفئ اللهب، ولا تركض.
• إذا لم يستطع الشخص الانبطاح والتدحرج، فأخمد اللهب ببطانية ثقيلة أو معطف.
• برّد الحرق فورًا تحت ماء جارٍ بارد لمدة 20 دقيقة، ولا تضع عليه ثلجًا أو زبدة أو معجون أسنان أو كريمات، ولا تفقأ الفقاعات.
• انزع الخواتم والساعات والملابس القريبة من الحرق، ولكن لا تنزع ما التصق بالجلد. ثم ضع عليه برفق غلافًا بلاستيكيًا نظيفًا أو قطعة قماش نظيفة.
• اتصل بالرقم 122 إذا كان الحرق كبيرًا أو عميقًا، أو في الوجه أو اليدين أو القدمين أو الأعضاء التناسلية، أو ناتجًا عن الكهرباء أو مادة كيميائية، أو إذا كان المصاب يتنفّس بصعوبة.`}],tips:["أغلق ليلًا أبواب غرف النوم والمطبخ: فالباب المغلق يبطئ انتشار الدخان والنار.","احتفظ بمصباح يدوي وهاتفك بجانب سريرك.","تأكّد أن رقم منزلك أو علامة دالّة واضحة يُرى من الشارع ليلًا ونهارًا.","اكتب الرقمين 115 و122 وعنوانك الكامل مع علامة دالّة في مكان يراه الجميع.","علّم الأطفال خطة الإخلاء ونقطة التجمّع: يخرجون ويخبرون شخصًا بالغًا، ولا يحاولون إطفاء الحريق أبدًا."],warnings:["لا تعد أبدًا إلى مبنى يحترق، ولو من أجل أحد أفراد الأسرة: أخبر رجال الإطفاء بمكان الشخص.","لا تمشِ منتصبًا في الدخان، ولا تفتح أبدًا بابًا تشعر بأنه ساخن.","لا تستعمل المصعد أبدًا أثناء الحريق."],activity:{prompt:"يوقظك جهاز إنذار الدخان ليلًا. تلمس باب غرفة نومك بظاهر يدك فتجده ساخنًا. غرفتك في الطابق الثالث وفيها نافذة. ماذا تفعل؟",options:[{text:"أفتح الباب بسرعة وأركض عبر الممر نحو الدرج.",correct:!1,feedback:"الباب الساخن يعني وجود نار أو دخان شديد الحرارة خلفه، وفتحه قد يُدخلهما إلى غرفتك. أبقِه مغلقًا واستعمل طريقك الثاني أو انتظر عند النافذة."},{text:"أُبقي الباب مغلقًا، وأسدّ الفتحات حوله بالمناشف أو الملابس، وأتصل بالرقم 115 وأذكر العنوان والطابق والغرفة، وأشير من النافذة بقطعة قماش فاتحة اللون.",correct:!0,feedback:"الباب المغلق المسدود يحميك من الدخان والنار، ويحتاج الرقم 115 إلى موقعك الدقيق ليصل إليك بسرعة."},{text:"أقفز من النافذة فورًا قبل أن يصل الدخان إلى الغرفة.",correct:!1,feedback:"القفز من الطابق الثالث قد يقتلك أو يصيبك إصابة بالغة. أغلق الباب، واتصل بالرقم 115، وأشِر من النافذة: فرجال الإطفاء يستطيعون الوصول إليك هناك."},{text:"أختبئ تحت السرير وأنتظر بهدوء حتى يزول الدخان.",correct:!1,feedback:"الدخان لا يزول من تلقاء نفسه، ويجب أن يتمكّن رجال الإطفاء من العثور عليك. ابقَ عند النافذة، وأشِر، وأخبر الرقم 115 بمكانك."}]},quiz:[{question:"أين يجب تركيب أجهزة إنذار الدخان في المنزل؟",options:[{text:"في المطبخ فقط، فوق موقد الطبخ مباشرة",correct:!1},{text:"في كل غرفة نوم، وخارج أماكن النوم، وفي كل طابق",correct:!0},{text:"في غرفة الجلوس فقط، بجانب الباب الرئيسي، حيث يسمعها الجميع",correct:!1},{text:"داخل خزانة، حيث لا يصل إليها الغبار ولا الأطفال",correct:!1}],explanation:"مكان أجهزة إنذار الدخان في كل غرفة نوم، وخارج أماكن النوم، وفي كل طابق. أما فوق الموقد مباشرة فيطلقها دخان الطبخ، فيميل الناس إلى تعطيلها."},{question:"كم مرة يجب اختبار كل جهاز إنذار دخان بزر الاختبار؟",options:[{text:"مرة كل خمس سنوات",correct:!1},{text:"مرة في الشهر",correct:!0},{text:"فقط عند تغيير البطارية",correct:!1},{text:"أبدًا: فالاختبار يُتلف الجهاز",correct:!1}],explanation:"اختبر كل جهاز مرة في الشهر، واستبدل البطاريات القابلة للاستبدال مرة في السنة على الأقل، واستبدل الجهاز كله بعد 10 سنوات أو وفق تعليمات الشركة المصنّعة."},{question:"خرجت من المنزل المحترق، لكن أحد أفراد الأسرة ما زال مفقودًا. ماذا تفعل؟",options:[{text:"أبقى في الخارج، وأتصل بالرقم 115، وأخبر رجال الإطفاء بالمكان الذي قد يكون فيه",correct:!0},{text:"أعود إلى الداخل بسرعة للبحث عنه قبل وصول رجال الإطفاء إلى المنزل",correct:!1},{text:"أنتظر صامتًا عند نقطة التجمّع حتى تنطفئ النار",correct:!1},{text:"أرسل طفلًا إلى الداخل، لأن الأطفال صغار وسريعون",correct:!1}],explanation:"لا تعد أبدًا إلى مبنى يحترق. فلدى رجال الإطفاء ملابس واقية وأجهزة تنفّس، وإخبارهم فورًا بمكان الشخص هو أسرع مساعدة."},{question:"سدّ الدخان والنار طريقي الخروج من غرفتك. ماذا تفعل أولًا؟",options:[{text:"أفتح الباب والنافذة على مصراعيهما ليخرج الدخان من الغرفة",correct:!1},{text:"أقفز من النافذة فورًا، ولو من طابق علوي",correct:!1},{text:"أغلق الباب، وأسدّ الفتحات، وأتصل بالرقم 115 وأذكر مكاني",correct:!0},{text:"أختبئ في خزانة الملابس، حيث لا يصل الدخان إليّ",correct:!1}],explanation:"الباب المغلق المسدود يمنع الدخان مدة أطول. أخبر الرقم 115 بالعنوان والطابق والغرفة، ثم أشِر من النافذة ليجدك رجال الإطفاء."},{question:"اشتعلت ملابسك. ماذا يجب أن تفعل؟",options:[{text:"أركض إلى الخارج بسرعة لتطفئ الريح اللهب",correct:!1},{text:"أتوقّف، وأنبطح على الأرض، وأغطّي وجهي، وأتدحرج حتى ينطفئ اللهب",correct:!0},{text:"أقف ساكنًا وأنتظر حتى يُحضر أحدهم الماء من المطبخ",correct:!1},{text:"أخلع الملابس المشتعلة وأنا أركض إلى الحمّام",correct:!1}],explanation:"التوقّف والانبطاح والتدحرج يخمد اللهب؛ فلا تركض. وبعد ذلك برّد الحرق تحت ماء جارٍ بارد لمدة 20 دقيقة، واتصل بالرقم 122 إذا كان الحرق خطيرًا."}],media:[{kind:"image",src:"media/images/w7_home_escape_plan.webp",title:"أسرة تتدرّب على خطة إخلاء المنزل",description:"يخرج الوالدان والأطفال من المنزل منخفضين تحت الدخان، ويغلقون الباب خلفهم، ويجتمعون عند نقطة التجمّع في الخارج."}]},{id:17,icon:"Fuel",accent:"#b45309",title:"المدافئ وأسطوانات الغاز وأول أكسيد الكربون والمولّدات",subtitle:"التدفئة الآمنة وأسطوانات الغاز المسال والغاز الخفي CO والمولّدات في المنزل والحيّ",summary:"في الشتاء وأثناء انقطاع الكهرباء، تستعمل بيوت كثيرة مدافئ الغاز والنفط الأبيض (الكيروسين) وأسطوانات الغاز المسال (LPG) والمولّدات. وإذا أسيء استعمالها فقد تسبّب الحرائق والانفجارات والتسمّم بأول أكسيد الكربون (CO)، وهو غاز لا يُرى ولا تُشمّ له رائحة. يقدّم هذا الدرس قواعد السلامة لكل منها، ويشرح ما تفعله إذا شممت رائحة الغاز أو ظهرت على أحد علامات التسمّم بأول أكسيد الكربون.",blocks:[{heading:"مدافئ الغاز والنفط الأبيض",body:`• استعمل مدفأة سليمة واتبع تعليمات الشركة المصنّعة، ولا تستعمل إلا الوقود الذي تحدّده الشركة: لا تضع البنزين أبدًا في مدفأة النفط الأبيض.
• أبعِد كل ما يمكن أن يحترق (الستائر والفراش والملابس والأثاث) مسافة متر واحد (3 أقدام) على الأقل عن المدفأة، وأبعِد الأطفال عنها.
• ضع المدفأة على أرض مستوية ثابتة، بعيدًا عن الأبواب وعن أماكن مرور الناس.
• المدفأة التي لا مدخنة لها (أنبوب يُخرج العادم إلى الخارج) تطلق عادمها داخل الغرفة: فأبقِ باب الغرفة مفتوحًا على بقية المنزل وافتح نافذة قليلًا لدخول الهواء النقي.
• أطفئ مدافئ الغاز والنفط الأبيض المتنقّلة قبل النوم وعند مغادرة الغرفة.
• املأ مدفأة النفط الأبيض في الخارج، وبعد إطفائها وبرودتها فقط.
• إذا اشتعلت المدفأة بلهب مفاجئ أو احترقت فلا تحملها: أطفئها بمفتاح الإيقاف إن كان ذلك آمنًا، وإلا فأخرج الجميع وأغلق الباب واتصل بالرقم 115.`},{heading:"أسطوانات الغاز المسال (LPG)",body:`• استعمل أسطوانات ومنظّمات وخراطيم سليمة، ولا تستعمل أي جزء تالف أو متشقّق أو يتسرّب منه الغاز.
• أبقِ الأسطوانة قائمة في مكان جيد التهوية، بعيدًا عن المدافئ والطبّاخات وأشعة الشمس المباشرة وأي مصدر حرارة آخر.
• الغاز المسال أثقل من الهواء: فالغاز المتسرّب يتجمّع قرب الأرض وفي الأماكن المنخفضة. لا تضع الأسطوانات في سرداب، ولا تخزّن الأسطوانات الاحتياطية في غرف النوم أو قرب طريق الخروج.
• اطلب من فنيّ مؤهل تركيب المنظّم والخرطوم والوصلات وفحصها، واستبدل الخرطوم المتشقّق أو المتصلّب أو القديم.
• لا تبحث أبدًا عن التسرّب بلهب أو عود ثقاب أو قدّاحة. فالفنيّ يفحص الوصلات بماء الصابون: والفقاعات تدلّ على التسرّب.
• أغلق صمّام الأسطوانة عندما لا تستعمل الغاز.`},{heading:"إذا شممت رائحة الغاز",body:`1. لا تُشعل أي لهب، ولا تُشغّل المصابيح أو الأجهزة ولا تُطفئها. لا تستعمل الهاتف في الداخل، ولا تشغّل مولّدًا أو سيارة في مكان قريب.
2. افتح الأبواب والنوافذ في طريقك إلى الخارج إن استطعت ذلك بسرعة.
3. لا تُغلق صمّام الغاز إلا إذا كان قريبًا منك وتستطيع الوصول إليه دون الدخول إلى المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة؛ وإلا فلا تقترب منه.
4. أخرج الجميع ونبّه الجيران.
5. اتصل بالرقم 115 من الخارج، ولا تعد إلى الداخل حتى يؤكّد المختصون أن المكان آمن.`},{heading:"أول أكسيد الكربون (CO): السمّ الخفي",body:`يتكوّن أول أكسيد الكربون (CO) عند احتراق الوقود: في المدافئ والطبّاخات وسخّانات الماء والمولّدات ومحرّكات السيارات والفحم. وهو غاز بلا لون ولا رائحة.
• علامات التسمّم بأول أكسيد الكربون: الصداع والدوار والضعف والغثيان أو القيء وألم الصدر والارتباك. وإذا شعر عدة أشخاص في المكان نفسه بالمرض في الوقت نفسه ففكّر في أول أكسيد الكربون.
• قد يموت النائمون بأول أكسيد الكربون قبل أن يلاحظوا أي علامة.
• ركّب جهاز إنذار لأول أكسيد الكربون قرب أماكن النوم، واختبره مرة في الشهر، واتبع تعليمات الشركة المصنّعة.
• اطلب من فنيّ مؤهل فحص المدافئ وسخّانات الماء والمداخن كل سنة.
• لا تدفّئ المنزل أبدًا بفرن الغاز، ولا تُدخل منقل الفحم أو الشوّاية إلى الداخل أبدًا.`},{heading:"إذا رنّ إنذار أول أكسيد الكربون أو شعر الناس بالمرض",body:`• أخرج الجميع إلى الهواء الطلق فورًا، ولا تُطفئ المدفأة في طريقك إلا إذا كان ذلك سريعًا وآمنًا.
• من الخارج اتصل بالرقم 122 لكل من تظهر عليه العلامات ولو بدأ يتحسّن، واتصل بالرقم 115.
• لا تعد إلى الداخل لإنقاذ أحد: انتظر الفرق المدرّبة.
• لا يعود أحد إلى الداخل حتى يؤكّد المختصون أن المكان آمن ويُفحص الجهاز.`},{heading:"المولّدات في المنزل والحيّ",body:`• شغّل المولّد المتنقّل في الخارج فقط، على بعد 6 أمتار (20 قدمًا) على الأقل من النوافذ والأبواب وفتحات التهوية، مع توجيه العادم بعيدًا عن المباني. ولا تشغّله أبدًا داخل المنزل أو المرآب أو السرداب أو المحل أو المخزن، أو على شرفة مغلقة، حتى لو كانت الأبواب والنوافذ مفتوحة.
• قبل إعادة التزويد بالوقود، أطفئ المولّد واتركه حتى يبرد: فالوقود المنسكب على الأجزاء الساخنة قد يشتعل. واحفظ الوقود خارج أماكن السكن في وعاء مناسب مغلق.
• لا توصل المولّد أبدًا بمقبس الجدار أو بأسلاك كهرباء المنزل (التغذية العكسية Backfeeding): فقد يقتل الجيران وعمال الكهرباء. ولا يوصله إلا كهربائي مختص عبر مفتاح تحويل (Transfer Switch).
• مولّدات الأحياء (الأهلية): لا تلمس كابلاتها أو مفاتيحها بنفسك. أبلغ صاحب المولّدة عن الكابلات المرتخية أو التالفة أو الشرر أو رائحة الاحتراق، واتصل بالرقم 115 في الطوارئ. ولا يركّب مفتاح التحويل بين المولّدة الأهلية والكهرباء الوطنية في منزلك إلا كهربائي مختص.`}],tips:["ركّب في المنزل جهاز إنذار للدخان وجهاز إنذار لأول أكسيد الكربون، واختبرهما مرة في الشهر.","اطلب من فنيّ مؤهل فحص المدافئ وأجهزة الغاز كل سنة.","اترك حول المدفأة منطقة آمنة لا تقل عن متر واحد (3 أقدام)، ولا سيما للأطفال.","أغلق صمّام الأسطوانة عندما لا تستعمل الغاز.","احفظ وقود المدفأة ووقود المولّد خارج أماكن السكن، في أوعية مناسبة مغلقة بعيدًا عن الحرارة."],warnings:["لا تشغّل أبدًا مولّدًا أو منقل فحم أو شوّاية داخل المنزل، حتى لو كانت الأبواب والنوافذ مفتوحة.","لا تبحث أبدًا عن تسرّب الغاز بلهب.","لا توصل المولّد أبدًا بمقبس الجدار أو بأسلاك كهرباء المنزل."],activity:{prompt:"في ليلة باردة، ظلّت مدفأة النفط الأبيض مشتعلة ساعات في غرفة الجلوس المغلقة. أمك وابنك كلاهما يعاني صداعًا ودوارًا وغثيانًا. ماذا تفعل؟",options:[{text:"أعطيهما أقراصًا للصداع، وأفتح النافذة قليلًا، ونبقى في الغرفة الدافئة.",correct:!1,feedback:"الأقراص لا تُخرج أول أكسيد الكربون من الجسم، وفتحة صغيرة لا تكفي بعد ظهور العلامات. يجب أن يخرج الجميع إلى الهواء الطلق وأن تتصل بالرقم 122."},{text:"أُخرج الجميع إلى الهواء الطلق فورًا، ولا أُطفئ المدفأة في طريقي إلا إذا كان ذلك سريعًا وآمنًا، وأتصل بالرقمين 122 و115 من الخارج؛ ولا يعود أحد إلى الداخل حتى يُفحص المكان.",correct:!0,feedback:"شخصان بالعلامات نفسها قرب مدفأة مشتعلة يدلّان على التسمّم بأول أكسيد الكربون: فالهواء الطلق والاتصال بالرقم 122 يأتيان أولًا، ويجب فحص المدفأة قبل استعمالها مرة أخرى."},{text:"أُطفئ المدفأة وأتركهما ينامان، لأن الراحة تفيد الصداع.",correct:!1,feedback:"قد يموت النائمون بأول أكسيد الكربون دون أن يستيقظوا. أخرج الجميع إلى الهواء الطلق واتصل بالرقم 122."},{text:"أضيف مزيدًا من النفط الأبيض لتشتعل المدفأة أفضل ويقلّ دخانها.",correct:!1,feedback:"زيادة الوقود لا توقف أول أكسيد الكربون. يحتاج هذان الشخصان الآن إلى الهواء الطلق والمساعدة الطبية: أخرجهما واتصل بالرقم 122."}]},quiz:[{question:"كم يجب أن تبعد الستائر والفراش وسائر الأشياء القابلة للاحتراق عن المدفأة؟",options:[{text:"نحو 10 سنتيمترات تكفي",correct:!1},{text:"متر واحد (3 أقدام) على الأقل",correct:!0},{text:"أي مسافة، إذا كانت المدفأة جديدة",correct:!1},{text:"لا حاجة إلى مسافة، إذا كانت المدفأة منخفضة",correct:!1}],explanation:"أبعِد كل ما يمكن أن يحترق مسافة متر واحد (3 أقدام) على الأقل عن المدافئ، وأبعِد الأطفال عنها أيضًا."},{question:"ما الطريقة الآمنة لفحص خرطوم الغاز المسال ووصلاته بحثًا عن تسرّب؟",options:[{text:"أُقرّب عود ثقاب مشتعلًا من الوصلة وأراقب هل يظهر لهب",correct:!1},{text:"أُشعل الطبّاخ وأستمع إلى صوت اللهب",correct:!1},{text:"يفحصها فنيّ مؤهل بماء الصابون",correct:!0},{text:"أشمّ الخرطوم عن قرب وصمّام الأسطوانة مفتوح بالكامل",correct:!1}],explanation:"قد يُشعل اللهبُ الغازَ المتسرّب فيسبّب حريقًا أو انفجارًا. ويفحص الفنيّ المؤهل الوصلات بماء الصابون: والفقاعات تدلّ على التسرّب."},{question:"أيّ مما يأتي قد يكون علامة على التسمّم بأول أكسيد الكربون (CO)؟",options:[{text:"رائحة غاز قوية تصدر من المدفأة",correct:!1},{text:"صداع ودوار لدى عدة أشخاص معًا",correct:!0},{text:"دخان أزرق تراه بوضوح قرب الأرض",correct:!1},{text:"طفح جلدي يظهر بعد أسبوع",correct:!1}],explanation:"أول أكسيد الكربون بلا لون ولا رائحة. والصداع والدوار والضعف والغثيان، ولا سيما لدى عدة أشخاص معًا قرب أجهزة حرق الوقود، علامات خطر. أما رائحة الغاز فتعني تسرّب الغاز، لا أول أكسيد الكربون."},{question:"أين يمكن تشغيل المولّد المتنقّل بأمان؟",options:[{text:"في الخارج، على بعد 6 أمتار (20 قدمًا) على الأقل من النوافذ والأبواب وفتحات التهوية",correct:!0},{text:"في المرآب، ما دام بابه الكبير مفتوحًا بالكامل",correct:!1},{text:"على شرفة مغلقة، والنافذة المجاورة لها مفتوحة للهواء النقي",correct:!1},{text:"داخل المنزل، بجانب نافذة مفتوحة، مع مروحة تُخرج الدخان",correct:!1}],explanation:"عادم المولّد يحتوي على أول أكسيد الكربون، وقد يقتل في دقائق داخل المنزل. شغّل المولّد في الخارج فقط، على بعد 6 أمتار (20 قدمًا) على الأقل من النوافذ والأبواب وفتحات التهوية، مع توجيه العادم بعيدًا عن المباني."},{question:"كيف يجوز توصيل المولّد بأسلاك كهرباء المنزل؟",options:[{text:"بتوصيله بمقبس الجدار بسلك له قابسان",correct:!1},{text:"على يد كهربائي مختص فقط، عبر مفتاح تحويل",correct:!0},{text:"على يد صاحب المنزل، مباشرة بلوحة المصاهر، أثناء انقطاع الكهرباء",correct:!1},{text:"على يد أي جار سبق أن وصل مولّدًا",correct:!1}],explanation:"توصيل المولّد بمقبس الجدار أو بأسلاك المنزل (التغذية العكسية) قد يصعق الجيران وعمال الكهرباء. ولا يوصله إلا كهربائي مختص عبر مفتاح تحويل."}],media:[{kind:"image",src:"media/images/w7_heaters_gas_generators.webp",title:"تدفئة آمنة ومولّد في الخارج",description:"مدفأة حولها منطقة آمنة خالية، وأسطوانة غاز قائمة بخرطوم مفحوص، وجهاز إنذار لأول أكسيد الكربون على الجدار، ومولّد يعمل في الخارج بعيدًا عن النوافذ."}]},{id:18,icon:"Building",accent:"#4f46e5",title:"السكن في الشقق والمباني العالية",subtitle:"المخارج والدرج وأبواب الحريق وما تفعله عند نشوب حريق في مبناك",summary:"في العمارة السكنية قد يعرّض حريقٌ في شقة واحدة الجميعَ للخطر: فالدخان ينتشر عبر الممرات والدرج، وطريق الخروج أطول. ومعرفة المخارج، والمحافظة على الدرج وأبواب الحريق صالحة، ومعرفة متى تخرج ومتى تبقى في شقتك، كلها قد تنقذ أسرتك. اتبع دائمًا خطة مبناك وتعليمات الدفاع المدني.",blocks:[{heading:"تعرّف على مبناك قبل الحريق",body:`• اعرف أماكن كل سلالم الخروج في طابقك، تحسّبًا لانسداد أقربها بالنار أو الدخان. وعُدّ الأبواب بين شقتك وكل درج، لتجده في الظلام أو في الدخان.
• اسأل إدارة المبنى عن وسائل السلامة من الحريق فيه (إنذار الحريق، والمطافئ، وإنارة الطوارئ، وخطة الإخلاء)، وعن الطريقة التي يُطلب من السكان أن يستجيبوا بها للإنذار.
• ضع خطة إخلاء لشقتك، واتفقوا على نقطة تجمّع خارج المبنى.
• اعرف أيّ جيران طابقك سيحتاجون إلى مساعدة في نزول الدرج، ككبار السن والأشخاص ذوي الإعاقة، واتفق مع الإدارة والجيران على من سيساعدهم.`},{heading:"الدرج والممرات وأبواب الحريق",body:`• لا تضع أي شيء أبدًا في الممرات أو على الدرج أو أمام أبواب الخروج: لا أثاث ولا أحذية ولا دراجات ولا أسطوانات غاز ولا وقود.
• يجب أن تنغلق أبواب الحريق وأبواب الدرج من تلقاء نفسها وأن تبقى مغلقة. لا تثبّتها مفتوحة أبدًا ولا تربطها، وأبلغ الإدارة عن أي تلف في الأبواب أو أجهزة الإغلاق أو موانع التسرّب.
• يجب ألا تكون أبواب الخروج والدرج مقفلة أو مسدودة، وأن تُفتح من الداخل دون مفتاح.
• لا تمرّر كابلات المولّد أو أسلاك التمديد أو الخراطيم عبر أبواب الدرج أو أبواب الحريق: فهي تمنع الأبواب من الانغلاق.`},{heading:"استعمل الدرج، ولا تستعمل المصعد أبدًا",body:`عند الحريق استعمل الدرج للخروج. ولا تستعمل المصعد إلا إذا طلب منك رجال الإطفاء ذلك: فقد يتوقف ويحتجزك بين الطوابق في الدخان.

إذا لم يستطع أحد استعمال الدرج فلا تُدخله المصعد. أخبر الرقم 115 ورجال الإطفاء فورًا بمكان الشخص بدقة: الطابق ورقم الشقة.`},{heading:"إذا كان الحريق في شقتك",body:`1. نبّه كل من في الشقة واخرج فورًا.
2. أغلق باب الشقة خلفك: فالباب المغلق يُبقي الدخان والنار في الداخل.
3. نبّه الجيران: اطرق أبوابهم واصرخ «حريق!»، واضغط زر إنذار الحريق إن وُجد في المبنى.
4. انزل بالدرج لا بالمصعد.
5. اتصل بالرقم 115 من الخارج: اذكر العنوان والطابق ورقم الشقة، واذهب إلى نقطة التجمّع.`},{heading:"إذا كان الحريق في مكان آخر من المبنى",body:`• عندما يرنّ الإنذار أو تشمّ رائحة دخان، تحسّس باب شقتك بظاهر يدك قبل أن تفتحه.
• إذا كان الباب باردًا والممر والدرج خاليين، فاخرج من أقرب درج، وأغلق الأبواب خلفك، واذهب إلى نقطة التجمّع.
• إذا كان الباب ساخنًا، أو كان الممر أو الدرج مليئًا بالدخان، فابقَ في شقتك: أبقِ الباب مغلقًا، وضع مناشف أو شراشف مبلّلة حوله وفوق فتحات التهوية، واتصل بالرقم 115 واذكر العنوان والطابق ورقم الشقة.
• اذهب إلى نافذة أو شرفة بعيدة عن الدخان، وأشِر بقطعة قماش فاتحة اللون أو بمصباح يدوي. افتح نافذة قليلًا للهواء النقي، وأغلقها إذا دخل الدخان.
• استمع إلى الإعلانات، واتبع خطة مبناك وتعليمات الدفاع المدني ورجال الإطفاء: فالإنقاذ من مبنى عالٍ قد يستغرق وقتًا طويلًا.`},{heading:"الشرفات وأسطوانات الغاز والمولّدات والكابلات",body:`• لا تخزّن على الشرفات أسطوانات غاز احتياطية أو وقودًا أو أثاثًا قديمًا أو نفايات. وإذا كانت أسطوانة غاز الطبخ موضوعة هناك، فأبقِها قائمة بعيدًا عن الحرارة وأشعة الشمس المباشرة، وصمّامها مغلق حين لا تُستعمل.
• لا تشغّل المولّد على الشرفة أبدًا: فعادمه يحمل أول أكسيد الكربون إلى بيتك وبيوت جيرانك عبر النوافذ والأبواب.
• يجب أن يمدّ كابلات المولّد وكهرباء الحيّ كهربائي مختص. وأبلغ الإدارة عن الكابلات المرتخية أو التالفة أو الساخنة في المبنى.
• أطفئ السجائر تمامًا في منفضة عميقة، ولا ترمِها أبدًا من شرفة أو نافذة.`}],tips:["اعرف درجَي خروج على الأقل من طابقك.","احتفظ بمفاتيحك وهاتفك ومصباح يدوي بجانب سريرك، وخذها معك عند الخروج.","شارك في تمارين الإخلاء في المبنى كأنها حقيقية.","اطلب من الإدارة فحص إنذار الحريق وإنارة الطوارئ والمطافئ وأبواب الحريق بانتظام.","ركّب أجهزة إنذار الدخان داخل شقتك واختبرها مرة في الشهر."],warnings:["لا تستعمل المصعد أبدًا أثناء الحريق إلا إذا طلب منك رجال الإطفاء ذلك.","لا تثبّت أبدًا باب حريق أو باب درج مفتوحًا.","لا تدخل ممرًا أو درجًا مليئًا بالدخان: ابقَ في شقتك، وسدّ فتحات الباب، واتصل بالرقم 115."],activity:{prompt:"تسكن في الطابق السابع. رنّ إنذار الحريق. باب شقتك بارد، لكنك حين تفتحه قليلًا تجد الممر مليئًا بدخان كثيف. ماذا تفعل؟",options:[{text:"أنزل بسرعة بالمصعد، لأنه أسرع من سبعة طوابق من الدرج.",correct:!1,feedback:"لا تستعمل المصعد أبدًا عند الحريق: فقد يتوقف ويحتجزك في الدخان. ابقَ في شقتك واتصل بالرقم 115."},{text:"أحبس أنفاسي وأركض عبر الدخان نحو الدرج.",correct:!1,feedback:"الدخان سامّ وقد تضلّ طريقك فيه. أغلق الباب، وسدّ الفتحات، واتصل بالرقم 115 من شقتك."},{text:"أغلق الباب من جديد، وأسدّ الفتحات حوله بمناشف مبلّلة، وأتصل بالرقم 115 وأذكر العنوان والطابق ورقم الشقة، وأشير من نافذة بعيدة عن الدخان.",correct:!0,feedback:"الدخان الكثيف في الممر يسدّ طريق الخروج، وباب شقتك المغلق يحميك حتى يُرسل الرقم 115 المساعدة إلى طابقك."},{text:"أترك باب الشقة مفتوحًا لأسمع وصول رجال الإطفاء.",correct:!1,feedback:"الباب المفتوح يُدخل الدخان إلى الشقة. أبقِه مغلقًا ومسدودًا، وأخبر الرقم 115 بمكانك."}]},quiz:[{question:"لماذا يجب أن تبقى أبواب الحريق وأبواب الدرج في المبنى مغلقة؟",options:[{text:"لتُبقي الممرات دافئة في الشتاء وتوفّر الكهرباء على الجميع",correct:!1},{text:"لأنها تبطئ انتشار الدخان والنار وتحمي درج الخروج",correct:!0},{text:"لتمنع الغرباء والأطفال من التنقّل بين الطوابق ليلًا",correct:!1},{text:"لأنها للزينة في الغالب، فلا يهمّ إن بقيت مفتوحة",correct:!1}],explanation:"باب الحريق المغلق يبطئ الدخان والحرارة والنار، ويُبقي الدرج صالحًا للخروج. لا تثبّته مفتوحًا أبدًا، وأبلغ عن أي باب لا ينغلق من تلقاء نفسه."},{question:"الحريق داخل شقتك. ما التصرّف الصحيح؟",options:[{text:"اخرج، وأغلق الباب خلفك، ونبّه الجيران، واتصل بالرقم 115",correct:!0},{text:"اترك باب الشقة مفتوحًا ليخرج الدخان إلى الممر",correct:!1},{text:"ابقَ في الداخل وحاول إطفاء حريق كبير بدلاء الماء",correct:!1},{text:"انزل بالمصعد، ثم اطلب من حارس المبنى أن يتولّى الأمر",correct:!1}],explanation:"إغلاق باب الشقة المحترقة يُبعد الدخان والنار عن الممر والدرج اللذين يحتاج إليهما جيرانك. نبّههم، واستعمل الدرج، واتصل بالرقم 115 من الخارج."},{question:"ما الذي يجب فعله بالأحذية أو الدراجات أو أسطوانات الغاز المتروكة في الممر أو على الدرج؟",options:[{text:"ترتيبها بجانب أحد الجدران ليتمكّن الناس من المرور",correct:!1},{text:"تركها هناك صيفًا ونقلها في الشتاء فقط",correct:!1},{text:"تغطيتها بقطعة قماش حتى لا تشتعل",correct:!1},{text:"إزالتها: فالممرات والدرج يجب أن تبقى خالية للخروج",correct:!0}],explanation:"عند الحريق يخرج الناس عبر الدخان والظلام، وأي شيء في الممر أو على الدرج قد يعيقهم أو يحترق. فلا يُخزّن شيء في الممرات أو على الدرج أو أمام المخارج."},{question:"متى يجوز لك استعمال المصعد أثناء حريق في مبناك؟",options:[{text:"عندما تسكن فوق الطابق الخامس",correct:!1},{text:"فقط عندما يطلب منك رجال الإطفاء استعماله",correct:!0},{text:"عندما يكون الدخان في الطوابق السفلى فقط",correct:!1},{text:"عندما تحمل أطفالًا أو أغراضًا ثقيلة",correct:!1}],explanation:"استعمل الدرج. فالمصعد قد يتوقف ويحتجز الناس في الدخان، ورجال الإطفاء هم من يقرّرون هل يجوز استعمال المصعد."},{question:"حاصرك دخان الممر في شقتك. ماذا تقول للرقم 115؟",options:[{text:"اسمك فقط، لأنهم سيجدون المبنى بأنفسهم",correct:!1},{text:"العنوان والطابق ورقم الشقة وعدد من معك",correct:!0},{text:"أن هناك دخانًا فقط، وسيتصلون بك لاحقًا ليسألوا عن التفاصيل",correct:!1},{text:"لا شيء الآن: تنتظر بهدوء حتى يطرق أحد الباب",correct:!1}],explanation:"يحتاج رجال الإطفاء إلى معرفة مكانك بدقة: العنوان والطابق والشقة، وعدد الموجودين. ولا تُنهِ المكالمة حتى يُطلب منك ذلك."}],media:[{kind:"image",src:"media/images/w7_apartment_fire_safety.webp",title:"الخروج الآمن من عمارة سكنية",description:"ينزل السكان على الدرج مارّين بباب حريق مغلق، بينما تنتظر أسرة في شقة أخرى عند النافذة وتُشير بقطعة قماش فاتحة اللون."}]},{id:19,icon:"Leaf",accent:"#c2410c",title:"حرائق المحاصيل وبقايا الحصاد والأعشاب",subtitle:"الوقاية من الحرائق في موسم الحصاد والسلامة عند اقتراب حريق الحقول",summary:"في الصيف تشتعل حقول القمح والشعير الجافة وبقايا الحصاد والأعشاب بسهولة، وقد تنشر الريح حريق الحقل بسرعة كبيرة. وكثيرًا ما يتسبّب الإنسان في هذه الحرائق: سيجارة، أو شرارة أو عادم ساخن من الآليات، أو نار أُشعلت لحرق بقايا الحصاد. يشرح هذا الدرس كيف نمنعها، وماذا نفعل عندما تقترب النار من حقولنا أو قريتنا أو بيوتنا.",blocks:[{heading:"لماذا حرائق الحقول خطيرة",body:`• تشتعل المحاصيل الجافة وبقايا الحصاد والأعشاب بسهولة، ولا سيما في الأيام الحارة الجافة العاصفة.
• تدفع الريح النار إلى الأمام وتحمل الجمر المتطاير أمام اللهب، فيُشعل حرائق جديدة.
• تنتشر النار أسرع ما تنتشر صعودًا على المنحدرات وفي اتجاه هبوب الريح.
• يحجب الدخان الطريق، وقد يحاصر حريق سريع الناس والحيوانات والمركبات داخل الحقل.`},{heading:"الوقاية في موسم الحصاد",body:`• قبل الحصاد وفي أثنائه، نظّف الحاصدات والجرّارات كل يوم من التبن والقش والغبار، ولا سيما حول المحرّك والعادم والشاحن التوربيني: فالغبار والقش اللذان يصلان إلى هذه الأجزاء الساخنة قد يشتعلان.
• افحص الآليات بحثًا عن المحامل (الرولمانات) البالية والسيور المنزلقة وتسرّب الوقود أو الزيت، وأصلح الأعطال قبل بدء العمل.
• احتفظ بالماء وبمطفأة حريق مناسبة على الحاصدة ومع فريق العمل.
• احرث أو نظّف خطًا عازلًا للنار (شريطًا من التربة العارية لا شيء فيه يحترق) حول الحقل وبين الحقول والقرية.
• أوقف العمل بالآليات حين يكون الجو شديد الحرارة والجفاف والرياح.
• لا تقُد السيارات والجرّارات ولا توقفها على العشب الجاف أو بقايا الحصاد: فالعادم الساخن قد يُشعلها.`},{heading:"لا تُشعل النار قرب الحقول",body:`• قد تفلت النار عند حرق بقايا الحصاد أو النفايات في العراء فتنتقل مع الريح إلى الحقول والبساتين والقرى المجاورة. وقبل أن تحرق أي شيء، استفسر من الدفاع المدني والجهات المحلية هل يُسمح بالحرق ومتى؛ ولا تحرق أبدًا في يوم جاف أو عاصف، ولا تترك النار وحدها أبدًا.
• لا ترمِ السجائر من السيارات أبدًا ولا تُلقِها في الحقول أو العشب، ولا تدخّن أثناء العمل في الحصاد.
• لا تُشعل نار الطبخ أو الشواء قرب المحاصيل أو العشب الجاف، وأطفئ أي نار إطفاءً تامًا بالماء قبل أن تغادر.
• أعِد القناني الزجاجية والنفايات إلى البيت: فالزجاج المتروك في الحقل قد يركّز أشعة الشمس على العشب الجاف.`},{heading:"عندما تقترب النار",body:`• اخرج مبكرًا، ولا تنتظر حتى تقترب النار: فالدخان واللهب قد يقطعان الطريق. وإذا طلبت منك الجهات المختصة المغادرة فغادر فورًا.
• لا تحاول إطفاء إلا نار صغيرة جدًا بدأت للتو، بالماء أو التراب، وبشرط أن يكون طريق خروجك خلفك وألا تدفع الريح النار نحوك. وإذا لم تنطفئ فورًا فاخرج.
• ابتعد عن مسار النار: لا تتجه أبدًا إلى حيث تدفعها الريح، ولا تصعد أبدًا منحدرًا فوقها. استعمل الطرق والممرات، واتجه إلى أرض قليلة أو خالية مما يحترق، كالأرض المحروثة.
• اتصل بالرقم 115 من مكان آمن واذكر الموقع بدقة (القرية أو الطريق أو الحقل أو علامة دالّة)، وقل هل تتجه النار نحو البيوت أو الناس.
• نبّه المزارعين الآخرين والقرية بالهاتف، لا بالركض أمام النار.`},{heading:"حماية القرى والبيوت",body:`• أبقِ المنطقة المحيطة بالبيوت ومخازن التبن وحظائر الحيوانات خالية من العشب الجاف والقش والحطب والنفايات لمسافة 9 أمتار (30 قدمًا) على الأقل.
• أبعِد أكوام التبن والقش عن البيوت والطرق، ولا تخزّن الوقود بجانبها.
• اتفقوا في القرية على من يتصل بالرقم 115، وأين يتجمّع الناس، وكيف يُنقل كبار السن والأطفال والحيوانات.
• أبقِ الطرق والبوابات خالية لتصل سيارات الإطفاء إلى القرية والحقول.
• عندما تقترب النار اتبع تعليمات الدفاع المدني، ولا تعد حتى يؤكّدوا أن المكان آمن.`}],tips:["نظّف الحاصدات والجرّارات كل يوم من أيام الحصاد، ولا سيما حول المحرّك والعادم.","احتفظ بالماء وبمطفأة حريق على كل حاصدة.","راقب الطقس: فالأيام الحارة الجافة العاصفة هي الأخطر.","احفظ الرقم 115 في هاتفك، واعرف علامة دالّة واضحة لكل حقل من حقولك.","نبّه المزارعين من حولك فور رؤيتك الدخان."],warnings:["لا ترمِ السيجارة أبدًا في العشب الجاف أو بقايا الحصاد، ولا من نافذة السيارة.","لا تحاول أبدًا إيقاف حريق حقل كبير بنفسك: اخرج واتصل بالرقم 115.","لا تهرب من النار أبدًا صعودًا على منحدر أو في اتجاه هبوب الريح."],activity:{prompt:"تحصد القمح بالحاصدة في ظهيرة حارة عاصفة. ترى دخانًا ولهبًا صغيرًا في بقايا الحصاد خلف الآلة، والريح تدفعهما نحو الحقل المجاور. ماذا تفعل؟",options:[{text:"أتوقّف، وأُبعد الآلة والناس عن مسار النار، وأتصل بالرقم 115 وأذكر الموقع بدقة، وأنبّه المزارعين القريبين؛ ولا أستعمل الماء أو المطفأة إلا ما دامت النار صغيرة جدًا وطريق خروجي مفتوحًا.",correct:!0,feedback:"حريق الحقل يكبر بسرعة مع الريح. فإبعاد الناس عن مساره والاتصال المبكر بالرقم 115 يأتيان أولًا؛ ولا يجوز التصدّي إلا لنار صغيرة جدًا، ومع طريق خروج آمن."},{text:"أقود الحاصدة عبر اللهب لأصل إلى الجانب الآخر من الحقل.",correct:!1,feedback:"القيادة عبر النار قد تحاصرك وتُشعل الآلة. ابتعد عن مسار النار واتصل بالرقم 115."},{text:"أواصل الحصاد، لأن نار بقايا الحصاد ستنطفئ من تلقاء نفسها.",correct:!1,feedback:"قد تحمل الريح النار إلى المحاصيل والبساتين والقرى. توقّف، وأبعِد الناس عن مسارها، واتصل بالرقم 115 فورًا."},{text:"أركض أمام النار، في اتجاه هبوب الريح، لأنبّه المزرعة المجاورة.",correct:!1,feedback:"الركض إلى حيث تدفع الريح النار يضعك في طريقها. نبّه الآخرين بالهاتف، وابتعد عن مسار النار."}]},quiz:[{question:"أيّ جزء من الحاصدة هو الأهمّ في إبقائه نظيفًا من التبن والغبار؟",options:[{text:"مقعد السائق ونوافذ المقصورة والمرايا",correct:!1},{text:"منطقة المحرّك، حول العادم الساخن والشاحن التوربيني",correct:!0},{text:"الإطارات والدرجات المؤدية إلى باب المقصورة",correct:!1},{text:"خزان الحبوب، بعد تفريغه في نهاية اليوم",correct:!1}],explanation:"التبن والغبار اللذان تدفعهما المراوح إلى العادم الساخن أو الشاحن التوربيني قد يشتعلان. نظّف منطقة المحرّك كل يوم من أيام الحصاد، وأكثر من ذلك في الأيام الحارة."},{question:"حريق حقل يتجه نحوك تدفعه الريح. في أي اتجاه تهرب؟",options:[{text:"إلى الأمام مباشرة في اتجاه هبوب الريح، بأقصى سرعة",correct:!1},{text:"صعودًا إلى أقرب تلّ، لترى إلى أين تتجه النار",correct:!1},{text:"بعيدًا عن مسارها عبر طريق، لا صعودًا ولا مع الريح",correct:!0},{text:"إلى داخل القمح القائم، حيث يخفيك الزرع الطويل عن الدخان",correct:!1}],explanation:"تسير النار أسرع ما تسير مع الريح وصعودًا. ابتعد عن مسارها عبر الطرق أو الممرات نحو أرض قليلة ما يحترق فيها، واتصل بالرقم 115."},{question:"ماذا تقول للرقم 115 عندما تبلّغ عن حريق حقل؟",options:[{text:"أن هناك دخانًا في مكان ما فقط، ثم أُنهي المكالمة بسرعة توفيرًا للوقت",correct:!1},{text:"الموقع الدقيق (القرية أو الطريق أو علامة دالّة) واتجاه سير النار",correct:!0},{text:"اسم صاحب الحقل ونوع المحصول وكم تبلغ قيمته",correct:!1},{text:"لا شيء آخر، لأن الدفاع المدني يرى كل حرائق الحقول من بعيد",correct:!1}],explanation:"يحتاج الدفاع المدني إلى الوصول إلى النار بسرعة: اذكر القرية والطريق وعلامة دالّة، وقل هل البيوت أو الناس في خطر، ولا تُنهِ المكالمة حتى يُطلب منك ذلك."},{question:"لماذا يُعدّ حرق بقايا الحصاد خطيرًا؟",options:[{text:"بقايا الحصاد لا تحترق جيدًا، فتنطفئ النار دائمًا من تلقاء نفسها فورًا",correct:!1},{text:"هو خطير ليلًا فقط، حين لا يرى الناس الدخان",correct:!1},{text:"قد تفلت النار مع الريح إلى الحقول والقرى القريبة",correct:!0},{text:"هو خطير على من يُشعل النار فقط، لا على غيره",correct:!1}],explanation:"النار التي تُشعل لأغراض زراعية قد تخرج عن السيطرة، ولا سيما في الأيام الجافة العاصفة. استفسر من الدفاع المدني والجهات المحلية قبل أي حرق، ولا تترك النار وحدها أبدًا."},{question:"أيّ مما يأتي قد يُشعل حريق حقل؟",options:[{text:"سيجارة رُميت من نافذة سيارة في العشب الجاف",correct:!0},{text:"شجرة خضراء قائمة في الظل على حافة الحقل",correct:!1},{text:"مطر يهطل على بقايا الحصاد بعد الحصاد",correct:!1},{text:"خزان ماء مغلق متوقف بجانب الحقل",correct:!1}],explanation:"السجائر والشرر والعوادم الساخنة للسيارات والآليات والنيران المشتعلة في العراء تُشعل كثيرًا من حرائق الحقول. لا ترمِ السجائر أبدًا، ولا توقف السيارة على العشب الجاف."}],media:[{kind:"image",src:"media/images/w7_crop_fire_prevention.webp",title:"الوقاية من الحريق في حقل قمح",description:"مزارع ينظّف منطقة محرّك الحاصدة بجانب خط عازل للنار محروث، وخزان ماء ومطفأة حريق جاهزان على حافة حقل قمح جاف."}]},{id:20,icon:"Bomb",accent:"#b45309",title:"الألغام والذخائر غير المنفجرة: ابقَ آمنًا",subtitle:"تعرّف على الخطر، وابتعد، وأبلِغ",summary:"يمكن أن تبقى الألغام والقنابل العنقودية وغيرها من الذخائر غير المنفجرة خطرة لعقود، حتى لو بدت قديمة أو صدئة أو غير مؤذية. ويستطيع كل شخص أن يبقى آمنًا باتباع قواعد قليلة: لا تلمس، وابتعد، وأبعِد الآخرين، وأبلِغ.",blocks:[{heading:"ما الذي قد يكون خطرًا",body:"تأتي الذخائر المتفجرة بأحجام وأشكال وألوان كثيرة. فقد تكون ملقاة على الأرض، أو مدفونة في التراب، أو مختبئة بين الأعشاب أو الأنقاض أو في المباني القديمة، أو معلّقة على الأشجار. تعامل مع ما يلي على أنه خطر:",points:["الألغام: غالبًا ما تكون مدفونة أو مخفية، ومن الصعب جدًّا رؤيتها.","القنيبلات الصغيرة من القنابل العنقودية: بعضها زاهي الألوان وقد يبدو كالألعاب.","قذائف المدفعية والصواريخ وقذائف الهاون والقنابل اليدوية غير المنفجرة.","أي جسم معدني أو بلاستيكي مجهول الشكل في مكان شهد قتالًا.","الأجسام القديمة أو الصدئة أو المكسورة: فقد تنفجر مع ذلك."]},{heading:"إذا رأيت جسمًا مشبوهًا",points:["توقّف ولا تقترب منه.","لا تلمسه ولا تحرّكه ولا تركله ولا تلتقطه، ولا ترمِ عليه أي شيء، ولا تحاول حرقه أبدًا.","نبّه من حولك وأبعِد الجميع عنه، وخاصةً الأطفال.","تذكّر المكان والمعالم القريبة منه.","ابتعد مسافة كافية قبل أن تستخدم الهاتف، ثم اتصل بالرقم 115 واتّبع تعليمات الدفاع المدني.","لا تنقل الجسم أبدًا إلى منزلك أو إلى مركز شرطة أو مركز دفاع مدني."]},{heading:"العلامات التحذيرية والمناطق المسيّجة",body:"تكون العلامات التحذيرية من مخاطر المتفجرات عادةً حمراء أو برتقالية، وكثيرًا ما تحمل رسم جمجمة وعظمتين متقاطعتين وكلمة «خطر» أو «ألغام». وقد تُعلَّم المنطقة الخطرة أيضًا بحجارة مطليّة باللون الأحمر أو بسياج أو أسلاك أو حبال أو أشرطة. وقد تختلف العلامات في منطقتك عن ذلك.",points:["احترم كل علامة وكل سياج، ولا تتجاوزهما أبدًا.","لا تُزِل أي علامة أبدًا ولا تحرّكها ولا تأخذها، حتى لو كانت قديمة أو مكسورة.","غياب العلامة لا يعني الأمان: فمعظم المناطق الخطرة غير معلَّمة.","كن حذرًا قرب الحقول التي غطّتها الأعشاب، والطرق المهجورة، والأنقاض، والمواقع العسكرية المهجورة؛ واستخدم الطرق الرئيسية والممرات المطروقة."]},{heading:"إذا ظننت أنك في منطقة ملغومة",body:`إذا رأيت لغمًا أو علامة تحذيرية أو جسمًا غريبًا قرب قدميك، أو وقع انفجار:
1. توقّف فورًا، وابقَ ثابتًا ولا تحرّك قدميك.
2. نادِ طلبًا للمساعدة، ونبّه الآخرين ألا يأتوا إليك.
3. انتظر وصول فريق مدرَّب، حتى لو طال الوقت.

لا تحاول أبدًا العودة على آثار قدميك، أو فحص الأرض بعصا، أو وضع علامات: فهذه ليست طرقًا آمنة للخروج. وإذا أُصيب أحد، فلا تركض نحوه: اطلب المساعدة وانتظر المنقذين المدرَّبين.`},{heading:"نصائح للفئات الأكثر عرضة للخطر",points:["المزارعون: إذا وجدتم جسمًا غريبًا أثناء الحراثة أو الحفر، فأوقفوا العمل، وأبعِدوا الجميع، وأبلِغوا عنه؛ ولا تزرعوا أرضًا معلَّمة أو أرضًا يتجنّبها الناس.","الرعاة: لا تُدخِلوا المواشي إلى المناطق المعلَّمة أو المشتبه بها، ولا تلحقوا أبدًا بحيوان دخلها.","عمّال البناء وحفر الآبار: إذا كشف الحفر عن جسم غريب، فتوقّفوا فورًا، وأبعِدوا الجميع، وأبلِغوا عنه.","العائلات العائدة بعد القتال: قبل استخدام منزل أو حقل أو طريق، اسألوا الجهات المختصة هل جرى فحصه.","جامعو الخردة: لا تجمعوا الخردة العسكرية أبدًا، ولا تقطعوها أو تفتحوها أو تبيعوها؛ فقد تنفجر وتعرّض حياتكم وحياة المشتري والجيران للخطر."]},{heading:"الحديث مع الأطفال",body:"الأطفال فضوليون، وبعض هذه الأجسام يشبه الألعاب. تحدّث معهم بهدوء وباستمرار دون أن تخيفهم، وامدحهم حين يخبرونك بشيء رأوه. علّمهم:",points:["ما لم يسقط منك، فلا تلتقطه.","لا تلمس جسمًا غريبًا أبدًا، ولا تركله ولا ترمِه بالحجارة، ولا تقترب منه.","ابتعد عن العلامات والأسيجة والأنقاض والمواقع العسكرية القديمة.","أخبر شخصًا كبيرًا فورًا.","إذا ظننت أنك في مكان خطر: توقّف، واثبت في مكانك، ونادِ طلبًا للمساعدة، وانتظر."]}],tips:["احفظ الرقم 115 في هاتفك وعلّمه لعائلتك.","اعرف المناطق الخطرة القريبة من منزلك وحقولك ومراعيك، واسأل الجهات المختصة إذا لم تكن متأكدًا.","عند الإبلاغ، اذكر المكان والمعالم القريبة، وهل يوجد أشخاص قرب الجسم.","لا تثق بالشائعات التي تقول إن منطقة ما قد طُهّرت؛ واسأل الجهات المختصة.","استخدم الطرق الرئيسية والممرات المطروقة، وخاصةً في المناطق التي شهدت قتالًا."],warnings:["لا تلمس الذخائر المتفجرة أو الخردة العسكرية أبدًا، ولا تحرّكها ولا تجمعها ولا تبعها، حتى لو بدت قديمة أو صدئة أو مستعملة.","في المنطقة الملغومة لا تعُد أبدًا على آثار قدميك، ولا تفحص الأرض، ولا تضع علامات: توقّف، واثبت في مكانك، واطلب المساعدة، وانتظر.","لا تركض نحو مصاب في منطقة ملغومة: اطلب المساعدة وانتظر المنقذين المدرَّبين."],media:[{kind:"image",src:"media/images/w7_uxo_keep_away.webp",title:"ابتعد وأبلِغ",description:"مزارع يُبعد عائلته مسافة كافية عن جسم مشبوه في حقل قبل أن يتصل بالرقم 115."}],activity:{prompt:"أثناء حراثة حقل، يرى مزارع جسمًا معدنيًّا صدئًا في التراب. ويريد ابنه أن يلتقطه ويبيعه خردةً. ماذا يجب أن يفعلا؟",options:[{text:"يوقفان العمل، ويُبعدان الجميع، ويتذكّران المكان، ثم يتصلان بالرقم 115 بعد أن يبتعدا مسافة كافية",correct:!0,feedback:"الذخائر القديمة أو الصدئة قد تنفجر مع ذلك. إيقاف العمل وإبعاد الجميع والإبلاغ من مكان آمن يحمي العائلة ويتيح للفرق المدرَّبة التعامل معه."},{text:"يرفعانه بحذر إلى الجرّار وينقلانه إلى مركز الدفاع المدني",correct:!1,feedback:"تحريكه أو نقله قد يؤدي إلى انفجاره في الطريق أو في المركز. اتركه في مكانه وأبلِغ عنه من مكان آمن."},{text:"يحرثان حوله ويواصلان العمل، لأنه قديم وصدئ",correct:!1,feedback:"القِدم والصدأ لا يجعلان الذخيرة آمنة، والحراثة بقربها قد تفجّرها. أوقِف العمل، وابتعد، وأبلِغ عنها."},{text:"يغطّيانه بالتراب ويضعان بجانبه حجرًا علامةً",correct:!1,feedback:"تغطيته أو تعليمه يعني البقاء بجانب الخطر. ابتعد، وتذكّر المكان، وأبلِغ الرقم 115."}]},quiz:[{question:"لا توجد علامات تحذيرية قرب حقل غطّته الأعشاب شهد قتالًا. هل دخوله آمن؟",options:[{text:"لا: فمعظم المناطق الخطرة غير معلَّمة، لذا ابقَ على الممرات المطروقة واسأل الجهات المختصة",correct:!0},{text:"نعم: فكل منطقة خطرة في الإقليم عليها علامات حمراء واضحة، لذا فالحقل الخالي منها آمن تمامًا",correct:!1},{text:"نعم، بعد حرق الأعشاب، لأن النار تدمّر كل الألغام المخبّأة في التراب تمامًا",correct:!1},{text:"نعم، إذا قال كبار السنّ في القرية إن الحقل طُهّر من الألغام منذ سنوات كثيرة",correct:!1}],explanation:"غياب العلامة لا يعني الأمان: فمعظم المناطق المتأثرة غير معلَّمة. والحرق لا يجعل المنطقة آمنة، والشائعات ليست فحصًا. استخدم الطرق الرئيسية والممرات المطروقة واسأل الجهات المختصة."},{question:"أدركت أنك ربما دخلت منطقة ملغومة. ما التصرّف الصحيح؟",options:[{text:"توقّف، ولا تحرّك قدميك، واطلب المساعدة، وانتظر فريقًا مدرَّبًا",correct:!0},{text:"عُد ببطء وحذر شديد على آثار قدميك نفسها إلى الطريق الذي جئت منه",correct:!1},{text:"اغرس عصا في الأرض أمامك لتجد طريقًا آمنًا للخروج من المنطقة",correct:!1},{text:"اركض بأقصى سرعة إلى أقرب طريق لتقضي وقتًا أقل في المنطقة",correct:!1}],explanation:"التوقّف والانتظار يمنعانك من أن تطأ لغمًا آخر. فآثار الأقدام يصعب رؤيتها والعودة عليها غير آمنة، وفحص الأرض عمل المختصين، ولا يمكنك أن تسبق الانفجار ركضًا."},{question:"يجمع جارك قذائف قديمة ويبيعها لتاجر خردة. ما النصيحة الأكثر أمانًا؟",options:[{text:"أن يتوقّف عن الجمع فورًا، ولا يحرّك الأجسام بنفسه، ويُبلغ عنها على الرقم 115",correct:!0},{text:"أن يواصل الجمع، لكن يأخذ فقط ما يبدو فارغًا أو قديمًا أو صدئًا ويترك الباقي في مكانه",correct:!1},{text:"أن يفتحها أولًا ليُخرج منها أي شيء خطر، ثم يبيع المعدن",correct:!1},{text:"أن يحفظها في غرفة باردة مغلقة في المنزل حتى يأتي التاجر لأخذها",correct:!1}],explanation:"قد تنفجر الخردة العسكرية في أي وقت، حتى لو بدت فارغة أو صدئة، فتعرّض الجامع والمشتري والجيران للخطر. لا تحرّكها: أبلِغ عنها لتتعامل معها الفرق المدرَّبة."},{question:"وجد أطفال جسمًا غريبًا ملوّنًا قرب المدرسة. ماذا يجب أن يعلّمهم الكبار؟",options:[{text:"ألا يلمسوه أو يقتربوا منه، وأن يُبعدوا أصدقاءهم ويخبروا شخصًا كبيرًا فورًا",correct:!0},{text:"أن يلتقطوه ببطء وحذر ويأخذوه إلى المعلّم ليفحصه ويعرف ما هذا الشيء",correct:!1},{text:"أن يرموه بحجارة صغيرة من بعيد ليعرفوا هل هو خطر",correct:!1},{text:"أن يلتقطوا له صورة واضحة عن قرب ويرسلوها إلى مجموعة العائلة على الهاتف",correct:!1}],explanation:"بعض المتفجرات تشبه الألعاب. لمسها أو حملها أو رميها بأي شيء أو الاقتراب منها لتصويرها قد يفجّرها؛ أما الابتعاد وإخبار شخص كبير فيُبقي الجميع في أمان."},{question:"أين يجب أن تكون عندما تتصل بالرقم 115 بشأن جسم مشبوه؟",options:[{text:"بعيدًا عنه في مكان آمن، بعد أن تنبّه الآخرين إلى الابتعاد",correct:!0},{text:"بجانبه تمامًا، لتتمكّن من وصف شكله وحجمه ولونه بدقة",correct:!1},{text:"قريبًا منه مع تشغيل كاميرا الهاتف، لترسل لهم صورة واضحة له",correct:!1},{text:"ممسكًا به بيدك، لتتمكّن من قراءة أي كتابة أو أرقام على جانبه",correct:!1}],explanation:"لا تقترب أبدًا لتنظر أو تصوّر. ولا ينبغي استخدام الهاتف أو اللاسلكي قرب الذخائر المتفجرة، لذا ابتعد مسافة كافية، ثم أبلِغ عن المكان والمعالم القريبة."}]},{id:21,icon:"CloudFog",accent:"#6d28d9",title:"تسرّب مادة خطرة قربك: الاحتماء في المكان أو الإخلاء",subtitle:"ادخل، وابقَ في الداخل، وتابع التعليمات",summary:"قد يؤدي حريق أو حادث في مصنع أو صهريج متضرّر إلى انطلاق غاز أو دخان أو غبار سامّ. وكثيرًا ما يكون أكثر الأماكن أمانًا هو داخل مبنى. يشرح هذا الدرس كيف تحتمي في المكان، ومتى تُخلي، وماذا تفعل إذا أصابت مادة ما جسمك.",blocks:[{heading:"ادخل، وابقَ في الداخل، وتابع التعليمات",body:"إذا أعلنت الجهات المختصة عن تسرّب مادة خطرة، أو رأيت سحابة أو دخانًا غريبًا، أو شممت رائحة كيميائية قوية، أو سمعت صوت إنذار (صفّارة) قربك:",points:["ادخل: ادخل فورًا أقرب مبنى متين، وأدخِل الأطفال والحيوانات الأليفة معك.","ابقَ في الداخل: ابقَ داخل المبنى حتى تعلن الجهات المختصة أن الخروج آمن، حتى لو أردت مساعدة الآخرين.","تابع التعليمات: تابع البيانات الرسمية عبر الراديو أو التلفاز أو الهاتف، ونفّذ ما تطلبه.","بعض الغازات الخطرة لا رائحة لها: اتّبع التعليمات حتى لو لم تلاحظ شيئًا."]},{heading:"كيف تحتمي في المكان",points:["أغلق جميع الأبواب والنوافذ الخارجية وأقفلها.","أطفئ أجهزة التكييف والمبرّدات والمراوح وأنظمة التهوية، وأغلق فتحات التهوية.","اذهب إلى غرفة داخلية قليلة النوافذ، فوق مستوى الأرض إن أمكن (لا في القبو)، وأغلق الأبواب الداخلية.","إن توفّر لديك، فسدّ الفتحات حول الأبواب والنوافذ وفتحات التهوية بشريط لاصق وأغطية بلاستيكية.","لا تأكل ولا تشرب شيئًا ربما تعرّض للمادة.","في السيارة: أغلق النوافذ وفتحات التهوية، وأطفئ المكيّف والمدفأة، وادخل أقرب مبنى."]},{heading:"متى تُخلي المكان",body:"أخلِ المكان عندما تطلب منك الجهات المختصة ذلك، أو عندما تصل المادة إلى داخل مبناك وتستطيع الخروج دون المرور عبرها.",points:["إذا طُلب منك الإخلاء، فغادر فورًا واتّبع التعليمات التي تُعطى لك.","اتجه إلى الجهة التي تهبّ منها الريح (upwind)، وإلى مكان مرتفع إن استطعت: فبعض الغازات أثقل من الهواء وتتجمّع في الأماكن المنخفضة.","لا تمرّ أبدًا عبر السحابة أو الدخان أو المادة المنسكبة.","إذا لم تستطع الوصول إلى هواء نقي دون المرور عبرها، فابقَ بعيدًا عنها قدر ما تستطيع واحتمِ في مكانك."]},{heading:"إذا أصابتك مادة: أبعِد نفسك، واخلع، وأزِل (Remove, Remove, Remove)",body:`1. أبعِد نفسك: ابتعد عن المادة وانتقل إلى هواء نقي.
2. اخلع الملابس الخارجية: اخلع الملابس التي لامستها المادة؛ وحاول ألا تسحبها فوق رأسك، ولا تنزع الملابس الملتصقة بالجلد، وضعها في كيس بلاستيكي مغلق.
3. أزِل المادة عن الجلد: جفّفها أو انفضها عن الجلد بمنديل ورقي أو قطعة قماش جافة؛ وإذا شعرت بحكّة أو حرقة في الجلد، فاشطفه بكمية كبيرة من الماء. وإذا دخلت المادة عينيك، فاغسلهما بماء نظيف.

لا تأكل ولا تشرب ولا تدخّن، ولا تلمس وجهك. أخبر فرق الاستجابة أنك تعرّضت للمادة، واتّبع تعليماتهم بشأن الفحص الطبي. وإذا كان أحد يتنفّس بصعوبة أو أُصيب إصابة بالغة، فاتصل بالرقمين 115 و122.`},{heading:"لا تذهب أبدًا لتشاهد",points:["لا تتجه نحو موقع الحادث لتشاهد أو تصوّر: فقد تصل إليك المادة دون إنذار.","لا تخرج لمساعدة الآخرين حتى تعلن الجهات المختصة أن الوضع آمن؛ واتصل بدلًا من ذلك بالرقمين 115 و122.","أبلِغ الرقم 115 من مكان آمن عن أي تسرّب أو سحابة غريبة أو انسكاب.","لا تنشر إلا البيانات الرسمية؛ فالشائعات تنشر الخوف والنصائح الخاطئة."]}],tips:["اختر غرفة الاحتماء الآن: غرفة داخلية قليلة النوافذ، فوق مستوى الأرض.","احتفظ في حقيبة الطوارئ بشريط لاصق ومقص وأغطية بلاستيكية وراديو يعمل بالبطاريات.","تعلّم كيف تطفئ المكيّف والمبرّدة وأنظمة التهوية بسرعة.","اتفق مع عائلتك على مكان الاحتماء وكيف تتواصلون فيما بينكم.","اتصل هاتفيًّا بالجيران الذين ربما لم يسمعوا البيان؛ ولا تخرج لإبلاغهم."],warnings:["لا تتجه أبدًا نحو السحابة أو الدخان أو المادة المنسكبة لتشاهد أو تصوّر!","لا تغادر مكان احتمائك حتى تعلن الجهات المختصة أن الوضع آمن، حتى لمساعدة الآخرين.","عند الإخلاء، لا تمرّ أبدًا سيرًا أو بالسيارة عبر السحابة أو المادة المنسكبة."],media:[{kind:"image",src:"media/images/w7_shelter_in_place.webp",title:"الاحتماء في المكان",description:"عائلة تحتمي في غرفة داخلية والأبواب والنوافذ مغلقة، وتتابع البيانات الرسمية."}],activity:{prompt:"يتصاعد من حريق في مستودع قريب دخان كثيف ذو رائحة غريبة باتجاه حيّك، ويطلب بيان رسمي من الناس البقاء داخل المنازل. أطفالك يلعبون في الفناء. ماذا تفعل؟",options:[{text:"أُدخل الأطفال، وأغلق الأبواب والنوافذ، وأطفئ المبرّدة والتهوية، وننتقل إلى غرفة داخلية، وأتابع البيانات",correct:!0,feedback:"هذا هو الاحتماء في المكان: في الداخل، ومع منع دخول الهواء الخارجي، تستنشق العائلة دخانًا أقل بكثير، والبيانات تخبرك متى يصبح الوضع آمنًا أو إن كان عليك المغادرة."},{text:"أقود السيارة بالعائلة نحو طريق المستودع لأرى حجم الحريق ثم أقرّر",correct:!1,feedback:"التوجّه نحو موقع الحادث يأخذك إلى داخل الدخان. ابقَ في الداخل وتابع البيانات الرسمية."},{text:"أفتح كل النوافذ وأشغّل المراوح ليمرّ الدخان عبر البيت بسرعة",correct:!1,feedback:"النوافذ المفتوحة والمراوح تُدخل الدخان إلى البيت. أغلق كل شيء، وأطفئ المراوح والمبرّدات والتهوية."},{text:"أمشي مع الأطفال عبر الدخان إلى بيت أحد الأقارب في حيّ آخر",correct:!1,feedback:"المشي عبر الدخان يعرّض العائلة كلها للمادة. لا تُخلِ إلا عندما يُطلب منك ذلك، ولا تمرّ أبدًا عبر السحابة."}]},quiz:[{question:"ماذا تعني «ادخل، وابقَ في الداخل، وتابع التعليمات»؟",options:[{text:"ادخل، وابقَ في الداخل حتى يُعلَن أن الوضع آمن، وتابع البيانات الرسمية",correct:!0},{text:"ادخل منطقة الحادث، وابقَ فيها لمساعدة المصابين، واتصل بأقاربك باستمرار لتعرف الأخبار",correct:!1},{text:"اصعد إلى السطح، وابقَ هناك لتراقب السحابة، وشغّل كل المراوح لتنقية الهواء",correct:!1},{text:"ادخل سيارتك، وابقَ فيها والمحرّك والمكيّف يعملان، واستمع إلى الموسيقى",correct:!1}],explanation:"في الداخل تستنشق كمية أقل بكثير من المادة. ابقَ في الداخل حتى تعلن الجهات المختصة أن الوضع آمن، وتابع البيانات الرسمية عبر الراديو أو التلفاز أو الهاتف."},{question:"أثناء احتمائك في المنزل، ماذا تفعل بالمكيّف أو المبرّدة؟",options:[{text:"أطفئه مع المراوح وأنظمة التهوية، وأغلق فتحات التهوية",correct:!0},{text:"شغّله بأقصى سرعة ليدفع الغاز إلى خارج البيت عبر النوافذ والأبواب",correct:!1},{text:"اتركه يعمل، لأن مرشّحه ينقّي الهواء الداخلي من المواد الكيميائية",correct:!1},{text:"شغّله فقط في الغرفة التي تحتمي فيها العائلة معًا",correct:!1}],explanation:"قد تسحب أجهزة التكييف والمبرّدات والمراوح والتهوية الهواء الخارجي ومعه المادة إلى داخل البيت. أطفئها وأغلق فتحات التهوية."},{question:"متى يجب أن تُخلي المكان أثناء تسرّب مادة خطرة؟",options:[{text:"عندما يُطلب منك ذلك، أو عندما تصل المادة إلى داخل مبناك وتستطيع الخروج بأمان",correct:!0},{text:"فور سماعك بالتسرّب، حتى لو كان طريق الخروج الوحيد من المنطقة يمرّ عبر السحابة نفسها",correct:!1},{text:"فقط بعد أن تخرج لترى بنفسك في أيّ اتجاه تتحرّك السحابة",correct:!1},{text:"متى غادر جيرانك، أيًّا كان ما تقوله البيانات الرسمية",correct:!1}],explanation:"كثيرًا ما يكون البقاء في الداخل أكثر أمانًا من الخروج. غادر عندما يُطلب منك ذلك، أو عندما تصل إليك المادة في الداخل وتستطيع الخروج دون المرور عبرها."},{question:"إذا اضطررت إلى الإخلاء، فأيّ اتجاه أكثر أمانًا؟",options:[{text:"نحو الجهة التي تهبّ منها الريح، وإلى مكان مرتفع إن أمكن، دون عبور السحابة",correct:!0},{text:"مع اتجاه الريح، لتساعدك الريح أنت وعائلتك على الابتعاد عن السحابة بسرعة كبيرة",correct:!1},{text:"نزولًا إلى وادٍ منخفض أو نفق قريب، حيث يكون الهواء عادةً هادئًا وساكنًا",correct:!1},{text:"نحو مصدر المادة، لأن النار هناك تحرق الغاز الخطر",correct:!1}],explanation:"في الجهة التي تهبّ منها الريح، تحمل الريح المادة بعيدًا عنك، وبعض الغازات أثقل من الهواء وتتجمّع في الأماكن المنخفضة. لا تمشِ أبدًا عبر السحابة."},{question:"تناثرت مادة كيميائية سائلة على ذراعك وكمّك. ماذا تفعل أولًا؟",options:[{text:"انتقل إلى هواء نقي، واخلع الملابس الخارجية الملوّثة، وجفّف السائل",correct:!0},{text:"امسحه بيدك العارية وتابع عملك، لأن الكمية الصغيرة منه لا تسبّب أي ضرر",correct:!1},{text:"غطِّه بالزيت أو معجون الأسنان لمنعه من التسرّب إلى الجلد",correct:!1},{text:"أبقِ الملابس عليك لتحمي جلدك حتى تصل إلى المستشفى لتلقّي العلاج",correct:!1}],explanation:"أبعِد نفسك، واخلع الملابس الخارجية، وأزِل المادة. فخلع الملابس الملوّثة يزيل معظم التلوّث؛ واشطف الجلد بكمية كبيرة من الماء إذا شعرت بحكّة أو حرقة، ولا تضع على الجلد أي علاجات منزلية."}]},{id:22,icon:"FlaskConical",accent:"#7e22ce",title:"التسمّم في المنزل",subtitle:"التخزين الآمن، وابتلاع السموم، وتناثر المواد الكيميائية، وأول أكسيد الكربون",summary:"توجد الأدوية ومواد التنظيف والنفط الأبيض (الكيروسين) والبنزين والمبيدات الحشرية في معظم المنازل، وكلٌّ منها قد يسبّب التسمّم. والأطفال الصغار أكثر عرضة للخطر، لأنهم يضعون الأشياء في أفواههم ولا يستطيعون قراءة الملصقات. يشرح هذا الدرس كيف نخزّن هذه المواد بأمان، وماذا نفعل إذا ابتلع شخص مادة ضارة، وكيف نغسل المواد الكيميائية عن العينين والجلد، وكيف نتصرّف عند الاشتباه في أول أكسيد الكربون (CO).",blocks:[{heading:"خزّن المواد الخطرة بأمان",body:"التخزين الصحيح هو أفضل وقاية:",points:["احفظ الأدوية ومواد التنظيف والمبيدات الحشرية في مكان مقفل أو مرتفع، بعيدًا عن أنظار الأطفال ومتناول أيديهم.","أبقِ كل مادة في عبوتها الأصلية مع ملصقها، حتى لا يظنّها أحد شرابًا.","لا تضع أبدًا النفط الأبيض أو البنزين أو المواد الكيميائية أو الأدوية في قناني المشروبات أو الأكواب أو أوعية الطعام.","أغلق العبوة بعد كل استعمال وأعدها إلى مكانها فورًا؛ ولا تتركها على الأرض أو على الطاولة ولو للحظة.","لا تخلط مواد التنظيف بعضها ببعض أبدًا (مثل المبيّض مع منظّف آخر): فقد يطلق الخليط أبخرة خطرة."]},{heading:"إذا ابتلع شخص مادة ضارة",body:`1. أبعد المادة عن المصاب وعن الأطفال.
2. اتصل بالرقم 122 فورًا حتى لو بدا المصاب بخير، فبعض السموم لا يظهر ضررها إلا لاحقًا. واحتفظ بالعبوة أو الملصق لتريهما لفريق الإسعاف والأطباء.
3. لا تحاول إحداث القيء.
4. لا تعطه حليبًا أو زيتًا أو ماءً مالحًا أو أي علاج منزلي آخر، ولا تعطه شيئًا يأكله أو يشربه إلا إذا طلب الطبيب ذلك.
5. إذا أصبح المصاب نعسانًا أو فاقدًا للوعي لكنه يتنفّس طبيعيًا، فضعه على جنبه (وضعية الإفاقة) وواصل مراقبة تنفّسه. وإذا توقف عن التنفّس الطبيعي فابدأ الإنعاش القلبي الرئوي (CPR) (انظر درس «الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)»).`},{heading:"النفط الأبيض والبنزين وزيت المصابيح",body:`هذه السوائل خطرة جدًا إذا ابتُلعت. فهي رقيقة وزلقة وتنزلق بسهولة إلى الرئتين ولو بكمية صغيرة، فتسبّب مشكلات تنفّسية خطيرة والتهابًا رئويًا. لذلك يكون إحداث القيء هنا خطرًا جدًا. والسعال أو الاختناق أو صعوبة التنفّس بعد ابتلاعها قد تعني أن السائل وصل إلى الرئتين: اتصل بالرقم 122 فورًا.

• اشترِ الوقود واحفظه في أوعية الوقود المخصّصة فقط، مقفلًا عليه بعيدًا عن الأطفال.`},{heading:"المواد الكيميائية في العين أو على الجلد",points:["احمِ نفسك أولًا: لا تلمس المادة الكيميائية بيدين عاريتين، والبس القفازات إن وُجدت.","العين: اغسلها فورًا بكمية وافرة من الماء النظيف الجاري مدة 15 دقيقة على الأقل، مع إبقاء الجفنين مفتوحين. ولا تدع الماء يسيل إلى العين الأخرى.","الجلد: أزل أي مسحوق جاف أولًا، وانزع الملابس الملوّثة والساعة والحليّ، ثم اغسل الجلد بكمية وافرة من الماء الجاري مدة 15 دقيقة على الأقل.","اتصل بالرقم 122 لطلب التوجيه واحتفظ بملصق المادة. واتصل فورًا إذا كان المصاب يعاني صعوبة في التنفّس، أو شعر بالمرض، أو أصابت المادة مساحة كبيرة من جسمه."]},{heading:"أول أكسيد الكربون (CO)",body:`أول أكسيد الكربون غاز سام بلا لون ولا رائحة، يصدر عن المدافئ والمواقد والمولّدات والمحرّكات التي تحرق الوقود. والصداع أو الدوار أو الغثيان أو الضعف أو الارتباك قرب هذه الأجهزة قد تكون علامات إنذار.

• أخرج الجميع إلى الهواء الطلق فورًا، واتصل بالرقمين 115 و122 من الخارج.
• لا تعد إلى الداخل حتى يُقال لك إن المكان آمن.
• لا تشغّل أبدًا مولّدًا أو محرّك سيارة داخل المنزل أو المرآب ولو كانت الأبواب مفتوحة، وركّب جهاز إنذار CO قرب غرف النوم.`}],tips:["اكتب الرقمين 122 (الإسعاف) و115 (الدفاع المدني) بجانب هاتفك، وعلّمهما لكل أفراد الأسرة.","تجوّل في منزلك على مستوى نظر طفل صغير، وأزل كل مادة سامة يمكن أن تصل إليها يده.","عندما تتصل بالرقم 122 بسبب تسمّم، أمسك العبوة بيدك لتقرأ اسم المادة.","اقرأ الملصق قبل استعمال أي مادة تنظيف، واتبع تعليماتها.","أبعد الأطفال في أثناء استعمال مواد التنظيف أو المبيدات أو الوقود."],warnings:["لا تحاول أبدًا إحداث القيء لمن ابتلع مادة سامة، ولا تعطه حليبًا أو زيتًا أو ماءً مالحًا.","لا تحفظ أبدًا النفط الأبيض أو البنزين أو المواد الكيميائية في قناني المشروبات: فقد يشربها طفل.","لا تدخل غرفة مليئة بالأبخرة أو يُشتبه فيها بأول أكسيد الكربون لإنقاذ أحد؛ اخرج واتصل بالرقم 115."],activity:{prompt:"ابن أخيك البالغ ثلاث سنوات يسعل ويبكي، وبجانبه قنينة مشروب مفتوحة كانت الأسرة تحفظ فيها النفط الأبيض للمدفأة. ماذا تفعل؟",options:[{text:"أبعد القنينة عنه، وأتصل بالرقم 122 فورًا، وأحتفظ بالقنينة لأريها لفريق الإسعاف. ولا أحاول إحداث القيء ولا أعطيه شيئًا يشربه.",correct:!0,feedback:"السعال بعد ابتلاع النفط الأبيض قد يعني أنه وصل إلى الرئتين. والاتصال السريع بالرقم 122، والاحتفاظ بالقنينة، وعدم إحداث القيء، كلها تحمي الطفل."},{text:"أُدخل إصبعي في حلقه ليتقيأ النفط الأبيض.",correct:!1,feedback:"القيء خطر جدًا مع النفط الأبيض، لأن السائل قد يدخل إلى الرئتين. اتصل بالرقم 122 بدلًا من ذلك."},{text:"أعطيه كوبًا من الحليب ليخفّف السم.",correct:!1,feedback:"الحليب لا يجعل النفط الأبيض غير ضار، وقد يدفعه إلى القيء. لا تعطه شيئًا بالفم إلا بأمر الطبيب؛ واتصل بالرقم 122."},{text:"أنتظر لأرى هل يتوقف السعال قبل أن أتصل بأحد.",correct:!1,feedback:"السعال علامة إنذار على أن النفط الأبيض ربما وصل إلى الرئتين، والانتظار يضيّع الوقت. اتصل بالرقم 122 الآن."}]},quiz:[{question:"أين يجب حفظ الأدوية ومواد التنظيف؟",options:[{text:"في مكان مقفل أو مرتفع، داخل عبواتها الأصلية",correct:!0},{text:"تحت حوض المطبخ، حيث يسهل على كل أفراد الأسرة الوصول إليها بسرعة",correct:!1},{text:"في قناني مشروبات نظيفة، حتى تشغل مساحة أصغر في المنزل",correct:!1},{text:"على رفّ منخفض في الحمّام، مع ترك أغطيتها غير محكمة",correct:!1}],explanation:"التخزين في مكان مقفل أو مرتفع وفي العبوة الأصلية ذات الملصق يُبعد الأطفال عن هذه المواد، ويمنع أي شخص من أن يظنّها شرابًا."},{question:"ابتلع شخص مادة تنظيف. أيّ تصرّف هو الصحيح؟",options:[{text:"الاتصال بالرقم 122، والاحتفاظ بالعبوة، وعدم إعطائه شيئًا بالفم",correct:!0},{text:"جعله يتقيأ فورًا حتى تخرج المادة من معدته بأسرع وقت ممكن قبل أن تضرّه",correct:!1},{text:"إعطاؤه كوبًا من الحليب أو الزيت لحماية المعدة من المادة",correct:!1},{text:"إعطاؤه ماءً مالحًا ثم الانتظار لمعرفة هل تتحسّن حالته",correct:!1}],explanation:"القيء والعلاجات المنزلية قد تزيد الضرر. اتصل بالرقم 122، واحتفظ بالعبوة، ولا تعطه شيئًا يأكله أو يشربه إلا إذا طلب الطبيب ذلك."},{question:"لماذا يكون ابتلاع النفط الأبيض أو البنزين خطرًا جدًا؟",options:[{text:"لأنه قد ينزلق إلى الرئتين ويسبّب مشكلات تنفّسية خطيرة",correct:!0},{text:"لأنه يضرّ المعدة فقط، فيصبح المصاب آمنًا تمامًا بعد أن يتقيأ",correct:!1},{text:"لأنه خطر فقط إذا شُرب كوب كامل منه، لا رشفة صغيرة",correct:!1},{text:"لأنه يصبح غير ضار بعد دقائق قليلة حين يمتزج بالماء",correct:!1}],explanation:"قد يدخل النفط الأبيض والبنزين إلى الرئتين ولو بكمية صغيرة، والقيء يزيد هذا الاحتمال. اتصل بالرقم 122 فورًا."},{question:"تناثرت مادة كيميائية في عين شخص. كم من الوقت يجب غسلها بالماء الجاري؟",options:[{text:"15 دقيقة على الأقل",correct:!0},{text:"نحو 30 ثانية",correct:!1},{text:"رشّة ماء واحدة سريعة تكفي",correct:!1},{text:"فقط إلى أن يزول اللسع",correct:!1}],explanation:"اغسل العين فورًا بكمية وافرة من الماء الجاري مدة 15 دقيقة على الأقل مع إبقاء الجفنين مفتوحين، ثم اتصل بالرقم 122 لطلب التوجيه."},{question:"في أثناء تشغيل مدفأة داخل المنزل، أصيب عدد من أفراد الأسرة بالصداع والدوار. ماذا تفعل أولًا؟",options:[{text:"أُخرج الجميع، ثم أتصل بالرقمين 115 و122 من الخارج",correct:!0},{text:"أعطي الجميع مسكّنًا للألم وأتركهم يرتاحون في الغرفة الدافئة نفسها",correct:!1},{text:"أفتح نافذة قليلًا وأترك المدفأة تعمل طوال الليل",correct:!1},{text:"أرفع حرارة المدفأة لتدفأ الغرفة بسرعة ويزول الدوار",correct:!1}],explanation:"قد تكون هذه علامات تسمّم بأول أكسيد الكربون، وهو غاز بلا لون ولا رائحة: أخرج الجميع أولًا، واتصل من الخارج، ولا تعد إلى الداخل حتى يُقال لك إن المكان آمن."}],media:[{kind:"image",src:"media/images/w7_poisoning_home.webp",title:"التخزين الآمن في المنزل",description:"الأدوية ومواد التنظيف في عبواتها الأصلية، في مكان مقفل بعيدًا عن متناول الأطفال"}]},{id:23,icon:"Ambulance",accent:"#be123c",title:"الطوارئ الطبية: تعرّف واتصل",subtitle:"السكتة الدماغية، والنوبة القلبية، ونوبة التشنج، وانخفاض السكر، والحساسية الشديدة، والصدمة، وفقدان الوعي",summary:"في المرض المفاجئ، أهم ما يمكن أن يفعله المواطن هو أن يتعرّف على علامات الخطر، ويتصل بالرقم 122 فورًا، ويبقى مع المريض. يعلّم هذا الدرس علامات السكتة الدماغية (FAST)، والنوبة القلبية، ونوبة التشنج، وانخفاض سكر الدم، والحساسية الشديدة، والصدمة، وما يجب فعله لشخص فاقد للوعي، وما تقوله عند الاتصال بالرقم 122. ولا يغني هذا الدرس عن دورة في الإسعافات الأولية.",blocks:[{heading:"السكتة الدماغية: تذكّر FAST",body:`تحدث السكتة الدماغية عندما يتوقف وصول الدم الكافي إلى جزء من الدماغ فجأة. والعلاج أنجع كلما بدأ مبكرًا، لذلك تصرّف فورًا:
• F = الوجه (Face): اطلب منه أن يبتسم. هل يتدلّى أحد جانبي وجهه؟
• A = الذراعان (Arms): اطلب منه أن يرفع ذراعيه. هل تهبط إحداهما أو تبدو ضعيفة؟
• S = الكلام (Speech): هل كلامه متلعثم أو غريب، أو لا يفهم ما تقول؟
• T = الوقت (Time): إذا رأيت أيًّا من هذه العلامات، فاتصل بالرقم 122 فورًا.

سجّل وقت بدء العلامات، أو آخر وقت شوهد فيه المريض بحالة طبيعية، وأخبر به فريق الإسعاف. واتصل حتى لو زالت العلامات. ولا تعطه طعامًا أو شرابًا، لأن السكتة قد تجعل البلع صعبًا.`},{heading:"النوبة القلبية",body:`قد تشمل علامات الخطر: ألمًا أو ضغطًا أو عصرًا في الصدر؛ وألمًا يمتد إلى الذراع أو الرقبة أو الفك أو الظهر؛ وضيقًا في التنفّس؛ وتعرّقًا؛ وغثيانًا.
• اتصل بالرقم 122 فورًا. ودع سيارة الإسعاف تنقله إلى المستشفى، ولا تدعه يقود بنفسه.
• أوقف أي نشاط: ساعده على الجلوس أو الراحة في الوضعية الأكثر راحة له، وابقَ معه.
• إذا فقد الاستجابة وتوقف عن التنفّس الطبيعي، فابدأ الإنعاش القلبي الرئوي (CPR) وأرسل من يُحضر جهاز إزالة الرجفان الخارجي الآلي (AED).`},{heading:"نوبة التشنج (الصرع)",body:`في أثناء نوبة التشنج قد يسقط المريض، ويتصلّب جسمه ويرتعش، أو يحدّق دون أن يستجيب. ومعظم النوبات تتوقف من تلقاء نفسها خلال دقائق قليلة.
• ابقَ معه وسجّل وقت بدء النوبة.
• أبعد الأشياء الصلبة أو الحادة، وضع شيئًا لينًا ومسطّحًا، مثل سترة مطوية، تحت رأسه.
• لا تقيّد حركته ولا تضع أي شيء في فمه، ولا تعطه طعامًا أو شرابًا أو دواءً حتى يستعيد وعيه تمامًا.
• عندما تتوقف الارتعاشات، ضعه على جنبه (وضعية الإفاقة) إذا لم يُشتبه في إصابة الرقبة أو الظهر، وتحقق من تنفّسه.

اتصل بالرقم 122 إذا:`,points:["كانت هذه أول نوبة تشنج للشخص.","استمرت النوبة أكثر من 5 دقائق، أو بدأت نوبة أخرى قبل أن يستعيد الشخص وعيه.","حدثت النوبة في الماء، أو أصيب الشخص أو واجه صعوبة في التنفّس.","كانت المريضة حاملًا، أو كان المريض رضيعًا عمره أقل من 6 أشهر.","لم يستعد الشخص وعيه جيدًا خلال 5–10 دقائق بعد توقف النوبة."]},{heading:"انخفاض السكر والحساسية الشديدة والصدمة",points:["انخفاض سكر الدم (غالبًا لدى مريض السكّري): ارتباك مفاجئ، أو ارتجاف، أو تعرّق، أو سلوك غريب. إذا كان المريض واعيًا ويستطيع البلع، فأعطه سكّرًا أو حلوى أو شرابًا محلّى. واتصل بالرقم 122 إذا لم يستطع البلع، أو أصيب بنوبة تشنج، أو لم يتحسّن خلال 10 دقائق.","الحساسية الشديدة (التأق، Anaphylaxis): تورّم الشفتين أو الوجه أو الحلق، وصعوبة التنفّس، والأزيز، والطفح الجلدي، والدوار أو الإغماء، وغالبًا بعد دقائق من تناول طعام أو دواء أو من لسعة حشرة. اتصل بالرقم 122 فورًا. وإذا كان معه حاقن الأدرينالين الذاتي (auto-injector) الخاص به، فساعده على استعماله وفق تعليماته.","في الحساسية الشديدة، دع المريض يجلس إذا كان التنفّس صعبًا، وإلا فدعه يستلقي. ولا تدعه يقف أو يمشي حتى لو شعر بتحسّن.","الصدمة (بعد نزيف شديد أو حروق أو مرض شديد): جلد شاحب بارد ورطب، وسرعة ضربات القلب، ودوار أو ارتباك. اتصل بالرقم 122، ومدّد المصاب على ظهره، وحافظ على دفئه، ولا تعطه شيئًا يأكله أو يشربه. وإذا تقيّأ أو أصبح نعسانًا، فضعه على جنبه ما لم يُشتبه في إصابة الرقبة أو الظهر."]},{heading:"فاقد الوعي: هل يتنفّس طبيعيًا؟",body:"اربت على كتفيه واسأله بصوت عالٍ: «هل أنت بخير؟» فإن لم يستجب، فاتصل بالرقم 122 (أو اطلب من شخص آخر الاتصال)، وانظر إلى صدره مدة لا تزيد على 10 ثوانٍ.",points:["يتنفّس طبيعيًا، ولم يسقط ولم يتعرّض لحادث أو ضربة على الرأس أو الرقبة أو الظهر: ضعه على جنبه في وضعية الإفاقة، ولا تعطه شيئًا بالفم، وواصل التحقق من تنفّسه.","يتنفّس طبيعيًا، لكن قد تكون رقبته أو ظهره أو وركه أو حوضه مصابًا: لا تحرّكه إلا إذا كان المكان خطرًا، وأبقِه ثابتًا وواصل مراقبة تنفّسه.","لا يتنفّس، أو يشهق شهقات متقطعة فقط: ابدأ الإنعاش القلبي الرئوي (CPR) فورًا، وأرسل من يُحضر جهاز AED (انظر درس «الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)»)."]},{heading:"الاتصال بالرقم 122: ماذا تقول؟",body:`حافظ على هدوئك وأجب عن أسئلة موظف الطوارئ:
1. أين أنت: المنطقة، والشارع، ومعلم قريب، والمبنى، والطابق.
2. ماذا حدث وماذا ترى، مثلًا: «رجل في نحو الستين من عمره؛ أحد جانبي وجهه متدلٍّ.»
3. كم عدد المرضى أو المصابين، وهل يوجد أي خطر.
4. اسمك ورقم هاتفك.

لا تُنهِ المكالمة حتى يُطلب منك ذلك. وابقَ مع المريض، وجهّز أدويته وأوراقه الطبية لفريق الإسعاف.`}],tips:["تعلّم FAST وعلّمه لأسرتك: الوجه، والذراعان، والكلام، والوقت.","التحق بدورة في الإسعافات الأولية والإنعاش القلبي الرئوي، وجدّدها كل بضع سنوات.","إذا كان أحد أفراد أسرتك مصابًا بالسكّري أو الصرع أو مرض في القلب أو حساسية شديدة، فاعرف خطته للطوارئ ومكان أدويته وأجهزته.","احتفظ بقائمة مكتوبة بأمراض كل فرد من الأسرة وأدويته وأنواع الحساسية لديه، وسلّمها لفريق الإسعاف.","ابقَ مع المريض حتى يتسلّم فريق الإسعاف المهمة."],warnings:["لا تضع أبدًا أي شيء في فم شخص في نوبة تشنج أو غير واعٍ تمامًا.","لا تعطِ أدوية من تلقاء نفسك؛ ساعد الشخص فقط على استعمال حاقن الأدرينالين الذاتي أو البخّاخ (inhaler) الموصوف له.","لا تنتظر لترى هل تزول علامات السكتة الدماغية أو النوبة القلبية: اتصل بالرقم 122 فورًا."],activity:{prompt:"في اجتماع عائلي، أصبح عمّك البالغ 62 عامًا فجأة عاجزًا عن رفع ذراعه اليمنى، وصار كلامه متلعثمًا. يقول إنه يحتاج فقط إلى أن يستلقي قليلًا. ماذا تفعل؟",options:[{text:"أتصل بالرقم 122 فورًا، وأخبرهم بما أراه وبوقت بدء العلامات، وأبقى معه حتى تصل سيارة الإسعاف.",correct:!0,feedback:"ضعف الذراع وتلعثم الكلام من علامات السكتة الدماغية (FAST). والعلاج أنجع كلما بدأ مبكرًا، ووقت بدء العلامات يساعد الأطباء."},{text:"أتركه يستلقي ويرتاح، ونتصل بطبيب غدًا إذا لم يتحسّن.",correct:!1,feedback:"الانتظار يضيّع الوقت: السكتة الدماغية تحتاج إلى علاج في أبكر وقت ممكن. اتصل بالرقم 122 الآن حتى لو شعر بتحسّن."},{text:"آخذه بالسيارة إلى صيدلية ليشتري دواءً لضغط الدم.",correct:!1,feedback:"الصيدلية لا تعالج السكتة الدماغية، والأدوية من دون طبيب قد تضرّه. اتصل بالرقم 122 لتنقله سيارة الإسعاف إلى المستشفى."},{text:"أعطيه شايًا محلّى وأنتظر نصف ساعة لأرى هل يتحسّن كلامه.",correct:!1,feedback:"الشاي المحلّى لا يعالج السكتة الدماغية، والانتظار يضيّع وقتًا ثمينًا. اتصل بالرقم 122 فورًا."}]},quiz:[{question:"ماذا يعني الحرف T في FAST؟",options:[{text:"الوقت (Time): اتصل بالرقم 122 فورًا وسجّل وقت بدء العلامات",correct:!0},{text:"الحرارة (Temperature): قِس حرارته أولًا بميزان الحرارة لتعرف هل لديه حمّى",correct:!1},{text:"الأقراص (Tablets): أعطِ المريض دواءه المعتاد أولًا",correct:!1},{text:"الشاي (Tea): أعطِ المريض مشروبًا دافئًا ليهدأ",correct:!1}],explanation:"تعني FAST: الوجه، والذراعين، والكلام، والوقت. والوقت يعني الاتصال بالرقم 122 فورًا، ووقت بدء العلامات يساعد الأطباء على اختيار العلاج."},{question:"شخص في نوبة تشنج على الأرض. ما التصرّف الصحيح؟",options:[{text:"أبعد الأشياء الصلبة، وسجّل المدة، ولا تضع شيئًا في فمه",correct:!0},{text:"أمسك ذراعيه وساقيه بقوة حتى تتوقف الارتعاشات أسرع",correct:!1},{text:"ضع ملعقة بين أسنانه حتى لا يعضّ لسانه في أثناء النوبة",correct:!1},{text:"اسكب ماءً باردًا على وجهه ليستيقظ وتتوقف النوبة",correct:!1}],explanation:"لا تقيّد حركة المريض ولا تضع أي شيء في فمه. احمه من الإصابة، وسجّل مدة النوبة، وضعه على جنبه عندما تتوقف الارتعاشات."},{question:"متى يجب الاتصال بالرقم 122 بسبب نوبة تشنج؟",options:[{text:"إذا استمرت أكثر من 5 دقائق أو كانت أول نوبة للشخص",correct:!0},{text:"فقط إذا طلب الشخص ذلك بعد انتهاء النوبة",correct:!1},{text:"أبدًا، لأن النوبات تتوقف دائمًا وحدها دون مساعدة",correct:!1},{text:"فقط إذا استمرت النوبة أكثر من نصف ساعة كاملة دون توقف",correct:!1}],explanation:"اتصل بالرقم 122 في النوبة الأولى، أو النوبة التي تزيد على 5 دقائق، أو النوبات المتكررة، أو النوبة في الماء، أو عند الإصابة، أو صعوبة التنفّس، أو الحمل، أو إذا كان المريض رضيعًا دون 6 أشهر، أو إذا لم يستعد الشخص وعيه جيدًا."},{question:"مريض سكّري مرتبك ويتعرّق، لكنه واعٍ ويستطيع البلع. ما الذي يساعده؟",options:[{text:"أعطه سكّرًا أو شرابًا محلّى، واتصل بالرقم 122 إذا لم يتحسّن",correct:!0},{text:"أعطه جرعة إضافية من الإنسولين الخاص به ليعود سكّر دمه إلى طبيعته بسرعة",correct:!1},{text:"دعه ينام في غرفة هادئة دون أن يأكل أي شيء",correct:!1},{text:"اسكب شرابًا محلّى في فمه حتى لو أصبح نعسانًا",correct:!1}],explanation:"يُعالَج انخفاض سكر الدم بالسكّر عن طريق الفم فقط إذا كان المريض واعيًا ويستطيع البلع. واتصل بالرقم 122 إذا لم يستطع البلع، أو أصيب بنوبة تشنج، أو لم يتحسّن خلال 10 دقائق."},{question:"شخص فاقد للوعي يتنفّس طبيعيًا، ولا توجد علامة على سقوط أو ضربة على الرقبة أو الظهر. ماذا تفعل؟",options:[{text:"أتصل بالرقم 122، وأضعه على جنبه، وأراقب تنفّسه",correct:!0},{text:"أُجلسه وأعطيه ماءً ليستعيد وعيه ويستيقظ بسرعة أكبر",correct:!1},{text:"أبدأ الضغطات الصدرية فورًا مع أنه ما زال يتنفّس",correct:!1},{text:"أتركه وحده على ظهره وأذهب للبحث عن أسرته",correct:!1}],explanation:"تُبقي وضعية الإفاقة مجرى الهواء مفتوحًا لدى فاقد الوعي الذي يتنفّس طبيعيًا ولا يُشتبه في إصابة رقبته أو ظهره أو وركه أو حوضه. لا تعطه شيئًا بالفم، وإذا توقف التنفّس فابدأ الإنعاش القلبي الرئوي (CPR)."}],media:[{kind:"image",src:"media/images/w7_medical_emergencies.webp",title:"علامات السكتة الدماغية: FAST",description:"الوجه، والذراعان، والكلام، والوقت: تعرّف على العلامات واتصل بالرقم 122"}]},{id:24,icon:"Handshake",accent:"#0369a1",title:"إخلاء الأشخاص الذين يحتاجون إلى مساعدة",subtitle:"الأطفال، وكبار السن، والأشخاص ذوو الإعاقة، والنساء الحوامل، والمرضى",summary:"في الحريق أو الزلزال أو الفيضان، لا يستطيع بعض الناس الخروج بسرعة أو وحدهم: الأطفال الصغار، وكبار السن، والأشخاص ذوو الإعاقة، والنساء الحوامل، والمرضى. وتعتمد سلامتهم على خطة توضع قبل وقوع الطارئ. يشرح هذا الدرس كيف تُعدّ خطة إخلاء شخصية، وكيف تتواصل مع الصمّ والمكفوفين، ولماذا لا يُستعمل المصعد العادي في الحريق، وكيف تساعد دون أن تعرّض نفسك أو الشخص للخطر.",blocks:[{heading:"من قد يحتاج إلى مساعدة؟",body:"فكّر في كل من في منزلك ومبناك وشارعك ممن قد لا يستطيعون الخروج بسرعة أو وحدهم:",points:["الرضّع والأطفال الصغار، الذين يجب أن يوقظهم شخص بالغ ويُخرجهم.","كبار السن الذين يمشون ببطء، أو يستعملون المشّاية، أو لا يسمعون جرس الإنذار جيدًا.","مستخدمو الكرسي المتحرك أو العكازات أو العصا، والأشخاص ذوو الإعاقة البصرية أو السمعية أو الذهنية أو النفسية.","النساء الحوامل، والمرضى أو المتعافون من عملية جراحية، وكل من يعتمد على أدوية أو أجهزة طبية."]},{heading:"خطة الإخلاء الشخصية",body:"ضع الخطة قبل وقوع الطارئ، بالاشتراك مع الشخص نفسه:",points:["الشخص نفسه أعرف الناس بقدراته واحتياجاته: اسأله، وخطّط مع أسرته ومسؤول المبنى.","اختر لكل شخص مساعدًا (مرافقًا، buddy) ومساعدًا بديلًا، وتأكّد من أن كليهما يقبل هذه المهمة.","دوّن احتياجات الشخص: الأدوية، والأجهزة الطبية، ووسائل التنقل، وطريقة تواصله، ومن يجب الاتصال به.","في الليل، أبقِ النظارات وأجهزة السمع ووسيلة المشي والهاتف ومصباحًا يدويًا بجانب السرير.","إن أمكن، لينم الشخص في الطابق الأرضي قريبًا من مخرج.","تدرّبوا على الخطة معًا بانتظام."]},{heading:"التواصل مع الصمّ والمكفوفين",points:["الأصمّ أو ضعيف السمع: قد لا يسمع جرس الإنذار أو الصراخ. اذهب إليه مباشرة ولفت انتباهه بالتلويح أو بضوء وامض، ثم قف قبالته وتكلّم بوضوح من دون صراخ.","اشرح بإشارات بسيطة، وأشر إلى المخرج، أو اكتب ملاحظة قصيرة. وفي الظلام، سلّط ضوءًا على وجهك ويديك ليتمكّن من رؤيتك.","الكفيف أو ضعيف البصر: عرّفه بنفسك وبما يحدث، واسأله كيف يمكنك مساعدته. ولا تمسكه بقوة ولا تدفعه.","قدّم له ذراعك ودعه يمسكها فوق المرفق مباشرة. وتوقّف قليلًا قبل الدرج وحافة الرصيف والأبواب، وأخبره بما أمامه.","عند نقطة التجمع، أخبره أين هو ومن معه."]},{heading:"المصاعد ومناطق اللجوء",points:["لا تستعمل أبدًا المصعد العادي في الحريق. فعندما يدوّي إنذار الحريق، تتجه المصاعد عادةً إلى طابق محدد، ثم لا يشغّلها إلا رجال الإطفاء.","الشخص الذي لا يستطيع استعمال الدرج ينتظر مع مساعده في المكان الآمن المحدد في خطة الطوارئ الخاصة بالمبنى، مثل منطقة اللجوء (Area of Refuge)، بعيدًا عن النار والدخان.","إذا لم تستطع الوصول إلى شخص يحتاج إلى مساعدة، فاخرج واتصل بالرقم 115. وأخبر رجال الإطفاء فورًا أين ينتظر هذا الشخص: الطابق، والغرفة، وعدد الأشخاص.","اتفق على هذه الترتيبات مسبقًا مع مسؤول المبنى، واتبع تعليمات الدفاع المدني."]},{heading:"المساعدة من دون خطر",points:["اسأل قبل أن تساعد، واتبع تعليمات الشخص نفسه حول طريقة مساعدته.","لا ترفع شخصًا ولا تحمله إن لم تكن مدرّبًا، إلا إذا كان هناك خطر مباشر على الحياة: فقد تؤذيه وتؤذي نفسك.","لا تُبعد الكرسي المتحرك أو المشّاية أو العصا عن الشخص؛ وخذ وسيلة التنقل معك إن استطعت.","خذ أدويته وأجهزته فقط إذا كانت في متناول اليد؛ ولا تعد إلى الداخل لأجلها أبدًا.","عند نقطة التجمع، ابقَ مع الشخص، وأخبر من يعدّ الحاضرين بأنه بأمان."]}],tips:["أعدّ قائمة بالجيران في مبناك ممن قد يحتاجون إلى مساعدة، واتفقوا على من يساعد من.","احتفظ بنسخة من قائمة احتياجات كل شخص في حقيبة الطوارئ.","أجهزة إنذار الدخان المزوّدة بضوء وامض أو وسادة هزّازة تساعد الصمّ وضعاف السمع.","إذا كان أحدهم يستعمل مشّاية أو كرسيًا متحركًا، فتأكّد من أنه يستطيع المرور من كل أبواب الخروج في منزلك.","أشرِك الشخص الذي يحتاج إلى مساعدة في تدريباتكم، حتى تناسبه الخطة فعلًا."],warnings:["لا تستعمل أبدًا المصعد العادي في أثناء الحريق.","لا تعد أبدًا إلى مبنى يحترق لإنقاذ أحد: أخبر رجال الإطفاء بدقة أين يوجد الشخص."],activity:{prompt:"يدوّي إنذار الحريق في مبنى الشقق الذي تسكنه. جارتك في الطابق الرابع امرأة مسنّة تستعمل المشّاية ولا تستطيع نزول الدرج بسرعة. ماذا تفعل؟",options:[{text:"أخبرها بما يحدث، وأساعدها على نزول الدرج بالسرعة التي تناسبها أو على الوصول إلى مكان الانتظار الآمن المتفق عليه، وأخبر رجال الإطفاء بدقة أين هي.",correct:!0,feedback:"مساعدتها على اتباع الخطة وإخبار رجال الإطفاء بمكانها الدقيق يوصلان المنقذين المدرّبين إليها بسرعة، من دون تعريض أيٍّ منكما لخطر إضافي."},{text:"أُنزلها بالمصعد لأنه أسرع من الدرج.",correct:!1,feedback:"لا يجوز استعمال المصعد العادي في الحريق: فهو يتجه إلى طابق محدد ثم يتحكّم فيه رجال الإطفاء. استعمل الدرج أو مكان الانتظار المتفق عليه."},{text:"أخرج من دونها، لأن إنقاذ الناس مهمة رجال الإطفاء وحدهم.",correct:!1,feedback:"تركها دون إخبار أحد يؤخّر إنقاذها. نبّهها، وساعدها كما تنص خطتك، وأخبر رجال الإطفاء بمكانها."},{text:"أحملها على ظهري وحدي وأنزل الدرج مسرعًا.",correct:!1,feedback:"حملها من دون تدريب قد يؤذيكما معًا، والسقوط على الدرج يسدّ الطريق على الآخرين. لا تحمل شخصًا إلا إذا كنت مدرّبًا أو كان هناك خطر مباشر على الحياة."}]},quiz:[{question:"من يجب أن يضع خطة الإخلاء الشخصية لشخص ما؟",options:[{text:"الشخص نفسه، بالاشتراك مع أسرته ومساعديه ومسؤول المبنى",correct:!0},{text:"مسؤول المبنى وحده، من دون سؤال الشخص عن احتياجاته",correct:!1},{text:"رجال الإطفاء وحدهم، في اليوم الذي يقع فيه الطارئ فعلًا",correct:!1},{text:"لا أحد: من الأفضل أن نقرّر ماذا نفعل عندما يدوّي الإنذار",correct:!1}],explanation:"الشخص نفسه أعرف الناس باحتياجاته، لذلك توضع الخطة معه ومع أسرته ومساعديه ومسؤول المبنى، ويُتدرّب عليها قبل وقوع الطارئ."},{question:"يدوّي إنذار الحريق. كيف تلفت انتباه جار أصمّ؟",options:[{text:"أذهب إليه، وألوّح أو أستعمل ضوءًا، وأقف قبالته",correct:!0},{text:"أصرخ بصوت عالٍ من آخر الممر مرة بعد مرة حتى يسمعني",correct:!1},{text:"أمسك ذراعه من الخلف وأسحبه بسرعة نحو المخرج",correct:!1},{text:"أرسل رسالة إلى هاتفه وأتابع طريقي نحو المخرج وحدي",correct:!1}],explanation:"قد لا يسمع الأصمّ جرس الإنذار أو الصراخ. اذهب إليه مباشرة، ولفت انتباهه، وقف قبالته، واشرح بالإشارات أو بملاحظة مكتوبة."},{question:"كيف ترشد شخصًا كفيفًا إلى خارج المبنى؟",options:[{text:"أعرّفه بنفسي، وأقدّم له ذراعي، وأصف له الدرج والعوائق",correct:!0},{text:"أمسك كتفيه كليهما بقوة وأدفعه من الخلف نحو باب الخروج بسرعة",correct:!1},{text:"أمسك يده وأسحبه بسرعة خلفي من دون أن أقول شيئًا",correct:!1},{text:"أشير إلى المخرج وأطلب منه أن يجد طريقه وحده",correct:!1}],explanation:"عرّفه بنفسك واسأله كيف تساعده. دعه يمسك ذراعك فوق المرفق مباشرة، وأخبره بما أمامه، مثل الدرج وحافة الرصيف والأبواب."},{question:"لماذا لا يجوز استعمال المصعد العادي في الحريق؟",options:[{text:"لأنه يتجه إلى طابق محدد ثم يتحكّم فيه رجال الإطفاء",correct:!0},{text:"لا مانع من استعماله ما دام الحريق في طابق آخر",correct:!1},{text:"لأنه آمن لمستخدمي الكراسي المتحركة فقط دون غيرهم",correct:!1},{text:"يجوز استعماله إذا أبقى أحدهم أبوابه مفتوحة بكرسي حتى يصل الجميع",correct:!1}],explanation:"لا يُستعمل المصعد العادي في الطوارئ ما لم يكن مصمّمًا لذلك خصيصًا. فعندما يدوّي إنذار الحريق يتجه عادةً إلى طابق محدد، ولا يشغّله إلا رجال الإطفاء. والشخص الذي لا يستطيع استعمال الدرج ينتظر في المكان المتفق عليه، ويُبلَّغ رجال الإطفاء بمكانه."},{question:"لست مدرّبًا على حمل الأشخاص، ولا يوجد خطر مباشر. رجل على كرسي متحرك لا يستطيع استعمال الدرج. ما الأفضل؟",options:[{text:"أساعده إلى المكان المتفق عليه وأُبلغ رجال الإطفاء بمكانه",correct:!0},{text:"أرفعه من الكرسي وأحمله وحدي نزولًا على الدرج بأسرع ما أستطيع",correct:!1},{text:"أتركه في الممر وأخرج دون أن أخبر أحدًا بمكانه",correct:!1},{text:"أُنزله بالمصعد لأن الدرج ضيّق جدًا على الكرسي المتحرك",correct:!1}],explanation:"الحمل من دون تدريب قد يؤذيكما معًا. وما لم يكن هناك خطر مباشر، ساعده على الوصول إلى المكان الآمن المتفق عليه، وتأكّد من أن رجال الإطفاء يعرفون مكانه بدقة."}],media:[{kind:"image",src:"media/images/w7_assisted_evacuation.webp",title:"مساعدة جار على الإخلاء",description:"مساعد يرشد رجلًا كفيفًا من ذراعه، ومستخدم كرسي متحرك ينتظر مع مرافقه في منطقة اللجوء"}]},{id:25,icon:"TrafficCone",accent:"#ea580c",title:"في موقع حادث سير أو حريق مركبة",subtitle:"احمِ نفسك أولًا، ثم اتصل وساعد بأمان",summary:"معظم حوادث السير لا تنتهي بحريق، لكن موقع الحادث يبقى خطرًا: فحركة السير والوقود المتسرّب والدخان قد تؤذي من يتوقف للمساعدة. يبيّن هذا الدرس كيف تحمي نفسك أولًا، وكيف تتصل بالرقمين 115 و122 وتحدّد موقعًا تستطيع الفرق الوصول إليه، وكيف تساعد المصابين دون أن تزيد إصاباتهم سوءًا، وماذا تفعل إذا اشتعلت النار في مركبة.",blocks:[{heading:"احمِ نفسك أولًا",points:["لا تتوقف إلا في مكان آمن، خارج الطريق إن استطعت، ولا تسدّ الطريق أمام سيارات الإسعاف والإطفاء.","شغّل أضواء التحذير (الفلاشر)، وأطفئ محرّك سيارتك، واطلب من السائقين الآخرين إطفاء محركاتهم.","لا يدخّن أحد ولا يُشعل لهبًا قرب المركبات: فالوقود ومعظم سوائل المركبة الأخرى تشتعل بسهولة.","البس سترة عاكسة عالية الوضوح إن كانت معك، ولا تقف أبدًا بين المركبات المتضررة والسيارات القادمة.","إن كان معك مثلث تحذيري فلا تضعه إلا حيث تستطيع ذلك دون أن تدخل في حركة السير، أما القواعد المحلية لاستعماله ومسافة وضعه فتحددها جهات المرور.","أبعِد غير المصابين، ولا سيما الأطفال، عن المركبات والطريق إلى مكان أكثر أمانًا."]},{heading:"اتصل بالرقمين 115 و122",points:["اتصل فورًا: فبعد الحادث قد تصنع الدقائق الفرق بين الحياة والموت. اتصل بالرقم 115 للحريق أو المحاصَرين أو الوقود المتسرّب، وبالرقم 122 للمصابين، وبالرقمين معًا عند الحاجة إليهما.","أين: اسم الطريق أو اسم المدينتين اللتين يصل بينهما، واتجاه سيرك، ومَعلم قريب مثل جسر أو محطة وقود أو تقاطع أو لافتة طريق.","إن لم تكن متأكدًا من مكانك فاقرأ أقرب لافتات الطريق، أو استعن بالموقع الذي تُظهره خريطة هاتفك.","ماذا حدث: عدد المركبات، وعدد المصابين أو المحاصَرين، وأي خطر مثل الحريق أو الدخان أو الوقود المتسرّب أو شاحنة تحمل لوحات خطر.","اذكر اسمك ورقم هاتفك، ولا تُنهِ المكالمة حتى يُطلب منك ذلك. وإن لم يُصب أحد ولم يكن هناك حريق أو تسرّب أو خطر آخر، فأبلغ شرطة المرور بالحادث على الرقم 104."]},{heading:"ساعد المصابين دون أن تزيد الأمر سوءًا",points:["لا تحرّك المصاب إلا إذا كان في خطر مباشر، مثل النار أو الدخان الكثيف أو حركة سير لا يمكن إيقافها: فبعد الحادث قد تكون الرقبة أو الظهر مصابين.","إن كان المصاب واعيًا فتحدّث إليه بهدوء، واطلب منه أن يُبقي رأسه ورقبته ثابتين، وطمئنه بأن المساعدة في الطريق.","لا تنزع خوذة سائق الدراجة النارية؛ فهي لا تُنزع إلا إذا كان لا يتنفس أو كان مجرى الهواء مسدودًا، وعندئذٍ لا ينزعها إلا أشخاص مدرَّبون، ويُفضَّل أن يكونا اثنين، يُبقيان الرأس والرقبة ثابتين.","اضغط بقوة بقطعة قماش نظيفة على النزيف الشديد، واتبع تعليمات موظف الطوارئ على الرقم 122.","ابقَ مع المصابين حتى تصل الفرق، ثم اتبع تعليماتها."]},{heading:"إذا اشتعلت النار في مركبة",points:["علامات الخطر: دخان أو لهب، أو رائحة مطاط أو بلاستيك محترق. تصرّف فورًا.","إن كنت تقود فتوقّف على جانب الطريق حالما يكون ذلك آمنًا، وأطفئ المحرّك.","أخرِج الجميع وابتعدوا مسافة 30 مترًا (100 قدم) على الأقل عن المركبة المشتعلة، بعيدًا عن حركة السير وخارج الدخان، وفي الجهة التي تهبّ منها الريح إن أمكن.","لا تعد أبدًا إلى مركبة مشتعلة، لا من أجل هاتف ولا حقيبة ولا وثائق.","لا تفتح غطاء المحرّك أو صندوق السيارة إن ظننت أن النار في داخلهما: فالهواء الجديد قد يزيد النار اشتعالًا.","لا تحاول إطفاء النار بنفسك، واتصل بالرقم 115 من مسافة آمنة."]},{heading:"الوقود المتسرّب والحمولات الخطرة",points:["قد تشتعل أبخرة الوقود من شرارة أو سيجارة أو محرّك ساخن: فلا تدخين ولا لهب، والمحركات مطفأة.","أبعِد الناس عن الوقود المتسرّب، ولا تمشِ فيه.","شاحنة أو صهريج يحمل لوحات برتقالية أو علامات خطر: ابتعد كثيرًا، ولا تحاول إنقاذ أحد منه بنفسك، وأبلغ 115 بما تُظهره العلامات، ولا تستعمل هاتفك بالقرب منه.","لا تتجمهر حول موقع الحادث ولا تصوّر المصابين، وإن كنت مارًّا فقط فأبقِ عينيك على الطريق."]}],tips:["احتفظ في سيارتك بسترة عاكسة ومصباح يدوي وحقيبة إسعافات أولية.","انتبه دائمًا إلى اسم الطريق واتجاه سيرك والمعالم التي تمرّ بها.","اعتنِ بصيانة مركبتك بانتظام لدى فنيّ مختص، وافحص أي تسرّب للسوائل.","لا تنقل أبدًا عبوات الوقود أو أسطوانات الغاز داخل مقصورة الركاب.","التحق بدورة في الإسعافات الأولية لتعرف ما تفعله ريثما تصل المساعدة."],warnings:["قد تحاصر المركبة المشتعلة من فيها بسرعة: اخرج فورًا ولا تعد أبدًا.","لا تحرّك المصابين إلا إذا كانوا في خطر مباشر، ولا تنزع خوذة سائق الدراجة النارية.","التدخين واللهب والمحركات الدائرة قرب الوقود المتسرّب قد تُشعل حريقًا."],media:[{kind:"image",src:"media/images/w7_crash_scene_safety.webp",title:"المساعدة الآمنة في موقع الحادث",description:"سائق توقّف خارج الطريق وأضواء التحذير مشغّلة ويتصل طلبًا للمساعدة، بينما ينتظر الجميع بعيدًا عن سيارة يتصاعد منها الدخان."}],activity:{prompt:"ليلًا على طريق بين مدينتين، اصطدمت السيارة التي أمامك بالحاجز الجانبي، وبدأ الدخان يخرج من تحت غطاء محرّكها. السائق واعٍ ويحاول فتح الباب. ماذا تفعل؟",options:[{text:"أتوقف بأمان خلفها خارج الطريق، وأشغّل أضواء التحذير وأطفئ محرّكي، وأساعد السائق على الخروج والابتعاد بسبب الدخان، وأتصل بالرقمين 115 و122، وننتظر على بعد 30 مترًا على الأقل من السيارة.",correct:!0,feedback:"صحيح: فالدخان يعني خطرًا مباشرًا، لذا فمساعدة السائق الواعي على الخروج مبرَّرة. أنت تحمي نفسك أولًا، وتتصل بالرقمين، وتُبقي الجميع على بعد 30 مترًا على الأقل."},{text:"أفتح غطاء المحرّك لأرى مصدر الدخان، حتى أخبر 115 بدقة بما يحترق.",correct:!1,feedback:"فتح الغطاء يُدخل هواءً جديدًا فقد تكبر النار وتصل إلى وجهك. أبقِه مغلقًا، وأبعِد الجميع، واتصل بالرقم 115."},{text:"أتوقف بجانب السيارة مباشرة في المسار نفسه وأترك محرّكي دائرًا، لنتمكن من المغادرة بسرعة.",correct:!1,feedback:"التوقف في المسار يضعك في طريق السيارات الأخرى، والمحرّك الدائر قرب سيارة يخرج منها الدخان مصدر إضافي للاشتعال. توقّف خارج الطريق وأطفئ محرّكك."},{text:"أنتظر بضع دقائق لأرى هل يتوقف الدخان قبل أن أتصل، حتى لا أُجري مكالمة كاذبة.",correct:!1,feedback:"الحادث الحقيقي الذي يتصاعد منه الدخان ليس مكالمة كاذبة أبدًا، والدقائق مهمة بعد الحادث، لذا اتصل فورًا بالرقمين 115 و122."}]},quiz:[{question:"اشتعلت النار في سيارة. إلى أي مسافة يجب أن يبتعد الجميع؟",options:[{text:"30 مترًا (100 قدم) على الأقل، بعيدًا عن حركة السير",correct:!0},{text:"نحو 5 أمتار، قريبًا بما يكفي لمشاهدة النار",correct:!1},{text:"بجانب السيارة مباشرة، لإخراج الحقائب أولًا",correct:!1},{text:"في وسط الطريق، حيث يراك السائقون",correct:!1}],explanation:"توصي إرشادات السلامة من الحرائق (USFA وNFPA) بأن يبتعد الجميع 30 مترًا (100 قدم) على الأقل عن المركبة المشتعلة، وبعيدًا عن حركة السير. ولا تعد أبدًا من أجل الأغراض."},{question:"يخرج دخان من تحت غطاء محرّك سيارة. ماذا تفعل بالغطاء؟",options:[{text:"أبقِه مغلقًا: فالهواء يزيد النار اشتعالًا",correct:!0},{text:"افتحه على اتساعه ليخرج الدخان أسرع",correct:!1},{text:"ارفعه قليلًا واسكب الماء على المحرّك",correct:!1},{text:"افتحه لتفحص المحرّك قبل الاتصال بأحد",correct:!1}],explanation:"توصي USFA بعدم فتح غطاء المحرّك أو صندوق السيارة إن ظننت أن فيهما نارًا، لأن الهواء الجديد قد يزيد النار. ابتعد واتصل بالرقم 115."},{question:"متى يجوز لك إخراج مصاب من سيارة تعرّضت لحادث؟",options:[{text:"فقط إذا كان في خطر مباشر، مثل النار أو حركة السير",correct:!0},{text:"دائمًا وفورًا، ليتمكن من الاستلقاء على الأرض بجانب السيارة",correct:!1},{text:"متى وُجد شخصان قويّان لحمله",correct:!1},{text:"إذا لم تصل سيارة الإسعاف بعد عشر دقائق",correct:!1}],explanation:"قد تكون الرقبة أو الظهر مصابين بعد الحادث، وتنصّ إرشادات الإسعافات الأولية على عدم تحريك المصاب إلا إذا كان المكان غير آمن، بسبب النار أو الدخان أو حركة السير مثلًا."},{question:"سائق دراجة نارية ملقى على الطريق بعد حادث، وهو واعٍ ويتنفس. ماذا تفعل بخوذته؟",options:[{text:"اتركها على رأسه واطلب منه إبقاء رأسه ثابتًا",correct:!0},{text:"انزعها فورًا ليتنفس بشكل أفضل",correct:!1},{text:"أرخِها وأدِر رأسه لتفحص رقبته",correct:!1},{text:"اسحبها بسرعة قبل وصول سيارة الإسعاف",correct:!1}],explanation:"تبقى الخوذة على رأس السائق ما دام يتنفس، ولا تُنزع إلا إذا توقف عن التنفس أو انسدّ مجرى الهواء، وعندئذٍ ينزعها أشخاص مدرَّبون، ويُفضَّل أن يكونا اثنين، يُبقيان الرأس والرقبة ثابتين."},{question:"ما أول ما يحتاج فريق 115 أو 122 إلى سماعه منك؟",options:[{text:"الطريق واتجاهك ومَعلم قريب",correct:!0},{text:"نوع كل سيارة في الحادث وطرازها ولونها",correct:!1},{text:"رأيك في المتسبّب في الحادث وسببه",correct:!1},{text:"المستشفى الذي تفضّل أن يُنقل إليه المصابون",correct:!1}],explanation:"لا تستطيع الفرق المساعدة إلا إذا وجدتك. اذكر الموقع أولًا، ثم ما حدث، وعدد المصابين، وأي أخطار، ورقم هاتفك، ولا تُنهِ المكالمة حتى يُطلب منك ذلك."}]},{id:26,icon:"Waves",accent:"#0e7490",title:"الفيضانات: دليل للعائلات",subtitle:"التحذيرات، والسيول المفاجئة، والمغادرة في الوقت المناسب، والعودة الآمنة إلى المنزل",summary:"قد تأتي الفيضانات والسيول المفاجئة بسرعة، وأحيانًا بتحذير قليل أو من دون تحذير، ومعظم من يموتون في الفيضانات يموتون غرقًا. يساعد هذا الدرس عائلتك على الاستعداد، والتصرّف عند التحذيرات، والابتعاد عن مياه الفيضان، والمغادرة في الوقت المناسب، والعودة إلى المنزل بأمان.",blocks:[{heading:"التحذيرات والاستعداد",points:["تابع الإعلانات الرسمية للدفاع المدني والجهات المختصة عبر الإذاعة والتلفزيون وصفحاتها الرسمية، ولا تتصرّف بناءً على الشائعات.","اسأل الدفاع المدني والسلطات المحلية عن طريقة إعلان تحذيرات الفيضان وأوامر الإخلاء في منطقتك.","ضع خطة عائلية: إلى أي مكان مرتفع ستذهبون، وأي طريق ستسلكون، وكيف سيتواصل بعضكم مع بعض.","جهّز حقيبة الطوارئ: ماء الشرب، وطعامًا لا يفسد، والأدوية، ومصباحًا يدويًا، ومذياعًا، وبطاريات، ومستلزمات الإسعافات الأولية، ونسخًا من الوثائق المهمة في كيس مانع للماء.","خطّط للأطفال وكبار السن وذوي الإعاقة وكل من يحتاج إلى مساعدة في التنقّل."]},{heading:"السيول المفاجئة في الوديان ومجاري الأنهار الجافة",points:["يأتي السيل المفاجئ عادةً خلال 6 ساعات من هطول المطر الغزير، وأحيانًا خلال دقائق، وقد يكون المطر قد هطل بعيدًا عنك.","قد يمتلئ مجرى نهر جاف أو وادٍ بالمياه الجارفة خلال دقائق، حتى إن لم تكن تمطر حيث أنت.","لا تخيّم ولا تتنزّه ولا توقف سيارتك في أرض منخفضة بجانب مجرى ماء أو داخل مجرى نهر جاف حين تكون الأمطار متوقعة أو العواصف قريبة.","إذا بدأ الماء يرتفع فاصعد فورًا إلى مكان أعلى: اصعد سيرًا على قدميك، ولا تحاول الخروج بالسيارة.","يصعب ليلًا أن ترى السيل قادمًا، لذا خذ التحذيرات بجدية قبل حلول الظلام."]},{heading:"استدر ولا تغرق",points:["لا تمشِ ولا تسبح ولا تقُد في مياه الفيضان أبدًا: فالمياه الجارية بعمق 15 سم قد تُسقط البالغ أرضًا، وبعمق 30 سم قد تجرف معظم السيارات.","استدر وابحث عن طريق آخر؛ فقد يكون الطريق تحت الماء منهارًا، ولا تلتفّ أبدًا حول الحواجز التي تغلق طريقًا غمرته المياه.","ابتعد عن الجسور الممتدة فوق المياه السريعة الجريان.","قد تخفي مياه الفيضان حفرًا وحطامًا وأخطارًا كهربائية، وكثيرًا ما تكون ملوّثة.","إن كان أحد في الماء فلا تنزل وراءه: اتصل بالرقمين 115 و122، ثم مدّ إليه عصا أو حبلًا أو ارمِ له شيئًا يطفو من مكان آمن."]},{heading:"متى تغادر وكيف",points:["غادر فورًا إذا طلبت منك الجهات المختصة ذلك، وغادر مبكرًا بما يكفي كي لا تحاصرك المياه.","خذ حقيبة الطوارئ، واتبع الطرق الموصى بها، ولا تسلك طرقًا مختصرة فقد تكون مغلقة أو غمرتها المياه.","لا تفصل الكهرباء قبل المغادرة إلا إذا طُلب منك ذلك واستطعت فعله بأمان، ولا تلمس أبدًا المفاتيح أو الأجهزة الكهربائية وأنت مبتلّ أو واقف في الماء.","الغاز: إذا شممت رائحة غاز فلا تلمس أي مفتاح كهربائي؛ اخرج ونبّه الآخرين واتصل بالرقم 115 من الخارج. ولا تغلق صمام الغاز إلا إذا كان قريبًا وأمكنك الوصول إليه دون دخول المكان الذي تجمّع فيه الغاز.","إذا حاصرتك المياه داخل مبنى فانتقل إلى أعلى مستوى آمن، واتصل بالرقم 115 وحدّد موقعك بدقة. لا تدخل غرفة مغلقة تحت السطح قد تحاصرك فيها المياه، واصعد إلى السطح عند الضرورة فقط."]},{heading:"العودة الآمنة إلى المنزل",points:["لا تعد إلا حين تعلن الجهات المختصة أن العودة آمنة، وإن كان المنزل متضررًا فلا تدخله حتى يفحصه خبير في المباني.","أبقِ الكهرباء مفصولة حتى يفحص كهربائي مختص المنزل، وإن كان الوصول إلى المفتاح الرئيسي يتطلب أن تخطو في الماء فاتصل بكهربائي بدلًا من ذلك.","لا تلمس الأجهزة الكهربائية إن كانت مبتلّة أو كنت واقفًا في الماء.","اتبع التعليمات المحلية بشأن صلاحية ماء الحنفية للشرب، وتخلّص من أي طعام ربما لامس مياه الفيضان: فعند الشك تخلّص منه.","هوِّ المنزل وجفّفه، وإن بقي مغلقًا ومبتلًّا عدة أيام فتوقّع وجود العفن، والبس حذاءً مطاطيًا طويلًا وقفازين عند التنظيف.","لا تشغّل المولّد إلا في الخارج، على بعد 6 أمتار (20 قدمًا) على الأقل من الأبواب والنوافذ وفتحات التهوية، ولا تشغّله أبدًا داخل المنزل ولو كانت الأبواب مفتوحة."]}],tips:["اعرف هل يقع منزلك أو مكان عملك أو مدرستك في منطقة منخفضة أو قرب وادٍ معرّض للسيول.","اتفقوا على نقطة تجمّع في مكان مرتفع وعلى قريب خارج المنطقة يتواصل معه الجميع.","عند توقّع أمطار غزيرة، اشحن هاتفك وأبقِ مذياعًا يعمل بالبطاريات جاهزًا.","اطمئن على الجيران من كبار السن وذوي الإعاقة قبل الفيضان وبعده.","تدرّبوا على خطة العائلة معًا."],warnings:["لا تمشِ ولا تسبح ولا تقُد في مياه الفيضان أبدًا: استدر وابحث عن طريق آخر.","الكهرباء والماء معًا قد يقتلان: لا تلمس أبدًا المفاتيح أو الأجهزة الكهربائية وأنت مبتلّ أو في الماء.","يجب ألّا يلعب الأطفال أبدًا في مياه الفيضان أو الجداول أو قنوات تصريف المياه بعد المطر."],media:[{kind:"image",src:"media/images/w7_flood_family_higher_ground.webp",title:"العائلات تنتقل إلى مكان مرتفع",description:"عائلة تحمل حقيبة الطوارئ تصعد تلًّا سيرًا على الأقدام بعيدًا عن جدول في وادٍ يرتفع منسوبه بعد المطر."}],activity:{prompt:"هطل مطر غزير على الجبال طوال الليل. عائلتك في نزهة في وادٍ بجانب مجرى نهر جاف، ولا تمطر حيث أنتم. فجأةً بدأ المجرى يمتلئ بمياه موحلة. ماذا تفعلون؟",options:[{text:"نترك أغراضنا ونصعد فورًا سيرًا إلى مكان أعلى بعيدًا عن المجرى، ثم نتصل بالرقم 115 إن كان أحد في خطر.",correct:!0,feedback:"قد يرتفع السيل المفاجئ خلال دقائق، وترك كل شيء والصعود سيرًا فورًا إلى مكان أعلى هو الخيار الأكثر أمانًا؛ فالأغراض تُعوَّض، والحياة لا تُعوَّض."},{text:"نضع كل شيء في السيارة بسرعة ونخرج بها عبر الطريق في قاع الوادي.",correct:!1,feedback:"جمع الأغراض يضيّع الدقائق، وقد يكون طريق قاع الوادي أول ما تغمره المياه: فالمياه الجارية بعمق 30 سم قد تجرف السيارة. اصعد سيرًا ولا تخرج بالسيارة."},{text:"ننتظر ونراقب، لأنها لا تمطر هنا، فلن يرتفع الماء كثيرًا.",correct:!1,feedback:"تأتي السيول المفاجئة كثيرًا من مطر هطل بعيدًا، وقد يتحوّل المجرى الجاف إلى سيل جارف خلال دقائق، لذا اصعد إلى مكان مرتفع الآن."},{text:"نعبر المجرى بسرعة إلى الضفة الأخرى قبل أن يصبح الماء عميقًا.",correct:!1,feedback:"لا تدخل أبدًا في ماء جارٍ: فعمق 15 سم فقط قد يُسقط البالغ أرضًا. اصعد إلى مكان أعلى من جهتك نفسها."}]},quiz:[{question:"ما العمق الذي يكفي لمياه الفيضان الجارية كي تُسقط شخصًا بالغًا؟",options:[{text:"نحو 15 سم",correct:!0},{text:"نحو متر واحد",correct:!1},{text:"نحو 50 سم",correct:!1},{text:"فقط إذا تجاوز الخصر",correct:!1}],explanation:"تحذّر هيئة الأرصاد الجوية الوطنية الأمريكية (NWS) من أن نحو 15 سم (6 بوصات) من المياه السريعة قد تُسقط البالغ، وأن نحو 30 سم (12 بوصة) قد تجرف معظم السيارات."},{question:"الطريق أمامك تغطيه مياه جارية. ماذا تفعل؟",options:[{text:"استدر وخذ طريقًا آخر",correct:!0},{text:"اعبره ببطء على سرعة منخفضة",correct:!1},{text:"اعبره سيرًا أولًا لتختبر عمقه",correct:!1},{text:"اتبع السيارة التي أمامك عبره",correct:!1}],explanation:"استدر ولا تغرق: فلا يمكنك أن ترى عمق الماء أو سرعته، ولا هل انهار الطريق تحته. لا تمشِ ولا تقُد في مياه الفيضان أبدًا."},{question:"قبل مغادرة منزلك أثناء الفيضان، متى تفصل الكهرباء؟",options:[{text:"فقط إذا طُلب منك ذلك وبقيت جافًّا وأنت تفعله",correct:!0},{text:"دائمًا، حتى لو اضطررت إلى الوقوف في الماء للوصول إليه",correct:!1},{text:"أبدًا: اترك كل الأجهزة تعمل ليبقى المنزل مضاءً",correct:!1},{text:"فقط بعد أن تغطي المياه الأرضية",correct:!1}],explanation:"لا تفصل الكهرباء قبل المغادرة إلا إذا طُلب منك ذلك واستطعت فعله بأمان، ولا تلمس أبدًا المفاتيح أو الأجهزة الكهربائية وأنت مبتلّ أو واقف في الماء."},{question:"بعد الفيضان، متى تستطيع عائلتك العودة إلى المنزل؟",options:[{text:"عندما تعلن الجهات المختصة أن ذلك آمن",correct:!0},{text:"بمجرد توقّف المطر",correct:!1},{text:"عندما يصبح الماء في الخارج دون ركبتيك",correct:!1},{text:"في صباح اليوم التالي، مهما كان الضرر",correct:!1}],explanation:"لا تعد إلا حين تعلن الجهات المختصة أن العودة آمنة، ويجب أن يفحص خبير في المباني المنزلَ المتضرر، وكهربائيٌّ الكهرباءَ، قبل استعمالهما."},{question:"أين يجوز تشغيل المولّد بعد الفيضان؟",options:[{text:"في الخارج، على بعد 6 أمتار على الأقل من الأبواب والنوافذ",correct:!0},{text:"في المرآب، إذا تُرك باب المرآب مفتوحًا",correct:!1},{text:"داخل المنزل، بجانب نافذة مفتوحة مباشرة",correct:!1},{text:"في الممر، ما دامت كل الأبواب مفتوحة",correct:!1}],explanation:"تُطلق المولّدات غاز أول أكسيد الكربون (CO) السام الذي لا لون له ولا رائحة. شغّلها في الخارج فقط، على بعد 6 أمتار (20 قدمًا) على الأقل من الأبواب والنوافذ وفتحات التهوية، ولا تشغّلها أبدًا في الداخل ولو كانت الأبواب مفتوحة."}]},{id:27,icon:"CloudLightning",accent:"#7c3aed",title:"الطقس القاسي لعامة الناس",subtitle:"الحرّ والبرق والعواصف الترابية والرياح الشديدة والثلج والجليد",summary:"قد يؤذي الطقس القاسي الناس في وقت قصير. وفي منطقتنا نواجه موجات الحرّ، والعواصف الرعدية المصحوبة بالبرق، والعواصف الترابية، والرياح الشديدة، والثلج والجليد. يقدّم هذا الدرس أهم التصرفات الآمنة لكل منها. واتبع دائمًا تحذيرات الطقس الصادرة عن الجهات المختصة وتعليمات الدفاع المدني.",blocks:[{heading:"موجات الحرّ",points:["كبار السن والأطفال الصغار والمصابون بأمراض مزمنة أكثر عرضة للخطر، فاطمئن عليهم كثيرًا خلال موجة الحرّ.","اشرب الماء بانتظام طوال اليوم حتى قبل أن تشعر بالعطش، وتجنّب العمل الشاق والرياضة في أشدّ ساعات الحرّ.","الإنهاك الحراري (Heat exhaustion): تعرّق غزير، وضعف، ودوار، وصداع، وغثيان، وعطش. انقل المصاب إلى مكان بارد، وبرّده بالماء، وأعطه رشفات من الماء إذا كان واعيًا تمامًا. واطلب المساعدة الطبية إذا تقيّأ أو ساءت الأعراض أو استمرت أكثر من ساعة.","ضربة الحرّ (Heatstroke): اضطراب الوعي، أو سلوك غريب، أو تثاقل في الكلام، أو نوبة تشنّج، أو انهيار في الحرّ؛ وقد يكون الجلد حارًّا وجافًّا أو لا يزال متعرّقًا. اتصل بالرقم 122 وابدأ تبريد المصاب فورًا: وأفضل طريقة غمر الجسم حتى الرقبة في ماء بارد لمدة 15 دقيقة أو حتى يعود تفكيره واضحًا، أيّهما أسبق؛ وإلا فاستخدم دشًّا باردًا ومناشف مبلّلة بماء بارد وأكياس ثلج مع التهوية بالمروحة. ولا تعطِ المصاب المضطرب الوعي شيئًا ليشربه.","لا تترك أبدًا طفلًا، أو أي شخص، في سيارة متوقفة ولو لدقيقة واحدة: فقد يصبح داخلها شديد الحرارة بسرعة."]},{heading:"البرق",points:["إذا دوّى الرعد فادخل إلى مكان مغلق: فإن كنت تسمع الرعد فالبرق قد يصيبك، ولا يوجد مكان آمن في الخارج أثناء العاصفة الرعدية.","احتمِ في مبنى متين أو في سيارة ذات سقف معدني ونوافذ مغلقة، وابقَ في الداخل حتى تمرّ 30 دقيقة على آخر رعد.","إن لم تستطع الوصول إلى ملجأ فابتعد عن قمم التلال والأراضي المكشوفة والأشجار العالية المنفردة والمياه والأسوار المعدنية، فالخيمة لا تحمي.","في الداخل ابتعد عن النوافذ والأبواب، ولا تستعمل الهاتف السلكي، وتجنّب الاستحمام وغسل الأطباق حتى تمرّ العاصفة."]},{heading:"العواصف الترابية",points:["في المنزل ابقَ في الداخل وأغلق النوافذ والأبواب.","يحتاج الرضّع وكبار السن ومرضى الربو وغيرهم ممن يعانون مشكلات في التنفس إلى عناية إضافية: يبقون في الداخل، ويتبع مرضى الربو خطة الربو الخاصة بهم ويحملون معهم البخّاخ الموصوف لهم.","القيادة: لا تدخل بسيارتك في العاصفة الترابية. وإذا انخفضت الرؤية فابتعد عن الطريق قدر استطاعتك، وتوقّف، وأطفئ جميع الأضواء، واسحب فرامل اليد، وارفع قدمك عن دوّاسة الفرامل. ولا تتوقف أبدًا على الطريق نفسه.","يجب أن تكون أضواؤك مطفأة وأنت متوقف: فقد يتبع السائقون خلفك أضواءك فيصطدموا بك."]},{heading:"الرياح الشديدة",points:["قبل هبوب الرياح، اربط الأشياء غير المثبّتة على الأسطح والشرفات وفي الساحات أو أدخلها، حتى لا تقذفها الرياح على الناس أو النوافذ.","أثناء الرياح، ادخل مبنى متينًا وانتقل إلى غرفة داخلية بعيدة عن النوافذ.","قد تكون أسلاك الكهرباء الساقطة موصولة بالتيار: فلا تقترب منها ولا مما يلامسها، وأبعِد الآخرين، واتصل بالرقم 115.","إن كنت تقود فأمسك المقود بكلتا يديك، وخفّف السرعة، وابتعد عن الشاحنات والحافلات."]},{heading:"الثلج والجليد والتدفئة",points:["المدافئ: أبقِ منفذًا للهواء النقي في الغرفة، وركّب جهاز إنذار CO، ولا تدفّئ المنزل أبدًا بفرن الغاز، ولا تستعمل المولّد أو نار الفحم في الداخل أبدًا.","قد يدلّ الصداع أو الدوار أو الغثيان أو اضطراب الوعي قرب المدفأة على تسمّم بأول أكسيد الكربون (CO): أخرِج الجميع فورًا إلى الهواء الطلق، واتصل بالرقمين 115 و122 من الخارج.","على الجليد البس حذاءً مانعًا للانزلاق، وخذ خطوات قصيرة، وامشِ ببطء.","في الثلج والجليد تجنّب القيادة إن استطعت، وإن اضطررت إليها فخفّف السرعة حتى لو بدا الطريق مبتلًّا فقط، واحتفظ في السيارة ببطانيات وماء ومصباح يدوي وهاتف مشحون."]}],tips:["تابع النشرة الجوية وتحذيرات الجهات المختصة والدفاع المدني.","في موجات الحرّ والبرد الشديد اطمئن كثيرًا على الجيران والأقارب من كبار السن.","ثبّت الأشياء غير المثبّتة على الأسطح والشرفات بمجرد توقّع رياح شديدة.","جهّز مصباحًا يدويًا ومذياعًا يعمل بالبطاريات وهاتفًا مشحونًا تحسّبًا للعواصف.","اطلب فحص المدافئ والمواقد، وأبعِد عنها كل ما يمكن أن يشتعل."],warnings:["لا تترك طفلًا أبدًا في سيارة متوقفة ولو لدقيقة واحدة.","إذا دوّى الرعد فادخل: لا مكان آمنًا في الخارج.","لا تشغّل أبدًا مولّدًا أو نار فحم في الداخل، ولا تدفّئ المنزل أبدًا بفرن الغاز."],media:[{kind:"image",src:"media/images/w7_severe_weather_actions.webp",title:"تصرّفات آمنة في الطقس القاسي",description:"أربع لقطات: تبريد شخص في الظل أثناء موجة حرّ، وعائلة تدخل المنزل مع اقتراب عاصفة رعدية، وسيارة متوقفة بعيدًا عن الطريق وأضواؤها مطفأة في عاصفة ترابية، وشخص يبتعد عن سلك كهرباء ساقط."}],activity:{prompt:"في عصر يوم شديد الحرّ، كان جارك المسنّ يعمل في حديقته. والآن هو مضطرب الوعي ويتكلم بطريقة غريبة وجلده حارّ جدًّا. ماذا تفعل؟",options:[{text:"أتصل بالرقم 122، وأنقله إلى الظل أو إلى غرفة باردة، وأبدأ تبريده فورًا بالماء البارد والمناشف المبلّلة والتهوية، ولا أعطيه شيئًا ليشربه.",correct:!0,feedback:"اضطراب الوعي في الحرّ يعني ضربة حرّ، وهي حالة طارئة، والاتصال بالرقم 122 وتبريده فورًا قد ينقذان حياته، ولا يُعطى المضطرب الوعي شيئًا ليشربه."},{text:"أعطيه كوبًا كبيرًا من الماء البارد ليشربه، وأتركه يستريح على كرسي في الحديقة.",correct:!1,feedback:"لا يُعطى المضطرب الوعي شيئًا ليشربه، والبقاء في الحديقة يُبقيه في الحرّ. اتصل بالرقم 122، وانقله إلى مكان بارد، وبرّده فورًا."},{text:"أساعده على النوم في الداخل حتى يتحسّن، وأعود لأطمئن عليه في المساء.",correct:!1,feedback:"قد تقتل ضربة الحرّ إذا تأخّر التبريد، فلا تتركه ينام: اتصل بالرقم 122 وابدأ التبريد الآن."},{text:"أنقله بنفسي فورًا بالسيارة إلى المستشفى، دون أن أتوقف لتبريده أولًا.",correct:!1,feedback:"في ضربة الحرّ يأتي التبريد أولًا ثم النقل. اتصل بالرقم 122 وابدأ التبريد فورًا، وسيرشدك موظف الطوارئ."}]},quiz:[{question:"أثناء العاصفة الرعدية، متى يجب أن تدخل إلى مكان مغلق؟",options:[{text:"بمجرد أن تسمع الرعد",correct:!0},{text:"فقط حين يشتدّ المطر",correct:!1},{text:"فقط حين يكون البرق فوقك مباشرة",correct:!1},{text:"عندما تبدأ الرياح بالاشتداد",correct:!1}],explanation:"إن كنت تسمع الرعد فأنت قريب بما يكفي لأن يصيبك البرق. إذا دوّى الرعد فادخل، فلا يوجد مكان آمن في الخارج أثناء العاصفة الرعدية."},{question:"بعد آخر رعد، كم تنتظر قبل أن تعود إلى الخارج؟",options:[{text:"30 دقيقة",correct:!0},{text:"5 دقائق",correct:!1},{text:"حتى يتوقف المطر",correct:!1},{text:"لا داعي للانتظار",correct:!1}],explanation:"قد يضرب البرق حتى بعد أن يخفّ المطر، وتنصح هيئة الأرصاد الجوية الوطنية الأمريكية (NWS) بالانتظار 30 دقيقة بعد آخر برق أو رعد قبل العودة إلى الخارج."},{question:"أثناء القيادة، خفّضت عاصفة ترابية الرؤية فجأةً. ما التصرف الأكثر أمانًا؟",options:[{text:"ابتعد كثيرًا عن الطريق، وتوقّف، وأطفئ جميع الأضواء",correct:!0},{text:"توقّف في مسارك وشغّل أضواء التحذير",correct:!1},{text:"زِد سرعتك لتخرج من الغبار بأسرع ما يمكن",correct:!1},{text:"اتبع الأضواء الخلفية للسيارة التي أمامك",correct:!1}],explanation:"لا تتوقف أبدًا على الطريق نفسه. ابتعد عنه قدر استطاعتك، وأطفئ جميع الأضواء، واسحب فرامل اليد، وارفع قدمك عن الفرامل، حتى لا يتبع السائقون خلفك أضواءك فيصطدموا بك (NWS، «Pull aside, stay alive»)."},{question:"أيٌّ مما يلي يدلّ على ضربة الحرّ لا على الإنهاك الحراري؟",options:[{text:"اضطراب الوعي أو السلوك الغريب في الحرّ",correct:!0},{text:"العطش بعد يوم طويل من العمل تحت الشمس",correct:!1},{text:"التعرّق الغزير والتعب بعد العمل",correct:!1},{text:"صداع خفيف أثناء الجلوس في غرفة حارّة",correct:!1}],explanation:"اضطراب الوعي أو السلوك الغريب أو التشنّج أو الانهيار في الحرّ يعني ضربة حرّ، وهي حالة طارئة تهدد الحياة: اتصل بالرقم 122 وبرّد المصاب فورًا. أما العطش والتعرّق الغزير والصداع الخفيف فتناسب الإنهاك الحراري."},{question:"بعد عاصفة ترى سلك كهرباء ملقى على الأرض. ماذا تفعل؟",options:[{text:"ابتعد عنه، وأبعِد الآخرين، واتصل بالرقم 115",correct:!0},{text:"أزحه جانبًا بعصا خشبية جافة",correct:!1},{text:"اخطُ فوقه بحذر إن لم يكن يُصدر شررًا",correct:!1},{text:"اعبر فوقه ببطء بسيارتك",correct:!1}],explanation:"قد يكون السلك الساقط، وكل ما يلامسه من أشياء أو مياه، موصولًا بالتيار حتى لو لم يُصدر شررًا. لا تلمسه ولا تحرّكه ولا تقُد فوقه أبدًا: أبعِد الجميع واتصل بالرقم 115."}]},{id:28,icon:"Truck",accent:"#4d7c0f",title:"السلامة في الزراعة والحياة الريفية",subtitle:"المبيدات والجرّارات والآلات، والحبوب والتبن، والمخاطر المخفية في التربة",summary:"للعمل الزراعي مخاطره الخاصة: سموم تُستخدم لحماية المحاصيل، وآلات ثقيلة قد تنقلب أو تعلق بها الملابس، ومخازن حبوب وتبن قد تطمر الإنسان وتخنقه أو تشتعل، وذخائر قديمة في باطن الأرض. والأطفال الذين يلعبون قرب العمل أو يركبون الآلات معرّضون لخطر خاص. يوضّح هذا الدرس كيف تحمي الأسر الزراعية والعاملون في الزراعة أنفسهم، وماذا يفعلون إذا وقع مكروه.",blocks:[{heading:"المبيدات: احفظها بأمان",body:"تحدث حالات تسمّم كثيرة لأن مبيدًا كان في متناول اليد أو بدا كأنه شراب:",points:["احفظ المبيدات في مكان مقفل، بعيدًا عن متناول الأطفال، ولا تضعها أبدًا مع الطعام أو علف الحيوانات أو الأدوية أو بالقرب منها.","أبقِ كل مبيد في عبوته الأصلية مع ملصقه. لا تسكبه أبدًا في قنينة مشروب أو كوب أو وعاء طعام: فقد يشربه أحد.","لا تحتفظ في المنزل بالمبيدات شديدة السمّية أو المركّزة؛ احفظها في مخزن منفصل ومقفل.","لا تستعمل عبوات المبيدات الفارغة أبدًا للماء أو الطعام أو علف الحيوانات. تخلّص منها كما يقول الملصق والجهات المحلية.","قد تبدو البذور المعالجة وطُعوم القوارض مثل الحبوب العادية: احفظها في مكان مقفل بعيدًا عن الأطفال والحيوانات."]},{heading:"استعمال المبيدات بأمان",points:["اقرأ الملصق كاملًا قبل فتح العبوة واتّبعه بدقة: الكمية، وطريقة الخلط، ومعدات الوقاية، والمدة التي يجب أن يبقى فيها الناس بعيدين عن المكان المعالَج.","ارتدِ ملابس الوقاية التي يطلبها الملصق، مثل قفازات لا ينفذ منها الماء، وسراويل طويلة، وأكمام طويلة.","أبعِد الأطفال والآخرين والحيوانات أثناء الخلط والرشّ، وحتى تنقضي المدة المكتوبة على الملصق.","بعد الرشّ، بدّل ملابسك واغسل يديك فورًا. لا تترك ملابس العمل أو معدات الرشّ حيث يلعب الأطفال."]},{heading:"إذا تسمّم شخص بمبيد",body:`قد يكون الدوار، أو التعب، أو تشوّش الرؤية، أو الغثيان، أو جفاف الحلق، أو صعوبة التنفّس، أو حرقة العينين، أو حكّة الجلد، أو ضعف العضلات أثناء العمل بالمبيدات أو بعده علامات على التسمّم.

1. احمِ نفسك أولًا: ارتدِ القفازات ولا تلمس المبيد بيدين عاريتين. أبعِد الشخص عنه إلى الهواء النقي.
2. اتصل بالرقم 122 فورًا، حتى لو بدا الشخص بخير، واحتفظ بالعبوة أو ملصقها لتريها لفريق الإسعاف والأطباء.
3. إذا ابتُلع المبيد: لا تجعل الشخص يتقيّأ، ولا تعطه شيئًا يأكله أو يشربه إلا إذا قال الطبيب ذلك.
4. على الجلد أو في العينين: انزع الملابس الملوّثة واغسل الجلد، أو العين المفتوحة، بكمية وفيرة من الماء الجاري مدة 15 دقيقة على الأقل.
5. إذا كان الشخص فاقد الوعي لكنه يتنفّس طبيعيًا، ولا إصابة في رقبته أو ظهره أو وركه أو حوضه، فضعه على جنبه وواصل مراقبة تنفّسه. وإذا توقّف عن التنفّس الطبيعي، فابدأ الإنعاش القلبي الرئوي (CPR) (انظر درس «التسمّم في المنزل»).`},{heading:"الجرّارات والآلات",body:"انقلاب الجرّار، ودهس الأشخاص، وعلوق الملابس في عمود نقل الحركة الدوّار (PTO) هي أسباب معظم الإصابات الخطيرة بالجرّارات.",points:["استعمل جرّارًا مزوّدًا بهيكل حماية من الانقلاب (ROPS: قضيب حماية أو كابينة آمنة)، واربط حزام الأمان دائمًا: فهما معًا يمنحان السائق أفضل فرصة للنجاة من الانقلاب. ويمكن لوكيل مختص تركيب هيكل على كثير من الجرّارات القديمة.","ابتعد عن الخنادق والحوافّ والحفر، ولا تسِر على المنحدرات شديدة الانحدار، وخفّف السرعة عند الانعطاف وعلى الأرض الوعرة أو الزلقة أو الموحلة.","أبقِ جميع واقيات عمود نقل الحركة (PTO) والآلات في أماكنها. اربط الشعر الطويل ولا ترتدِ ملابس فضفاضة قرب الأجزاء المتحرّكة.","قبل تنظيف آلة أو ضبطها أو فكّ انسدادها، أطفئ المحرّك وانتظر حتى يتوقّف العمود وجميع الأجزاء المتحرّكة.","لا يركب أحد على الجرّار ما لم يكن فيه مقعد وحزام أمان لذلك الشخص. ولا يركب الأطفال أبدًا على الجرّارات أو الآلات ولا يلعبون بالقرب منها.","قبل تشغيل المحرّك أو عمود نقل الحركة، تأكّد من أن الجميع، ولا سيما الأطفال، بعيدون عن الآلة مسافة كافية."]},{heading:"الحبوب والتبن والقش",points:["لا تدخل أبدًا صومعة أو مخزن حبوب أو مقطورة حبوب بينما الحبوب تتحرّك أو تُفرَّغ: فالحبوب المتدفّقة تعمل كالرمال المتحرّكة وقد تطمر الإنسان في ثوانٍ. ولا تمشِ أبدًا على الحبوب لتجعلها تتدفّق.","الحبوب التي تكوّنت عليها قشرة صلبة أو صارت كومة عالية شديدة الانحدار قد تنهار فجأة على أيّ شخص يقف عليها أو بجانبها.","لا يلعب الأطفال أبدًا في مخازن الحبوب أو مقطوراتها أو أكوام التبن والقش.","لا تكبس التبن ولا تخزّنه إلا بعد أن يجفّ تمامًا: فالتبن الرطب أو الأخضر قد يسخن من الداخل ويشتعل من تلقاء نفسه، من أسبوعين إلى ثلاثة أشهر أو أكثر بعد الكبس.","علامات التحذير: بخار يتصاعد من الكومة، أو عفن، أو رائحة احتراق أو رطوبة أو رائحة حلوة تشبه الكراميل. إذا رأيت دخانًا أو شممت رائحته، أو كان جزء من الكومة ساخنًا جدًا، فلا تفكّكها: أبعِد الناس واتصل بالرقم 115.","أبقِ أكوام التبن والقش بعيدة عن المنازل والآلات والوقود والمواد الكيميائية وأسلاك الكهرباء."]},{heading:"الذخائر المتفجّرة وحرائق الحقول",points:["إذا كشفت الحراثة أو الحفر عن جسم غريب، فأوقف العمل فورًا. لا تلمسه ولا تحرّكه، وأبعِد الجميع، وابتعد كثيرًا قبل استخدام الهاتف، وأبلغ عنه على الرقم 115 (انظر درس «الألغام والذخائر غير المنفجرة: ابقَ آمنًا»).","لا تزرع ولا ترعَ المواشي في أرض معلَّمة بأنها خطرة أو يتجنّبها الناس. والمكان الخالي من علامات التحذير ليس آمنًا بالضرورة: فالحقل المهجور الذي نمت فيه الأعشاب بجوار حقول مزروعة قد يخفي ألغامًا.","إذا ظننت أنك في منطقة ألغام: توقّف، وابقَ ثابتًا، واطلب المساعدة، وانتظر فريقًا مدرَّبًا.","لا توقف الجرّارات أو السيارات على العشب الجاف أو بقايا الحصاد: فالعادم الساخن قد يشعلها. أما حرائق موسم الحصاد فيشرحها درس «حرائق المحاصيل وبقايا الحصاد والأعشاب»."]}],tips:["احفظ المبيدات في مكان مقفل داخل عبواتها الأصلية التي تحمل الملصق.","اقرأ الملصق قبل كل استعمال وارتدِ ملابس الوقاية التي يطلبها.","اربط حزام الأمان في الجرّار المزوّد بقضيب حماية، وأبقِ جميع الواقيات في أماكنها.","أطفئ المحرّك وانتظر حتى يتوقّف كل شيء قبل تنظيف آلة أو فكّ انسدادها.","اتّفقوا كأسرة على أماكن لعب الأطفال: بعيدًا عن الآلات ومخازن الحبوب وأكوام التبن والحقول المرشوشة."],warnings:["لا تضع المبيدات أو الوقود أبدًا في قناني المشروبات أو أوعية الطعام.","لا تسمح أبدًا لطفل بالركوب على جرّار أو اللعب قرب آلات تعمل.","لا تدخل أبدًا صومعة أو مخزن حبوب بينما الحبوب تتحرّك، ولا تمشِ أبدًا على الحبوب لتجعلها تتدفّق."],activity:{prompt:"جارك على وشك حراثة حقل على منحدر. يطلب ابنه ذو السنوات الثماني أن يجلس على غطاء عجلة الجرّار ويركب معه، ويقول الأب إن الأمر لدقائق قليلة فقط. بماذا تنصح؟",options:[{text:"لا يركب الصبي الجرّار ويبقى بعيدًا عن الحقل؛ ويربط الأب حزام الأمان ويتجنّب أيّ منحدر شديد الانحدار.",correct:!0,feedback:"قد يسقط الطفل تحت العجلات أو المحراث، وقد ينقلب الجرّار على المنحدر في ثوانٍ. يبقى الأطفال بعيدين جدًا عن الآلات العاملة، ويربط السائق حزام الأمان."},{text:"يمكن للصبي أن يركب إذا جلس على غطاء العجلة وتمسّك جيدًا بكلتا يديه.",correct:!1,feedback:"يسقط الأطفال عن أغطية العجلات وتدهسهم العجلات أو المحراث. لا يركب أحد دون مقعد وحزام أمان خاصّين به، والأطفال لا يركبون أبدًا."},{text:"يمكن للصبي أن يركب ما دام أبوه يقود ببطء شديد على المنحدر.",correct:!1,feedback:"قد يحدث الانقلاب في ثوانٍ حتى بسرعة منخفضة، والمنحدر يزيد الخطر. لا يركب الصبي الجرّار."},{text:"يمكن للصبي أن يمشي خلف المحراث ليرى كيف يقلب التربة.",correct:!1,feedback:"الطفل الذي يمشي قرب محراث يتحرّك قد يُدهَس أو يعلق فيه. يبقى الأطفال بعيدين جدًا عن الآلات العاملة."}]},quiz:[{question:"أين يجب حفظ المبيدات؟",options:[{text:"في مكان مقفل، داخل العبوة الأصلية ذات الملصق، بعيدًا عن الطعام",correct:!0},{text:"في قنينة مشروب نظيفة، مع كتابة اسم المبيد عليها بالقلم",correct:!1},{text:"على رفّ عالٍ في المطبخ، حيث تستطيع الأسرة رؤيتها دائمًا",correct:!1},{text:"في صندوق مفتوح في الفناء، حيث يحمل الهواء الرائحة بعيدًا",correct:!1}],explanation:"في قنينة مشروب أو في المطبخ قد يُظنّ المبيد شرابًا أو تصل إليه أيدي الأطفال. احفظه في عبوته الأصلية مع ملصقه، في مكان مقفل، بعيدًا عن الطعام وعلف الحيوانات."},{question:"عامل زراعي يشعر بالدوار ولا يرى جيدًا ويشعر بالغثيان بعد الرشّ. ماذا تفعل أولًا؟",options:[{text:"أنقله إلى الهواء النقي وأتصل بالرقم 122، وأحتفظ بالملصق",correct:!0},{text:"أعطيه كوبًا من الحليب ليغسل السمّ من معدته",correct:!1},{text:"أجعله يتقيّأ فورًا، ثم أتركه يرتاح في الظل",correct:!1},{text:"أتركه يُكمل الرشّ، ثم يستحمّ في المنزل",correct:!1}],explanation:"قد تكون هذه علامات تسمّم بالمبيدات. أبعِد الشخص عن المبيد، واتصل بالرقم 122، واحتفظ بالعبوة أو الملصق للأطباء؛ ولا تجعله يتقيّأ أبدًا، ولا تعطه الحليب أو العلاجات المنزلية."},{question:"لماذا يجب على سائق جرّار مزوّد بقضيب حماية (ROPS) أن يربط حزام الأمان؟",options:[{text:"ليبقى داخل المنطقة المحمية إذا انقلب الجرّار",correct:!0},{text:"ليتجنّب الغرامة حين يقود على الطريق الرئيسي",correct:!1},{text:"لأن حزام الأمان يقلّل استهلاك المحرّك للوقود",correct:!1},{text:"لا حاجة إليه، لأن قضيب الحماية وحده يكفي",correct:!1}],explanation:"لا يحمي قضيب الحماية إلا المساحة المحيطة بالمقعد. ومن دون حزام الأمان قد يُقذَف السائق خارجًا ويسحقه الجرّار."},{question:"ماذا يجب أن تفعل قبل فكّ انسداد آلة تعمل بعمود نقل الحركة (PTO)؟",options:[{text:"أطفئ المحرّك وانتظر حتى تتوقّف جميع الأجزاء",correct:!0},{text:"خفّف سرعة المحرّك وأبقِ يديك قرب الواقي",correct:!1},{text:"انزع الواقي لتصل إلى موضع الانسداد بسهولة",correct:!1},{text:"اطلب من طفل مراقبة العمود والصراخ إذا تسارع",correct:!1}],explanation:"قد يعلق العمود الدوّار بالملابس أو الشعر في لحظة. أطفئ المحرّك، وانتظر حتى يتوقّف كل شيء، وأبقِ جميع الواقيات في أماكنها."},{question:"أثناء الحراثة تكشف جسمًا معدنيًا صدئًا يشبه قذيفة قديمة. ماذا تفعل؟",options:[{text:"أوقف العمل، وأبعِد الجميع، وأبلغ عنه على الرقم 115",correct:!0},{text:"أحمله إلى طرف الحقل كي يستمر العمل",correct:!1},{text:"أحرث حوله، لأن القذيفة القديمة الصدئة لا تنفجر",correct:!1},{text:"أطرقه بالمجرفة لأتأكّد هل هو فارغ من الداخل",correct:!1}],explanation:"قد تنفجر الذخائر القديمة والصدئة إذا حُرّكت أو طُرقت. لا تلمسها: أوقف العمل، وأبعِد الجميع، وابتعد كثيرًا قبل استخدام الهاتف، ثم أبلغ عنها."}],media:[{kind:"image",src:"media/images/w8_farm_safety.webp",title:"عمل آمن في المزرعة",description:"مزارع يربط حزام الأمان ويقود جرّارًا مزوّدًا بقضيب حماية، بينما يراقبه أطفاله من خلف سياج الفناء؛ والمبيدات في عبواتها التي تحمل الملصقات داخل مخزن مقفل."}]},{id:29,icon:"Mountain",accent:"#15803d",title:"النزهات والرحلات الجبلية",subtitle:"النزهات والشواء والمشي والتخييم من دون حرائق أو سقوط أو ضياع",summary:"تستمتع أسر كثيرة بالنزهات والمشي والتخييم في الجبال والوديان في الربيع والصيف. ويمكن منع معظم الحوادث في الخلاء بقليل من التخطيط: نار أُشعلت في المكان الخطأ، أو سقوط عن الصخور، أو شخص يضيع، أو لدغة أفعى أو لسعة عقرب، أو سيل مفاجئ، أو عاصفة. يوضّح هذا الدرس كيف تخطّط لرحلة آمنة، وماذا تفعل إذا وقع مكروه بعيدًا عن المساعدة.",blocks:[{heading:"قبل أن تنطلق",points:["أخبر شخصًا لن يرافقك إلى أين تذهب، وأيّ طريق ستسلك، ومتى ستعود. واطلب منه أن يطلب المساعدة إذا لم تعد في الوقت المحدد.","تحقّق من توقّعات الطقس للمكان الذي تقصده، لا لمدينتك فقط، وغيّر خطتك إذا توقّعت الأرصاد عواصف أو أمطارًا غزيرة.","خذ معك ما يكفي من ماء الشرب، والطعام، وهاتفًا مشحونًا، ومصباحًا يدويًا، وحقيبة إسعافات أولية، وملابس دافئة، وصافرة لكل شخص، ولا سيما الأطفال.","التزم بالطرق والمسالك التي يكثر استخدامها. ففي المناطق التي شهدت قتالًا قد تخفي الطرق المهجورة والأراضي التي نمت فيها الأعشاب ألغامًا أو ذخائر متفجّرة: احترم كل علامة تحذير (انظر درس «الألغام والذخائر غير المنفجرة: ابقَ آمنًا»).","ابقوا معًا كمجموعة دائمًا، وأبقِ الأطفال حيث تستطيع رؤيتهم."]},{heading:"نار النزهة والشواء",points:["لا تُشعل نارًا أو شواءً إلا حيث يُسمح بذلك. واسأل عن القواعد المحلية قبل أن تنطلق.","لا تُشعل النار أبدًا على عشب جاف أو في يوم جاف عاصف. نظّف ما حولها من العشب والأوراق الجافة مسافة 3 أمتار (10 أقدام) على الأقل، وأبقِها على بُعد 8 أمتار (25 قدمًا) على الأقل من الأشجار والخيام والسيارات وكل ما يمكن أن يحترق.","أبقِ النار صغيرة ولا تتركها وحدها أبدًا، ولو لبضع دقائق. أبقِ الأطفال على بُعد متر واحد (3 أقدام) منها على الأقل، ولا تستعمل البنزين أو أيّ وقود آخر لإشعالها أو إحيائها أبدًا.","أبقِ قربك ماءً، أو مجرفة وترابًا. وقبل المغادرة صُبّ الماء على كل الجمر، وقلّبه، ثم صُبّ الماء مرة أخرى، حتى لا تبقى حرارة أو توهّج أو لهب أو دخان.","لا تُدخل أبدًا موقد الشواء أو نار الفحم أو الجمر الساخن إلى خيمة أو سيارة أو منزل، حتى للتدفئة: فقد يسبّب حريقًا أو تسمّمًا بأول أكسيد الكربون (CO) القاتل."]},{heading:"إذا ضعت",body:`قد يستغرق الإنقاذ ساعات، لذا اجعل العثور عليك سهلًا:

1. توقّف وحافظ على هدوئك. ابقَ في مكانك: فالحركة تجعل عثور المنقذين عليك أصعب. لا تتحرّك إلا إذا كنت في خطر مباشر، كمياه ترتفع أو نار.
2. ابقوا معًا؛ لا يذهب أحد وحده للبحث عن الطريق.
3. إذا توفّرت تغطية للهاتف، فاتصل بالرقم 115 وقل من أين انطلقت، وآخر مكان عرفت أنك فيه، وما تراه حولك، وكم عددكم، وهل هناك مصاب أو مريض. وأرسل موقعك من هاتفك إن استطعت.
4. انفخ في الصافرة ثلاث مرات، ثم استرح وكرّر: فصوت الصافرة يصل أبعد من صوتك ويوفّر جهدك. ارتدِ ملابس زاهية الألوان أو افرشها كي تُرى.
5. ابحث عن مأوى من الشمس أو المطر أو البرد، وانتظر المساعدة. ولا تُشعل نارًا إذا كان هناك أيّ خطر لحريق غابات.

علّم الأطفال: إذا ضعت فابقَ في مكانك، و«عانق شجرة» (أو صخرة كبيرة)، وانفخ في صافرتك.`},{heading:"السقوط والصخور",points:["التزم بالمسلك وانتبه إلى موضع قدميك، ولا سيما قرب الجروف وعلى الأرض الزلقة.","لا تتسلّق الصخور قرب الشلالات والجداول: فرذاذ الماء والطحالب تجعلها زلقة، وقد سقط أناس هناك ولقوا حتفهم.","أبقِ الأطفال قريبين منك وراقبهم طوال الوقت قرب الحوافّ والمياه.","إذا سقط شخص وربما أُصيب رأسه أو رقبته أو ظهره، فلا تحرّكه إلا إذا كان المكان خطرًا. اتصل بالرقم 122، وأبقِه ثابتًا ودافئًا، وانتظر المساعدة."]},{heading:"الأفاعي والعقارب",points:["ارتدِ أحذية مغلقة أو جزمات وسراويل طويلة. لا تضع يديك تحت الحجارة أو في أكوام الحطب أو الجحور، وابتعد قدر الإمكان عن العشب الطويل وأكوام الأوراق.","انفض الأحذية والملابس والفراش قبل استعمالها.","لا تلمس الأفعى أبدًا، ولا تمسكها، ولا تحاول قتلها.","لدغة الأفعى: أبقِ المصاب هادئًا وثابتًا، وانزع الخواتم والساعات وكل ما هو ضيّق قبل أن يبدأ التورّم، وانقله إلى المستشفى بسرعة: اتصل بالرقم 122، ولا تدعه يقود بنفسه. لا تجرح موضع اللدغة، ولا تمصّه، ولا تربط رباطًا ضاغطًا، ولا تضع عليه الثلج، ولا تستعمل العلاجات الشعبية.","لسعة العقرب: أبقِ المصاب هادئًا. يمكنك وضع كيس بارد ملفوف بقطعة قماش على موضع اللسعة، لكن لا تغمر الطرف في ماء مثلّج، ولا تعطه أيّ دواء. اطلب المساعدة الطبية لكل لسعة، واتصل بالرقم 122 فورًا إذا ظهرت عليه صعوبة في التنفّس، أو ارتعاش في العضلات، أو سيلان اللعاب، أو ثقل في الكلام، أو تململ غير طبيعي."]},{heading:"السيول والبرق والحرّ",points:["لا تخيّم ولا تتنزّه ولا توقف سيارتك أبدًا في مجرى نهر جاف أو في أرض منخفضة بجانب جدول: فقد يأتي السيل المفاجئ خلال دقائق، حتى لو هطل المطر بعيدًا عنك. وإذا بدأ الماء يرتفع فاصعد فورًا إلى مكان أعلى.","لا تمشِ ولا تقُد أبدًا في مياه جارية (انظر درس «الفيضانات: دليل للعائلات»).","إذا دوّى الرعد فادخل إلى مكان مغلق: لا يوجد مكان آمن في الخارج. احتمِ في مبنى متين أو في سيارة ذات سقف معدني؛ فالخيمة أو مظلّة النزهة لا توفّر أيّ حماية. وانتظر 30 دقيقة بعد آخر رعد.","إن لم تستطع الوصول إلى ملجأ، فابتعد عن قمم التلال والحواف الجبلية والأراضي المكشوفة والأشجار العالية المنفردة والمياه والأسوار المعدنية، وتفرّقوا إذا كنتم مجموعة.","خذ ماءً كثيرًا، واسترح في الظل، وتجنّب المشي الشاقّ في أشدّ ساعات الحرّ. والتشوّش أو الانهيار في الحرّ قد يكون ضربة شمس: اتصل بالرقم 122 وبرّد المصاب فورًا (انظر درس «السلامة في فصل الصيف»)."]}],tips:["أخبر أحدًا إلى أين تذهب ومتى ستعود.","أعطِ كل طفل صافرة وعلّمه أن يبقى في مكانه إذا ضاع.","لا تُشعل النار إلا حيث يُسمح بذلك، وأطفئها تمامًا بالماء قبل المغادرة.","انفض الأحذية والملابس قبل ارتدائها.","تحقّق من توقّعات الطقس للمكان الذي تقصده، وعُد أدراجك إذا اقتربت عاصفة."],warnings:["لا تترك نارًا أو شواءً مشتعلًا أبدًا، ولا تُشعلهما أبدًا على عشب جاف أو في يوم عاصف.","لا تُدخل أبدًا موقد الشواء أو الجمر الساخن إلى خيمة أو سيارة أو منزل.","لا تخيّم ولا توقف سيارتك أبدًا في مجرى نهر جاف أو بجانب جدول حين يُحتمل هطول المطر."],activity:{prompt:"تمشي في الجبال مع صديقين وتكتشف أنكم أضعتم المسلك. ستغرب الشمس بعد ساعتين، وتغطية هاتفك ضعيفة. ماذا تفعل؟",options:[{text:"نتوقّف ونبقى معًا في مكاننا، ونتصل بالرقم 115 ونذكر آخر موقع عرفناه وما نراه حولنا، وننفخ في الصافرة من حين إلى آخر.",correct:!0,feedback:"البقاء في مكان واحد يسهّل على المنقذين العثور عليكم، والاتصال بمعلومات واضحة عن الموقع وصافرة يصل صوتها بعيدًا يساعدانهم على الوصول إليكم."},{text:"نتفرّق لنبحث عن المسلك في اتجاهات مختلفة ثم نلتقي لاحقًا.",correct:!1,feedback:"التفرّق قد يحوّل مجموعة ضائعة واحدة إلى عدة أشخاص ضائعين. ابقوا معًا وابقوا في مكانكم."},{text:"ننزل المنحدر بأسرع ما نستطيع، حتى بعد حلول الظلام، إلى أن نجد طريقًا.",correct:!1,feedback:"المشي السريع على أرض مجهولة في الظلام قد يسبّب السقوط، والحركة تجعل العثور عليكم أصعب. توقّفوا واطلبوا المساعدة وانتظروا."},{text:"نُشعل نارًا كبيرة في العشب الجاف ليرى الناس الدخان.",correct:!1,feedback:"النار في العشب الجاف قد تنتشر وتحاصركم. أشيروا بالصافرة أو بالضوء أو بالملابس الزاهية، واتصلوا بالرقم 115."}]},quiz:[{question:"متى يمكنك ترك نار النزهة والمغادرة؟",options:[{text:"حين تُغمر بالماء وتُقلَّب ولا تبقى فيها حرارة ولا دخان",correct:!0},{text:"حين يخبو اللهب ولا يبقى سوى الجمر الأحمر",correct:!1},{text:"حين يُغطّى الحطب المشتعل بطبقة من الأوراق الجافة",correct:!1},{text:"حين تتغيّر الريح وتحمل الدخان بعيدًا عنك",correct:!1}],explanation:"قد يبقى الجمر ساخنًا ساعات، وقد تحمله الريح إلى العشب الجاف. صُبّ الماء على كل الجمر، وقلّبه، وصُبّ الماء مرة أخرى، وتأكّد من عدم بقاء حرارة أو توهّج أو لهب أو دخان."},{question:"ضاعت أسرتك في الجبل. ما أفضل ما تفعلونه؟",options:[{text:"ابقوا معًا في مكانكم، واتصلوا بالرقم 115، وانفخوا في الصافرة",correct:!0},{text:"امشوا بسرعة في اتجاه واحد حتى تصلوا إلى طريق أو قرية",correct:!1},{text:"أرسلوا الأطفال الأكبر وحدهم أمامكم للبحث عن المسلك",correct:!1},{text:"واصلوا الصعود إلى أعلى نقطة للتلويح، حتى بعد حلول الظلام",correct:!1}],explanation:"الحركة تجعل عثور المنقذين عليكم أصعب وقد تسبّب السقوط. ابقوا معًا في مكانكم، واتصلوا بالرقم 115 واذكروا آخر موقع عرفتموه، وأشيروا بالصافرة."},{question:"لدغت أفعى شخصًا في ساقه. ماذا يجب أن تفعل؟",options:[{text:"أبقِه ثابتًا، وانزع ما هو ضيّق، وانقله إلى المستشفى بسرعة",correct:!0},{text:"اجرح موضع اللدغة ومُصّ السمّ قبل الذهاب إلى المستشفى",correct:!1},{text:"اربط رباطًا ضاغطًا فوق اللدغة وضع الثلج على الجرح",correct:!1},{text:"دعه يمشي إلى البيت بسرعة وعالج اللدغة بوصفة منزلية",correct:!1}],explanation:"الثبات يبطّئ انتشار السمّ، والعلاج في المستشفى هو ما ينفع. أما الجرح والمصّ والأربطة الضاغطة والثلج والعلاجات الشعبية فلا تزيد إلا الضرر."},{question:"يُتوقّع هطول المطر في الجبال. ما أخطر مكان لنصب خيمتك؟",options:[{text:"في مجرى نهر جاف أو في أرض منخفضة بجانب جدول",correct:!0},{text:"على أرض مستوية مرتفعة بعيدة عن الماء",correct:!1},{text:"بجانب سيارتك في موقف حصوي على أرض مرتفعة",correct:!1},{text:"في مخيّم على سفح تلّ، أعلى بكثير من قاع الوادي",correct:!1}],explanation:"قد يملأ السيل المفاجئ مجرى النهر الجاف خلال دقائق، حتى لو هطل المطر بعيدًا. خيّم وتنزّه في الأماكن المرتفعة، واصعد فورًا إذا بدأ الماء يرتفع."},{question:"يبدأ الرعد بينما أنت في المخيّم. ما أكثر الأماكن أمانًا؟",options:[{text:"داخل مبنى متين أو سيارة ذات سقف معدني",correct:!0},{text:"داخل خيمتك مع إغلاق بابها بإحكام",correct:!1},{text:"تحت أعلى شجرة منفردة في الحقل",correct:!1},{text:"على قمة التلّ حيث يمكنك مراقبة العاصفة",correct:!1}],explanation:"لا يوجد مكان آمن في الخارج أثناء العاصفة الرعدية، والخيمة لا توفّر أيّ حماية. اذهب إلى مبنى متين أو سيارة ذات سقف صلب، وابقَ فيه حتى تمرّ 30 دقيقة على آخر رعد."}],media:[{kind:"image",src:"media/images/w8_outdoor_safety.webp",title:"نزهة عائلية آمنة في الجبال",description:"أسرة تتنزّه على أرض مرتفعة بعيدًا عن مجرى نهر جاف؛ يصبّ الأب الماء على جمر الشواء، بينما يبقى قربهم طفل يعلّق صافرة في رقبته."}]},{id:30,icon:"Construction",accent:"#a16207",title:"بعد انهيار مبنى: ما الذي يستطيع المواطن فعله",subtitle:"المساعدة الآمنة من الخارج، والإبلاغ عن المحاصَرين، وحماية نفسك إذا حوصرت",summary:"قد ينهار مبنى بعد زلزال أو انفجار، أو في حريق، أو لأنه قديم أو سيّئ البناء. وغالبًا ما يكون أول من يقدّم المساعدة هم الموجودون في المكان، قبل وصول فرق الإنقاذ. لكن غير المدرَّبين الذين يندفعون إلى داخل المباني المتضرّرة أو فوق الأنقاض كثيرًا ما يُصابون إصابات خطيرة، وقد مات بعضهم. يوضّح هذا الدرس ما يمكنك فعله بأمان من الخارج، وما تقوله عند الاتصال بالرقم 115، وكيف تحمي نفسك إذا حوصرت.",blocks:[{heading:"سلامتك أولًا",points:["لا تدخل أبدًا مبنى متضرّرًا ولا تصعد أبدًا فوق الأنقاض، حتى لإنقاذ أحد: فالأنقاض قد تتحرّك وتنهار، والهزّة الارتدادية قد تُسقط المزيد.","إذا كنت في مبنى متضرّر بعد توقّف الاهتزاز، فاخرج وابتعد عنه بسرعة إلى مكان مكشوف بعيد عن المباني والأشجار وأعمدة الإنارة وأسلاك الكهرباء.","علامات احتمال سقوط المبنى: أن يكون مائلًا أو انزاح عن أساسه، أو انهار جزء منه، أو ظهرت تشقّقات كبيرة في أساسه، أو تسمع صوت طقطقة أو أنين. أبعِد الجميع عنه.","توقّع حدوث الهزّات الارتدادية (Aftershock)، أحيانًا لأسابيع. إذا شعرت بإحداها: إن كنت في الداخل فانخفض، واحتمِ، وتمسّك (Drop, Cover, Hold On)، وإن كنت في الخارج فابقَ في المكان المكشوف.","إذا شممت رائحة الغاز، فلا تستخدم المفاتيح الكهربائية أو الولّاعات أو الهواتف قرب المبنى: ابتعد، ونبّه الآخرين، واتصل بالرقم 115 من مكان آمن. ولا تلمس أبدًا أسلاك الكهرباء الساقطة أو أيّ شيء يلامسها."]},{heading:"المساعدة من الخارج",points:["ساعد القادرين على المشي على الابتعاد عن المبنى إلى مكان مكشوف وآمن، وأبعِد المتفرّجين.","قدّم الإسعافات الأولية للمصابين الذين تستطيع الوصول إليهم دون دخول المبنى أو الصعود فوق الأنقاض، واتصل بالرقم 122. ولا تحرّك شخصًا قد تكون رقبته أو ظهره مصابين إلا إذا كان المكان خطرًا.","لا تسحب شخصًا محاصَرًا بالقوة، ولا ترفع قطع الأنقاض الثقيلة: فقد تسقط قطع أخرى عليه وعليك. اترك ذلك لفريق الإنقاذ المدرَّب.","لا تحفر في الأنقاض ولا تدخل الفجوات: فقد تنغلق في أيّ لحظة.","من مكان آمن، نادِ وأنصِت: «هل يسمعني أحد؟ اطرق أو نادِ.» وحدّد بدقة من أين يأتي أيّ صوت أو طرق.","حين يصل فريق الإنقاذ، أخبرهم بما تعرفه واتّبع تعليماتهم. ولا تساعد إلا إذا طلبوا منك ذلك."]},{heading:"الاتصال بالرقم 115: ماذا تقول",body:`اتصل بالرقم 115 (وبالرقم 122 للمصابين) من مكان آمن وقل:

1. المكان: المنطقة، والشارع، والمبنى، ومَعلم قريب؛ وأيّ جانب من المبنى وأيّ طابق.
2. ما حدث: انهيار، وأيّ حريق أو رائحة غاز أو أسلاك كهرباء ساقطة.
3. الأشخاص: كم شخصًا قد يكون محاصَرًا، وأين سمعت أصواتًا أو طرقًا، وكم عدد المصابين.
4. اسمك ورقم هاتفك. ولا تُغلق الخط حتى يُطلب منك ذلك.

حين يصل فريق الإنقاذ، أخبرهم مَن كان يسكن المبنى، ومن شوهد سالمًا، ومن لا يزال مفقودًا.`},{heading:"إذا حوصرت",body:`1. تحرّك أقلّ ما يمكن، كي لا تثير الغبار أو تُسقط المزيد من الحطام.
2. غطِّ أنفك وفمك بقطعة قماش أو بملابسك.
3. لا تُشعل عود ثقاب أو ولّاعة: فقد يكون هناك تسرّب غاز.
4. اطرق على أنبوب أو جدار، أو انفخ في صافرة، كي يعثر عليك المنقذون. وإذا كان هاتفك يعمل، فاتصل بالرقم 115 أو أرسل رسالة بموقعك.
5. لا تصرخ إلا كملاذ أخير: فالصراخ يجعلك تستنشق كميات خطرة من الغبار.

احتفظ بصافرة ومصباح يدوي قرب سريرك وفي حقيبة الطوارئ.`},{heading:"في الساعات والأيام التالية",points:["استعمل الرسائل النصية بدل المكالمات حين تستطيع، كي تبقى شبكة الهاتف متاحة لحالات الطوارئ.","أبقِ الشوارع خالية لسيارات الإسعاف والإنقاذ: لا تدخل المنطقة بسيارتك للمشاهدة.","لا يشارك الأطفال في رفع الأنقاض أو أعمال التنظيف.","لا تعد إلى مبنى متضرّر حتى يقول المهندسون أو الجهات المختصة إنه آمن.","اتّبع البيانات الرسمية للدفاع المدني والجهات المختصة، ولا تنشر الشائعات."]}],tips:["احتفظ بصافرة ومصباح يدوي قرب سريرك وفي حقيبة الطوارئ.","اتّفق مع أسرتك على نقطة تجمّع في الخارج بعيدًا عن المباني.","احفظ الرقمين 115 و122 في هاتفك، واعرف اسم شارعك والمعالم القريبة.","بعد الانهيار، نادِ وأنصِت من مكان آمن، وأخبر فريق الإنقاذ بدقة أين سمعت صوت شخص.","استعمل الرسائل النصية بعد الكارثة كي تبقى خطوط الهاتف متاحة."],warnings:["لا تدخل أبدًا مبنى متضرّرًا ولا تصعد فوق الأنقاض، حتى لإنقاذ أحد.","إذا شممت رائحة الغاز فلا تستخدم هناك المفاتيح الكهربائية أو الولّاعات أو الهواتف: ابتعد واتصل بالرقم 115 من مكان آمن.","لا تلمس أبدًا أسلاك الكهرباء الساقطة أو أيّ شيء يلامسها."],activity:{prompt:"بعد زلزال انهار جزء من منزل أحد الجيران. تسمع صوتًا ضعيفًا تحت الأنقاض، وبدأ عدة شبان يصعدون فوقها ليحفروا. ماذا تفعل؟",options:[{text:"أتصل بالرقم 115 وأذكر المكان بدقة وموضع الصوت، وأطلب من الشبان النزول وأُبعد الناس، وأواصل الحديث مع الشخص من مكان آمن.",correct:!0,feedback:"قد تتحرّك الأنقاض وقد تُسقط الهزّات الارتدادية المزيد. المعلومات الدقيقة تساعد فريق الإنقاذ، والحديث مع المحاصَر من مكان آمن يطمئنه دون تعريض مزيد من الناس للخطر."},{text:"أصعد معهم، لأن كل دقيقة مهمة والأيدي الكثيرة تحفر أسرع.",correct:!1,feedback:"الوزن الإضافي فوق الأنقاض قد يجعلها تنهار على المحاصَر وعلى من يحفرون. لا تصعد فوق الأنقاض واتصل بالرقم 115."},{text:"أسحب قطع الخرسانة الكبيرة من الحافة لأفتح طريقًا إلى الداخل.",correct:!1,feedback:"سحب القطع قد يُسقط الحطام الذي يسند الفراغ الذي يتنفّس فيه الشخص. اترك الحطام الثقيل للفريق المدرَّب."},{text:"أنتظر حتى الصباح لأبلّغ، لأن فرق الإنقاذ مشغولة الآن.",correct:!1,feedback:"يحتاج المحاصَرون إلى المساعدة في أقرب وقت ممكن. اتصل بالرقم 115 فورًا واذكر المكان بدقة."}]},quiz:[{question:"حوصرت تحت الحطام بعد زلزال. ماذا يجب أن تفعل؟",options:[{text:"غطِّ فمك، واطرق على أنبوب أو جدار أو استعمل صافرة",correct:!0},{text:"أشعل عود ثقاب لترى المكان من حولك",correct:!1},{text:"اصرخ بأعلى صوتك ومن دون توقّف حتى تصل المساعدة",correct:!1},{text:"ادفع الحطام فوقك بقوة لتفتح طريقًا للخروج بسرعة",correct:!1}],explanation:"اللهب قد يُشعل الغاز المتسرّب، والصراخ المتواصل يجعلك تستنشق الغبار، والدفع قد يُسقط المزيد من الحطام. الطرق والصافرة يساعدان المنقذين على العثور عليك؛ ولا تصرخ إلا كملاذ أخير."},{question:"ما أكثر الطرق أمانًا لكي يساعد المواطن بعد انهيار مبنى؟",options:[{text:"مساعدة الناس خارج المبنى والإبلاغ عن المحاصَرين على الرقم 115",correct:!0},{text:"دخول المبنى المتضرّر وتفتيش كل غرفه بحثًا عن ناجين",correct:!1},{text:"الصعود فوق الأنقاض ورفع القطع الثقيلة واحدة تلو الأخرى",correct:!1},{text:"قيادة سيارتك إلى داخل الشارع كي ترى ما يجري هناك",correct:!1}],explanation:"غير المدرَّبين الذين يدخلون المباني المتضرّرة أو يصعدون فوق الأنقاض كثيرًا ما يُصابون أو يموتون. ساعد من الخارج، وأبقِ الشوارع خالية لسيارات الإنقاذ، وأبلغ عن المحاصَرين على الرقم 115."},{question:"ما أول ما يجب أن تقوله للرقم 115 حين تبلّغ عن محاصَرين في انهيار؟",options:[{text:"المكان بدقة: المنطقة والشارع والمبنى ومَعلم قريب",correct:!0},{text:"رأيك في من بنى المبنى ولماذا انهار",correct:!1},{text:"أن شيئًا ما حدث في مكان ما من حيّك فقط",correct:!1},{text:"الأسماء الكاملة لكل من سكن المبنى في أيّ وقت",correct:!1}],explanation:"يجب أن تجد فرق الإنقاذ المكان بسرعة. اذكر المكان أولًا، ثم ما حدث، وكم شخصًا قد يكون محاصَرًا، وأين سمعتهم، وأيّ مخاطر، ولا تُغلق الخط حتى يُطلب منك ذلك."},{question:"لماذا يجب ألا يصرخ المحاصَر إلا كملاذ أخير؟",options:[{text:"لأن الصراخ يجعله يستنشق كميات خطرة من الغبار",correct:!0},{text:"لأن فرق الإنقاذ مدرَّبة على الإنصات لصوت الطرق فقط",correct:!1},{text:"لأن صوت الصراخ قد يُسقط الأنقاض التي فوقه",correct:!1},{text:"لأن الصراخ يستنزف بطارية الهاتف المحمول بسرعة",correct:!1}],explanation:"قد يؤذي الغبار في المبنى المنهار الرئتين، والصراخ يجعلك تستنشق المزيد منه. صوت الطرق على أنبوب أو جدار وصوت الصافرة يصلان جيدًا ويحميان تنفّسك."},{question:"تشمّ رائحة غاز قرب مبنى منهار. ماذا تفعل؟",options:[{text:"لا أستخدم هناك المفاتيح أو اللهب، وأبتعد وأتصل بالرقم 115",correct:!0},{text:"أدخل بسرعة وأغلق صمّام الغاز في المطبخ",correct:!1},{text:"أشعل أضواء الممرّ لأرى مكان التسرّب",correct:!1},{text:"أشعل ولّاعة قرب الأنابيب لأعرف من أين يتسرّب الغاز",correct:!1}],explanation:"الشرارة أو اللهب قد يُشعلان الغاز ويسبّبان انفجارًا. لا تدخل المبنى أبدًا للوصول إلى الصمّام: ابتعد، ونبّه الآخرين، واتصل بالرقم 115 من مكان آمن."}],media:[{kind:"image",src:"media/images/w8_collapse_citizen_help.webp",title:"مساعدة آمنة بعد الانهيار",description:"جيران يقفون بعيدًا عن منزل منهار جزئيًا؛ امرأة تتصل بالرقم 115 وتشير إلى المكان الذي سُمع منه صوت، بينما يساعد آخرون رجلًا مصابًا على الوصول إلى مكان مكشوف بعيد عن المباني وأسلاك الكهرباء."}]},{id:31,icon:"Users",accent:"#0f766e",title:"السلامة في التجمّعات المزدحمة",subtitle:"حفلات الأعراس والمهرجانات والمناسبات الدينية والملاعب والأسواق",summary:"حفلات الأعراس والمهرجانات والمناسبات الدينية والمباريات والأسواق المزدحمة تجمع أعدادًا كبيرة من الناس. وحين يتكدّس عدد كبير من الناس في مكان ضيّق، أو يندفع الجميع نحو نقطة واحدة، قد يُسحق الناس أو يُداسون. وفي كوارث الحشود يموت معظم الضحايا لأنهم يُضغطون بشدة حتى يعجزوا عن التنفّس. يوضّح هذا الدرس كيف تتعرّف مبكرًا على الحشد الخطر، وماذا تفعل إذا علقت فيه، وكيف تحمي الأطفال، وما الذي يجب على المنظّمين فعله.",blocks:[{heading:"عند وصولك",points:["ابحث عن جميع المخارج فور وصولك، وحدّد طريقين للخروج على الأقل: ففي حالة الطوارئ قد يكون الباب الذي دخلت منه مسدودًا.","تأكّد من أن المخارج غير مقفلة أو مربوطة بسلاسل أو مسدودة. وإذا لم يكن هناك طريقان للخروج على الأقل، فأبلغ المنظّمين، وغادر إذا لم تُعالَج المشكلة فورًا.","اعرف مكان نقطة الإسعافات الأولية، ونقطة الاستعلامات أو نقطة الأطفال التائهين إن وُجدت.","اتّفق مع أسرتك أو أصدقائك على نقطة تجمّع في حال افترقتم.","ابقَ قرب أطراف الحشد أو في الأماكن الأقل ازدحامًا، على أرض مستوية وجافة.","إذا شعرت بأن المكان مكتظّ أكثر من اللازم أو غير آمن، فغادر مبكرًا."]},{heading:"علامات الحشد الخطر",body:"غادر مبكرًا، ما دمت قادرًا على الحركة بحرّية، إذا لاحظت ما يلي:",points:["لم تعد هناك مسافة بينك وبين من حولك، ولا يزال مزيد من الناس يدفعون للدخول.","يبدأ الحشد بالتمايل أو الاندفاع على شكل موجات، وتُدفع إلى حيث لا تريد.","الناس يتدافعون أو يركضون، مثلًا نحو مدخل أو منصّة أو توزيع مجاني.","يُضغط الناس على الجدران أو الحواجز أو الأسوار.","يصبح التنفّس صعبًا."]},{heading:"إذا علقت في تدافع الحشد",points:["ارفع ذراعيك أمام صدرك، كالملاكم، لتحافظ على مساحة للتنفّس.","ابقَ واقفًا على قدميك: ثبّتهما جيدًا على الأرض وحاول ألا تسقط. ولا تنحنِ لالتقاط أيّ شيء.","لا تدفع عكس الحشد. وإذا توقّف من أمامك فلا تدفع: تماسك واطلب ممن خلفك أن يتماسكوا أيضًا.","حين يخفّ الضغط للحظة، تحرّك قُطريًا عبر الحشد نحو طرفه.","ابتعد عن الجدران والحواجز والأسوار، حيث يمكن أن يُسحق الناس.","إذا سقطت، فتكوّر على نفسك، واحمِ رأسك، وانهض بأسرع ما تستطيع. وإذا سقط شخص قربك، فاطلب ممن حولك أن يتماسكوا وساعده على النهوض."]},{heading:"الأطفال وكبار السن وذوو الاحتياجات الخاصة",points:["أبقِ الأطفال الصغار قريبين منك، وأمسك بأيديهم، وتأكّد من أن لديهم مساحة كافية.","ضع في جيب طفلك بطاقة تحمل اسمك ورقم هاتفك.","أرِ الأطفال نقطة التجمّع، وعلّمهم أن يذهبوا إليها إذا افترقوا عنك.","ابقَ مع كبار السن وذوي الاحتياجات الخاصة قرب أطراف الحشد وبالقرب من مخرج."]},{heading:"ما الذي يجب على المنظّمين فعله",points:["معرفة السعة الآمنة للمكان، بما في ذلك أماكن الاصطفاف والتجمّع والخروج، وعدم إدخال عدد من الناس يتجاوز ما يستوعبه المكان بأمان أبدًا.","إبقاء جميع المخارج غير مقفلة وجميع الطرق المؤدية إليها خالية طوال الفعالية؛ ويجب أن تُفتح أبواب الخروج من الداخل من دون مفتاح.","توفير عدد كافٍ من المشرفين المدرَّبين على تنظيم الحشود (Stewards) لتوجيه الناس، ومراقبة التدافع وتزايد الازدحام، وإيقاف الدخول حين تمتلئ منطقة ما.","التخطيط للإسعافات الأولية والمساعدة الطبية بحسب الحشد المتوقّع، والاتفاق مسبقًا مع الدفاع المدني وخدمة الإسعاف على طريقة وصولهم إلى المكان.","توفير نظام إذاعة داخلية وتعليمات طوارئ واضحة، والإبلاغ فورًا عن علامات تزايد خطر في الازدحام.","تنظيم الدخول والخروج بحيث لا يندفع الناس نحو نقطة واحدة، مثل بوابة وحيدة أو توزيع مجاني.","الالتزام بمتطلبات الدفاع المدني والجهات المحلية بشأن التصاريح وترتيبات السلامة."]},{heading:"إذا وقع طارئ",points:["إذا انطلق جرس الإنذار، أو رأيت دخانًا أو نارًا أو اضطرابًا مفاجئًا، فغادر بهدوء فورًا من أقرب مخرج.","تحرّك بسرعة الحشد؛ لا تركض ولا تدفع.","بعد خروجك، ابقَ في الخارج. اذهب إلى نقطة التجمّع وأخبر فرق الإنقاذ إذا كان هناك مفقود.","لا تنشر الشائعات؛ واتّبع تعليمات المشرفين على الحشود والدفاع المدني."]}],tips:["حدّد طريقين للخروج فور وصولك.","اتّفق مع أسرتك على نقطة تجمّع قبل الدخول.","ابقَ قرب أطراف الحشد، ولا سيما مع الأطفال.","غادر مبكرًا إذا ظلّ الحشد يكبر ولم تعد قادرًا على الحركة بحرّية.","ضع في جيب طفلك بطاقة تحمل رقم هاتفك."],warnings:["لا تدفع أبدًا في الحشد؛ وإذا توقّف من أمامك فتماسك واطلب ممن خلفك أن يتوقّفوا.","أيها المنظّمون: لا تقفلوا مخرجًا أو تسدّوه أبدًا ما دام الناس في الداخل.","لا تُدخل أبدًا عددًا من الناس يتجاوز ما يستوعبه المكان بأمان."],activity:{prompt:"في مهرجان مزدحم يندفع الحشد فجأة نحو المنصّة. تُدفع إلى الأمام ولا تكاد تستطيع تحريك ذراعيك. ماذا تفعل؟",options:[{text:"أرفع ذراعيّ أمام صدري، وأبقى واقفًا، ولا أدفع إلى الخلف، وحين يخفّ الضغط أتحرّك قُطريًا نحو الطرف.",correct:!0,feedback:"الذراعان أمام الصدر تحفظان مساحة للتنفّس، والبقاء واقفًا يحميك من أن تُداس، والتحرّك قُطريًا في لحظة هدوء يُخرجك من أشدّ الضغط."},{text:"أدفع بقوة من خلفي لأصنع مساحة أكبر.",correct:!1,feedback:"الدفع يزيد الضغط على الجميع وقد يُسقط الناس. لا تقاوم قوة الحشد؛ وانتظر لحظة هدوء."},{text:"أنحني لالتقاط هاتفي الذي سقط على الأرض.",correct:!1,feedback:"الانحناء أثناء التدافع قد يُسقطك فتُداس. ابقَ واقفًا واترك الهاتف."},{text:"أتحرّك نحو الحاجز في المقدّمة حيث أستطيع التمسّك بشيء.",correct:!1,feedback:"يُسحق الناس على الحواجز والجدران. ابتعد عنها، وتحرّك قُطريًا نحو طرف الحشد."}]},quiz:[{question:"لماذا يجب أن تحدّد مخرجين حين تصل إلى قاعة عرس أو ملعب؟",options:[{text:"لأن الباب الذي دخلت منه قد يكون مسدودًا في الطوارئ",correct:!0},{text:"لأن المنظّمين قد يطلبون منك الجلوس قرب أحد المخارج",correct:!1},{text:"لأن من اللياقة أن يعرف الضيوف مكان أبواب القاعة",correct:!1},{text:"لأن المخرج الثاني يكون دائمًا أقرب إلى موقف السيارات",correct:!1}],explanation:"في الطوارئ يتّجه معظم الناس إلى الباب الذي دخلوا منه، فقد ينسدّ بسرعة. ومعرفة طريق خروج ثانٍ تتيح لك المغادرة من أقرب مخرج آمن."},{question:"ماذا تفعل بذراعيك إذا علقت في تدافع الحشد؟",options:[{text:"أرفعهما أمام صدري، كالملاكم",correct:!0},{text:"أُرخيهما بجانبي لأشغل مساحة أقل",correct:!1},{text:"أرفعهما عاليًا فوق رأسي ليراني الناس",correct:!1},{text:"أستعملهما لأدفع من أمامي عن طريقي",correct:!1}],explanation:"الذراعان أمام الصدر تحفظان مساحة صغيرة للرئتين. ففي كوارث الحشود يموت معظم الضحايا لأنهم يُضغطون بشدة حتى يعجزوا عن التنفّس."},{question:"أثناء تدافع الحشد يخفّ الضغط للحظة. في أيّ اتجاه تتحرّك؟",options:[{text:"قُطريًا عبر الحشد نحو طرفه",correct:!0},{text:"إلى الخلف مباشرة عكس تيار الحشد",correct:!1},{text:"إلى الأمام نحو الحاجز في المقدّمة",correct:!1},{text:"إلى الأرض لأستريح حتى ينتهي",correct:!1}],explanation:"التحرّك قُطريًا نحو الطرف يُخرجك من أشدّ الضغط من دون مصارعة الحشد. أما الحواجز والأرض فهي حيث يُسحق الناس أو يُداسون."},{question:"أيّ مما يلي من واجبات منظّم حفل عرس كبير أو مهرجان؟",options:[{text:"إبقاء جميع المخارج غير مقفلة وخالية ما دام الضيوف في الداخل",correct:!0},{text:"إقفال الأبواب الجانبية كي لا يدخل أحد دون بطاقة دعوة",correct:!1},{text:"إدخال كل من يأتي، حتى بعد امتلاء القاعة",correct:!1},{text:"توزيع هدايا مجانية عند بوابة ضيّقة واحدة لإسعاد الضيوف",correct:!1}],explanation:"يجب أن تُفتح أبواب الخروج من الداخل من دون مفتاح، وأن تبقى الطرق إليها خالية. وعلى المنظّمين أيضًا الالتزام بالسعة الآمنة وتجنّب كل ما يدفع الناس إلى الاندفاع نحو نقطة واحدة."},{question:"ما الذي يساعد أكثر إذا افترق طفلك عنك في زحام؟",options:[{text:"نقطة تجمّع متّفق عليها مسبقًا وبطاقة تحمل رقم هاتفك",correct:!0},{text:"وعد بأنك ستبحث في كل زاوية من ساحة المهرجان",correct:!1},{text:"قاعدة بأن يمشي الطفل دائمًا وحده أمام الأسرة",correct:!1},{text:"خطة بأن يعود الطفل وحده بالحافلة إذا لم يجدك",correct:!1}],explanation:"نقطة تجمّع يعرفها الطفل وبطاقة تحمل رقم هاتفك تساعدان المشرفين وسائر الكبار على جمعكما بسرعة. ولا ينبغي أبدًا أن يغادر الطفل وحده."}],media:[{kind:"image",src:"media/images/w8_crowd_safety.webp",title:"البقاء آمنًا في الزحام",description:"أسر في مهرجان تقف قرب طرف الحشد بجانب مخرج مفتوح وواضح العلامات؛ مشرف على الحشد يرتدي سترة زاهية يوجّه الناس، وفي جيب أحد الأطفال بطاقة تحمل رقم هاتف أحد والديه."}]},{id:32,icon:"PlugZap",accent:"#a16207",title:"السلامة الكهربائية وسلامة البطاريات في المنزل",subtitle:"المقابس وأسلاك التمديد، والشواحن، والدراجات والسكوترات الكهربائية، وبطاريات الليثيوم أيون، والإسعافات الأولية للصعقة الكهربائية",summary:"في كل منزل أجهزة كهربائية كثيرة وبطاريات قابلة لإعادة الشحن: المقابس وأسلاك التمديد، وشواحن الهواتف، والشواحن المتنقلة (Power bank)، والدراجات والسكوترات الكهربائية. فالمقبس المحمَّل فوق طاقته، أو السلك التالف، أو البطارية المعطوبة قد يسبّب حريقًا، والصعقة الكهربائية قد تقتل. يشرح هذا الدرس كيف تستعملها بأمان، وكيف تتعرّف على علامات الخطر، وماذا تفعل إذا سخنت بطارية بشدة أو اشتعلت، وكيف تساعد شخصًا تعرّض لصعقة كهربائية.",blocks:[{heading:"المقابس وأسلاك التمديد والكابلات",points:["لا تحمّل المقابس أو أسلاك التمديد أو المقابس المتعددة فوق طاقتها: فكثرة الأجهزة على مقبس واحد قد تسخّنه وتسبّب حريقًا.","لا توصل أبدًا سلك تمديد أو مقبسًا متعددًا بآخر (التوصيل المتسلسل Daisy chaining).","أسلاك التمديد للاستعمال المؤقت فقط. وإذا كنت تحتاج إليها دائمًا، فاطلب من كهربائي مختص أن يتحقق هل يلزم تركيب مقابس إضافية.","صِل المدافئ والثلاجات والغسالات وغيرها من الأجهزة الكبيرة بمقبس الجدار مباشرةً، ولا تصلها أبدًا بسلك تمديد أو مقبس متعدد.","لا تمدّ الأسلاك تحت السجاد أو البُسط، ولا عبر المداخل، ولا حيث يمكن أن يسحقها الأثاث.","استبدل الأسلاك وأسلاك التمديد المتشققة أو التالفة، ولا تحاول إصلاحها بنفسك.","لا تلمس المقابس أو المفاتيح أو الأجهزة الكهربائية بيدين مبتلّتين."]},{heading:"علامات الخطر في المقابس والأسلاك",body:"إذا لاحظت أيًّا من هذه العلامات، فتوقّف عن استعمال المقبس أو الجهاز، وأطفئه وانزع قابسه إن كان ذلك آمنًا، واطلب من كهربائي مختص أن يكتشف السبب ويصلحه. وإذا كان هناك دخان أو نار، فأخرج الجميع وأغلق الباب واتصل بالرقم 115:",points:["مقابس أو مفاتيح دافئة أو متغيّرة اللون، أو قوابس تسخن.","رائحة احتراق أو بلاستيك ساخن قرب مقبس أو جهاز.","شرر، أو أزيز أو طقطقة، أو آثار احتراق حول المقبس أو القابس.","أضواء ترتعش، أو منصهرات (فيوزات) وقواطع كهربائية (Circuit breaker) تحترق أو تفصل مرارًا.","الإحساس بوخز خفيف عند لمس جهاز أو مغسلة معدنية."]},{heading:"الشواحن والدراجات والسكوترات الكهربائية",points:["تحتوي الهواتف والحواسيب المحمولة والشواحن المتنقلة والدراجات والسكوترات الكهربائية على بطاريات الليثيوم أيون (Li-ion). وهي تخزّن طاقة كبيرة، وقد تؤدي البطارية التالفة أو الشاحن غير المناسب إلى سخونتها الشديدة أو اشتعالها أو انفجارها.","استعمل الشاحن الذي جاء مع الجهاز أو شاحنًا توصي به الشركة المصنّعة. واشترِ الشواحن والبطاريات من بائعين موثوقين: فالنسخ الرخيصة قد لا تستوفي معايير السلامة.","اشحن على سطح صلب مستوٍ كالطاولة أو الأرض، ولا تشحن أبدًا على السرير أو الأريكة أو تحت الوسادة، حيث لا تجد الحرارة منفذًا.","لا تترك الأجهزة على الشحن وأنت نائم أو حين لا يكون أحد في المنزل، وانزع قابس الشاحن عندما تمتلئ البطارية.","اشحن الدراجات والسكوترات الكهربائية خارج المنزل إن أمكن. ولا تشحنها أو تضعها أبدًا في الممر أو قرب الباب الرئيسي أو على الدرج، حيث يسدّ الحريق طريق الخروج.","ركّب جهاز إنذار دخان في المكان الذي تشحن فيه الدراجات والسكوترات الكهربائية، واترك البطارية تبرد بعد الركوب قبل شحنها.","لا تستعمل بطارية تالفة، ولا بطارية عدّلها أو أصلحها شخص غير مختص."]},{heading:"بطارية تسخن بشدة أو يتصاعد منها الدخان أو تحترق",body:"علامات الخطر: تسخن البطارية بشدة، أو تنتفخ أو يتغيّر شكلها أو لونها، أو يتسرّب منها سائل، أو تنبعث منها رائحة غريبة، أو يصدر عنها فحيح أو طقطقة أو فرقعة، أو يتصاعد منها دخان. وحرائق بطاريات الليثيوم أيون تكبر بسرعة، ويصعب إطفاؤها، وينبعث منها دخان وغازات سامة.",points:["إذا لم يكن هناك دخان أو نار، فتوقّف عن استعمال البطارية فورًا. وإن كان ذلك آمنًا، فأطفئ الجهاز وانزع قابس الشاحن، ثم اسأل الشركة المصنّعة أو البائع عمّا يجب فعله.","إذا تصاعد الدخان من البطارية أو احترقت، فأخرج الجميع فورًا، وأغلق الباب خلفك، واتصل بالرقم 115 من الخارج. وابقَ في الخارج.","لا تحاول بنفسك إطفاء بطارية مشتعلة أو تبريدها ما لم تكن مدرّبًا: اترك ذلك لرجال الإطفاء.","لا ترمِ البطاريات القديمة أو التالفة مع نفايات المنزل، واسأل أين يمكن جمعها بأمان."]},{heading:"بعد الفيضانات والزلازل، وكابلات المولّدات الأهلية",points:["الكهرباء والماء معًا قد يقتلان: لا تلمس أبدًا المفاتيح أو المقابس أو الأجهزة الكهربائية وأنت مبتلّ أو واقف في الماء.","بعد الفيضان، أبقِ الكهرباء مفصولة حتى يفحص كهربائي مختص المنزل، وإن كان الوصول إلى المفتاح الرئيسي يتطلب أن تخطو في الماء فاتصل بكهربائي بدلًا من ذلك.","لا تستعمل الأجهزة الكهربائية أو الشواحن أو الدراجات والسكوترات الكهربائية التي غمرتها المياه حتى يفحصها شخص مختص.","بعد الزلزال، انتبه إلى أسلاك الكهرباء الساقطة والأسلاك التالفة وابتعد عنها مسافة كافية. واعتبر السلك الساقط وكل ما يلامسه موصولًا بالكهرباء، واتصل بالرقم 115.","إذا شممت رائحة غاز، فلا تشغّل أي مصباح أو جهاز ولا تطفئه: أخرج الجميع، ونبّه الجيران، واتصل بالرقم 115 من الخارج.","كابلات المولّدات الأهلية: لا تلمسها ولا توصل بها شيئًا بنفسك. أبلغ صاحب المولّدة عن الكابلات المرتخية أو التالفة أو الشرر أو رائحة الاحتراق، واتصل بالرقم 115 في الطوارئ. ولا يوصل منزلك بخط المولّدة الأهلية إلا كهربائي مختص."]},{heading:"الصعقة الكهربائية: الإسعافات الأولية",body:`1. لا تلمس المصاب ما دام قد يكون ملامسًا لمصدر كهربائي: فقد تُصعق أنت أيضًا.
2. اقطع التيار أولًا: انزع القابس أو أطفئ المفتاح الرئيسي في لوحة المنصهرات (الفيوزات)، إذا استطعت فعل ذلك بأمان.
3. إذا لم تستطع قطع التيار، أو كان الأمر يتعلق بخط ضغط عالٍ أو سلك كهرباء ساقط، فابتعد مسافة كافية، وأبعد الآخرين، واتصل بالرقمين 115 و122.
4. بعد قطع التيار، اتصل بالرقم 122. وإذا كان المصاب لا يتنفّس بصورة طبيعية، فابدأ الإنعاش القلبي الرئوي (CPR) (واكتفِ بالضغطات الصدرية إن لم تكن مدرّبًا)، واتّبع تعليمات موظف الطوارئ، واستعمل جهاز إزالة الرجفان الخارجي الآلي (AED) إن كان متوفرًا.
5. حتى لو بدا المصاب بخير، فراقبه واطلب المشورة الطبية من الرقم 122: فالصعقة الكهربائية قد تسبّب حروقًا عميقة وإصابات داخلية لا تُرى.`}],tips:["اعرف مكان المفتاح الرئيسي في منزلك (لوحة المنصهرات)، لكي تستطيع قطع التيار بسرعة وأمان.","صِل المدافئ وغيرها من الأجهزة الكبيرة بمقبس الجدار مباشرةً.","انزع قوابس الشواحن والأجهزة الصغيرة حين لا تستعملها.","ركّب جهاز إنذار دخان حيث تشحن الدراجات أو السكوترات الكهربائية، واختبر أجهزة إنذار الدخان في منزلك كل شهر.","اشترِ الشواحن والبطاريات وأسلاك التمديد من بائعين موثوقين، ولا تستعمل إلا الشاحن الذي توصي به الشركة المصنّعة."],warnings:["لا تلمس أبدًا شخصًا قد يكون ما زال ملامسًا للكهرباء: اقطع التيار أولًا.","لا تشحن أبدًا الدراجة أو السكوتر الكهربائي في الممر أو قرب الباب الرئيسي، ولا تتركه على الشحن والجميع نائمون.","إذا تصاعد الدخان من بطارية أو اشتعلت، فاخرج وأغلق الباب واتصل بالرقم 115، ولا تحاول إطفاءها بنفسك."],activity:{prompt:"الوقت متأخر في الليل. سكوتر ابنك الكهربائي موصول بالشاحن في الممر قرب الباب الرئيسي. تسمع فحيحًا من البطارية وتشمّ رائحة كيميائية قوية. ماذا تفعل؟",options:[{text:"أوقظ الجميع وأُخرجهم فورًا، ونغلق الأبواب خلفنا، وأتصل بالرقم 115 من الخارج؛ ولا يبقى أحد للتعامل مع السكوتر.",correct:!0,feedback:"الفحيح والرائحة الكيميائية علامتان على أن البطارية تتعطّل وقد تشتعل بسرعة كبيرة. وفي الممر يسدّ الحريق طريق الخروج، لذا فإن إخراج الجميع أولًا والاتصال بالرقم 115 هو التصرّف الصحيح."},{text:"أصبّ دلوًا من الماء على البطارية لتبريدها وأبقى بجانبها لأراقبها.",correct:!1,feedback:"لا تحاول بنفسك تبريد بطارية معطوبة أو إطفاءها ما لم تكن مدرّبًا: فقد تشتعل فجأة وتطلق دخانًا سامًّا. أخرج الجميع واتصل بالرقم 115."},{text:"أحمل السكوتر عبر الباب الرئيسي إلى الشارع حتى لا يشتعل المنزل.",correct:!1,feedback:"البطارية التي يصدر عنها فحيح قد تشتعل في أي لحظة: فحملها يعرّضك للخطر، والحريق في الممر يسدّ طريق الخروج. أخرج الجميع أولًا واتصل بالرقم 115."},{text:"أنزع قابس الشاحن، وأفتح نافذة، وأعود إلى النوم، ثم أفحص البطارية في الصباح.",correct:!1,feedback:"هذه علامات بطارية قد تشتعل. وتركها في الممر والجميع نائمون يعرّض الأسرة كلها للخطر: اخرج واتصل بالرقم 115."}]},quiz:[{question:"ما الطريقة الآمنة لاستعمال أسلاك التمديد والمقابس المتعددة في المنزل؟",options:[{text:"لمدة قصيرة فقط، ومن دون توصيلها أبدًا بسلك أو مقبس متعدد آخر",correct:!0},{text:"وصّل مقبسًا متعددًا ثانيًا بالأول كلما احتجت إلى مقابس أكثر في الغرفة",correct:!1},{text:"مرّر السلك تحت السجادة حتى لا يتعثّر به أحد في الغرفة",correct:!1},{text:"وصّل به المدفأة والثلاجة معًا لتوفير مقابس الجدار",correct:!1}],explanation:"أسلاك التمديد للاستعمال المؤقت. وتوصيل بعضها ببعض قد يحمّل المقبس فوق طاقته ويسبّب حريقًا، والأسلاك تحت السجاد قد تُسحق وتتلف، أما المدافئ والأجهزة الكبيرة فتوصل بمقبس الجدار مباشرةً."},{question:"ما أكثر الأماكن أمانًا لشحن الهاتف أو الشاحن المتنقل؟",options:[{text:"على سطح صلب مستوٍ كالطاولة، مع نزع القابس عند امتلاء البطارية",correct:!0},{text:"على السرير تحت الوسادة، حتى يبقى بعيدًا عن الطريق في الليل",correct:!1},{text:"على الأريكة طوال الليل، حتى تكون البطارية ممتلئة في الصباح",correct:!1},{text:"قرب المدفأة، لأن الهواء الدافئ يساعد البطارية على أن تُشحن بسرعة أكبر",correct:!1}],explanation:"الأسطح الليّنة كالسرير والوسادة والأريكة تحبس الحرارة، والبطارية التي لا تستطيع أن تبرد قد تسخن بشدة وتشتعل. اشحن على سطح صلب مستوٍ، ولا تشحن وأنت نائم، وانزع قابس الشاحن عندما تمتلئ البطارية."},{question:"أيّ مما يلي علامة على أن بطارية الليثيوم أيون تتعطّل؟",options:[{text:"تنتفخ أو تسخن بشدة أو يصدر عنها صوت فحيح",correct:!0},{text:"يستغرق شحنها وقتًا أطول قليلًا مما كان وهي جديدة",correct:!1},{text:"لون سلك الشاحن يختلف عن لون الجهاز نفسه",correct:!1},{text:"تخفت إضاءة شاشة الهاتف تلقائيًا في المساء",correct:!1}],explanation:"السخونة الشديدة، والانتفاخ أو تغيّر الشكل أو اللون، والتسرّب، والرائحة الغريبة، والفحيح أو الفرقعة، والدخان علامات خطر. توقّف عن استعمال البطارية فورًا، وإذا تصاعد منها الدخان أو احترقت فاخرج واتصل بالرقم 115."},{question:"بدأ الدخان يتصاعد من شاحن متنقل على الطاولة. ما التصرّف الصحيح؟",options:[{text:"أخرِج الجميع، وأغلق الباب، واتصل بالرقم 115 من الخارج",correct:!0},{text:"اسكب عليه كوبًا من الماء وابقَ بجانبه حتى تراه بعينك وقد انطفأ",correct:!1},{text:"ضعه في الثلاجة حتى يبرد بسرعة أكبر وبأمان",correct:!1},{text:"التقطه واحمله بسرعة إلى مغسلة المطبخ لتصبّ عليه الماء",correct:!1}],explanation:"حرائق بطاريات الليثيوم أيون تكبر بسرعة وتطلق دخانًا وغازات سامة. لا تحاول إطفاء بطارية مشتعلة أو تبريدها أو حملها ما لم تكن مدرّبًا: اخرج، وابقَ في الخارج، واتصل بالرقم 115 من الخارج."},{question:"بعد صعقة كهربائية، رجل ممدّد على الأرض وما زال ممسكًا بسلك جهاز. ماذا تفعل أولًا؟",options:[{text:"اقطع التيار من القابس أو المفتاح الرئيسي من دون أن تلمسه",correct:!0},{text:"اسحبه من ذراعه بعيدًا عن السلك بأسرع ما يمكنك",correct:!1},{text:"اسكب الماء على يديه لتبريد الحروق قبل أي شيء آخر",correct:!1},{text:"ابدأ الإنعاش القلبي الرئوي فورًا حتى وهو ما زال ممسكًا بالسلك",correct:!1}],explanation:"لا تلمس أبدًا شخصًا قد يكون ما زال ملامسًا للكهرباء: فقد تُصعق أنت أيضًا. اقطع التيار أولًا، ثم اتصل بالرقم 122، وابدأ الإنعاش القلبي الرئوي إذا كان لا يتنفّس بصورة طبيعية."}],media:[{kind:"image",src:"media/images/w8_home_electrical_battery.webp",title:"شحن آمن ومقابس سليمة في المنزل",description:"هاتف يُشحن على طاولة، وسكوتر كهربائي يُشحن خارج المنزل بعيدًا عن الباب، ومقبس جداري موصول به جهاز واحد فقط، وجهاز إنذار دخان على السقف."}]}],t={lessons:e};export{t as default,e as lessons};
